INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0001', 'be动词am用于I（我）之后：I''m = I am', 'be动词am用于I（我）之后：I''m = I am', '["I''m Lingling."]', '外研版', '三年级', '上册', 'Welcome', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0001');
