INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0009', '特殊疑问句 What''s this/that? 询问“这是什么/那是什么”，回答 It''s a/an + 名词', '特殊疑问句 What''s this/that? 询问“这是什么/那是什么”，回答 It''s a/an + 名词', '["What''s this? It''s a book."]', '外研版', '三年级', '上册', 'Unit 2', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0009');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0010', '一般疑问句 Is it…? 询问物品，肯定回答 Yes, it is. 否定回答 No, it isn''t.', '一般疑问句 Is it…? 询问物品，肯定回答 Yes, it is. 否定回答 No, it isn''t.', '["Is it a pen? No, it isn''t. It''s a pencil."]', '外研版', '三年级', '上册', 'Unit 2', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0010');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0011', '不定冠词 a/an：以元音音素开头的名词前用 an，其他用 a', '不定冠词 a/an：以元音音素开头的名词前用 an，其他用 a', '["a book, an eraser, a pencil"]', '外研版', '三年级', '上册', 'Unit 2', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0011');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0012', '祈使句（动词原形开头，表指令/建议）：Pack my pen. Pack my bag for school.', '祈使句（动词原形开头，表指令/建议）：Pack my pen. Pack my bag for school.', '["Pack my pencil case."]', '外研版', '三年级', '上册', 'Unit 2', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0012');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0013', '特殊疑问句 What colour is it? 询问颜色，回答 It''s + 颜色词', '特殊疑问句 What colour is it? 询问颜色，回答 It''s + 颜色词', '["What colour is it? It''s red!"]', '外研版', '三年级', '上册', 'Unit 3', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0013');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0014', '情态动词 can 表能力“能，会”，后接动词原形', '情态动词 can 表能力“能，会”，后接动词原形', '["What colours can you see? I can see a rainbow."]', '外研版', '三年级', '上册', 'Unit 3', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0014');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0015', '表达“想要某物”：I want + 名词', '表达“想要某物”：I want + 名词', '["I want a balloon."]', '外研版', '三年级', '上册', 'Unit 3', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0015');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0016', '颜色形容词的运用：red/pink/green/yellow/orange/blue/purple/black', '颜色形容词的运用：red/pink/green/yellow/orange/blue/purple/black', '["It''s yellow! It''s orange!"]', '外研版', '三年级', '上册', 'Unit 3', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0016');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0017', '特殊疑问句 How many…? 询问数量，后接可数名词复数', '特殊疑问句 How many…? 询问数量，后接可数名词复数', '["How many ropes? Only one rope!"]', '外研版', '三年级', '上册', 'Unit 4', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0017');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0018', '基数词 one~twelve 的认读与运用（计数）', '基数词 one~twelve 的认读与运用（计数）', '["One, two, three! Ten, eleven, twelve!"]', '外研版', '三年级', '上册', 'Unit 4', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0018');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0019', '特殊疑问句 What is it? 询问事物', '特殊疑问句 What is it? 询问事物', '["What is it? It''s beautiful!"]', '外研版', '三年级', '上册', 'Unit 4', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0019');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0020', '特殊疑问句 Who…? 询问人：Who can make a Chinese knot?', '特殊疑问句 Who…? 询问人：Who can make a Chinese knot?', '["Who can make a Chinese knot?"]', '外研版', '三年级', '上册', 'Unit 4', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0020');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0021', '特殊疑问句 Who is that? 询问人物身份，回答 That is / This is + 人物', '特殊疑问句 Who is that? 询问人物身份，回答 That is / This is + 人物', '["Who is that? That is my grandma."]', '外研版', '三年级', '上册', 'Unit 5', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0021');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0022', '指示代词 this（近指）与 that（远指）介绍人物', '指示代词 this（近指）与 that（远指）介绍人物', '["This is my dad. That is my grandma."]', '外研版', '三年级', '上册', 'Unit 5', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0022');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0023', '祈使句否定形式 Don''t + 动词原形', '祈使句否定形式 Don''t + 动词原形', '["Don''t worry! We can help!"]', '外研版', '三年级', '上册', 'Unit 5', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0023');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0024', '家庭称谓词：dad/mum/brother/sister/grandpa/grandma', '家庭称谓词：dad/mum/brother/sister/grandpa/grandma', '["This is my grandpa."]', '外研版', '三年级', '上册', 'Unit 5', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0024');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0025', '特殊疑问句 Where''s…? / Where is…? 询问位置，回答 主语+be+方位介词短语', '特殊疑问句 Where''s…? / Where is…? 询问位置，回答 主语+be+方位介词短语', '["Where''s Susu? She''s in the living room."]', '外研版', '三年级', '上册', 'Unit 6', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0025');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0026', '方位介词 in / on / under 表示位置', '方位介词 in / on / under 表示位置', '["She''s under the bed. Susu is in the box. On the chair."]', '外研版', '三年级', '上册', 'Unit 6', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0026');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0027', 'be动词与主语搭配描述位置：She''s in… / Susu is in…', 'be动词与主语搭配描述位置：She''s in… / Susu is in…', '["Susu is in the box."]', '外研版', '三年级', '上册', 'Unit 6', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0027');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0028', '确认多个事物的名称：Are they + 可数名词复数?', '确认多个事物的名称：Are they + 可数名词复数?', '["Are they tigers/pandas/elephants? 它们是老虎/熊猫/大象吗？"]', '外研版', '三年级', '下册', 'Unit 1', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0028');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0029', '描述事物特征：事物 + be动词(+not) + 形容词', '描述事物特征：事物 + be动词(+not) + 形容词', '["The panda is cute. 熊猫很可爱。/ Giraffes are not short. 长颈鹿不矮。"]', '外研版', '三年级', '下册', 'Unit 1', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0029');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0030', '询问多个事物名称：What are they? 答语 They are + 名词复数', '询问多个事物名称：What are they? 答语 They are + 名词复数', '["What are they? They are tigers."]', '外研版', '三年级', '下册', 'Unit 1', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0030');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0031', '介绍某人：This is + 人名', '介绍某人：This is + 人名', '["This is Linda. 这是琳达。"]', '外研版', '三年级', '下册', 'Unit 1', NULL, 4 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0031');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0032', '描述外形特征（肯定）：主语 + have/has got (+a/an/数词)(形容词) + 身体部位', '描述外形特征（肯定）：主语 + have/has got (+a/an/数词)(形容词) + 身体部位', '["I have got a nose. / You have got long hair. / He has got two ears."]', '外研版', '三年级', '下册', 'Unit 2', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0032');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0033', '描述外形特征（否定）：主语 + have/has not got ...', '描述外形特征（否定）：主语 + have/has not got ...', '["I haven''t got long hair. / He hasn''t got two ears."]', '外研版', '三年级', '下册', 'Unit 2', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0033');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0034', 'have got 与 has got 的区别：I/you/we/they用have got；he/she/it用has got；haven''t got=have not got，hasn''t got=has not got', 'have got 与 has got 的区别：I/you/we/they用have got；he/she/it用has got；haven''t got=have not got，hasn''t got=has not got', '["I have got... She has got..."]', '外研版', '三年级', '下册', 'Unit 2', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0034');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0035', '表达自己喜欢/不喜欢：I like + 事物 / I don''t like + 事物', '表达自己喜欢/不喜欢：I like + 事物 / I don''t like + 事物', '["I like apples. 我喜欢苹果。/ I don''t like apples. 我不喜欢苹果。"]', '外研版', '三年级', '下册', 'Unit 3', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0035');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0036', '第三人称单数表喜好：主语(三单) + likes + 事物；否定用 doesn''t + like', '第三人称单数表喜好：主语(三单) + likes + 事物；否定用 doesn''t + like', '["He likes apples. / He doesn''t like apples."]', '外研版', '三年级', '下册', 'Unit 3', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0036');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0037', '询问对方是否喜欢：Do you like + 事物? 答 Yes, I/We do. / No, I/We don''t.', '询问对方是否喜欢：Do you like + 事物? 答 Yes, I/We do. / No, I/We don''t.', '["Do you like apples? Yes, I do. / No, I don''t."]', '外研版', '三年级', '下册', 'Unit 3', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0037');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0038', '表达喜欢做某事：主语 + like(s) + 动词-ing 形式 (+其他)', '表达喜欢做某事：主语 + like(s) + 动词-ing 形式 (+其他)', '["I/We/You/They like singing. / He likes running.（Tips: like + 动词-ing）"]', '外研版', '三年级', '下册', 'Unit 4', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0038');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0039', '询问对方业余爱好：What do you like doing? 答 I/We like + 动词-ing', '询问对方业余爱好：What do you like doing? 答 I/We like + 动词-ing', '["What do you like doing? I like doing tai chi."]', '外研版', '三年级', '下册', 'Unit 4', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0039');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0040', '描述现在具体时间：It''s + 具体时间.', '描述现在具体时间：It''s + 具体时间.', '["It''s six o''clock. 六点钟。"]', '外研版', '三年级', '下册', 'Unit 5', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0040');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0041', '表达该做某事了：It''s time to + 动词(短语)原形 / It''s time for + 名词(短语)', '表达该做某事了：It''s time to + 动词(短语)原形 / It''s time for + 名词(短语)', '["It''s time to get up. / It''s time for school."]', '外研版', '三年级', '下册', 'Unit 5', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0041');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0042', '询问现在时间：What time is it? / What''s the time? 答 It''s + 具体时间.', '询问现在时间：What time is it? / What''s the time? 答 It''s + 具体时间.', '["What time is it? It''s one o''clock."]', '外研版', '三年级', '下册', 'Unit 5', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0042');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0043', '介绍今天是星期几：It''s + 星期.', '介绍今天是星期几：It''s + 星期.', '["It''s Monday. 今天星期一。"]', '外研版', '三年级', '下册', 'Unit 6', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0043');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0044', '介绍某星期有什么课：I/We have + 课程名称 + on + 星期.', '介绍某星期有什么课：I/We have + 课程名称 + on + 星期.', '["We have Chinese on Monday. 我们星期一有语文课。"]', '外研版', '三年级', '下册', 'Unit 6', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0044');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0045', '情态动词can表示"能力、会"：疑问句把can提到主语前，即"Can+主语+动词原形?"；肯定回答"Yes, 主语+can."，否定回答"No, 主语+can''t(=cannot)."。', '情态动词can表示"能力、会"：疑问句把can提到主语前，即"Can+主语+动词原形?"；肯定回答"Yes, 主语+can."，否定回答"No, 主语+can''t(=cannot)."。', '["Can you swim? Yes, I can. / No, I can''t."]', '外研版', '四年级', '上册', 'Unit 1', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0045');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0046', 'can后面必须接动词原形，且无人称和数的变化。', 'can后面必须接动词原形，且无人称和数的变化。', '["I can swim now. She can run fast."]', '外研版', '四年级', '上册', 'Unit 1', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0046');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0047', '祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。', '祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。', '["Don''t give up! Never stop!"]', '外研版', '四年级', '上册', 'Unit 1', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0047');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0048', '情态动词may表示请求许可："May I+动词原形…?"意为"我可以……吗？"，语气委婉。', '情态动词may表示请求许可："May I+动词原形…?"意为"我可以……吗？"，语气委婉。', '["Dad, may I play outside? Yes."]', '外研版', '四年级', '上册', 'Unit 2', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0048');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0049', '请求别人帮忙用"Can you+动词原形…?"，意为"你能……吗？"。', '请求别人帮忙用"Can you+动词原形…?"，意为"你能……吗？"。', '["Can you help me clean the floor?"]', '外研版', '四年级', '上册', 'Unit 2', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0049');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0050', '祈使句表指令或要求：以动词原形开头（tidy, clean, stop…）。', '祈使句表指令或要求：以动词原形开头（tidy, clean, stop…）。', '["Tidy your room first. Clean the floor."]', '外研版', '四年级', '上册', 'Unit 2', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0050');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0051', '询问天气用"What''s the weather like?"（天气怎么样？），回答用"It''s+描述天气的形容词."。', '询问天气用"What''s the weather like?"（天气怎么样？），回答用"It''s+描述天气的形容词."。', '["What''s the weather like? It''s sunny and warm."]', '外研版', '四年级', '上册', 'Unit 3', NULL, 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0051');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0052', '选择疑问句用or连接两个并列选项，不能用yes/no回答，要直接选择回答。', '选择疑问句用or连接两个并列选项，不能用yes/no回答，要直接选择回答。', '["Is it cold or hot? It''s cold."]', '外研版', '四年级', '上册', 'Unit 3', NULL, 2 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0052');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0053', '提建议用"Let''s+动词原形"（让我们……吧）。', '提建议用"Let''s+动词原形"（让我们……吧）。', '["Let''s go home! Let''s run!"]', '外研版', '四年级', '上册', 'Unit 3', NULL, 3 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0053');
