INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-001-001', 'en-repo-001', '1', 'I ___ Lingling.（我是玲玲。）', 'FillBlank', '{"id":"en-q-001-001","title":"I ___ Lingling.（我是玲玲。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Welcome","section":"重点语法与句型","knowledgePoint":["be动词am用于I（我）之后：I''m = I am"],"examAnalysis":"考查be动词am用于I之后的用法（Welcome语法点1）。主语是I（我）时，be动词必须用am；I am可以缩写为I''m。句中I是主语，所以填am。注意不能说I is或I are。","examCorrectAnswer":"am","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Welcome"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Welcome', '重点语法与句型', '["be动词am用于I（我）之后：I''m = I am"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-001-001');
