INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-001-002', 'en-repo-001', '2', 'What ___ your name?（你叫什么名字？）', 'FillBlank', '{"id":"en-q-001-002","title":"What ___ your name?（你叫什么名字？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Welcome","section":"重点语法与句型","knowledgePoint":["特殊疑问句 What''s your name? 询问姓名，回答用 My name is… 或 I''m…"],"examAnalysis":"考查特殊疑问句What''s your name?（Welcome语法点2）。What''s是What is的缩写，所以What后面用is。询问姓名用What is your name?，答句用My name is…或I''m…。","examCorrectAnswer":"is","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Welcome"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Welcome', '重点语法与句型', '["特殊疑问句 What''s your name? 询问姓名，回答用 My name is… 或 I''m…"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-001-002');
