INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-001-004', 'en-repo-001', '4', 'I am Lingling. 句中 I am 可以缩写为：I ___', 'FillBlank', '{"id":"en-q-001-004","title":"I am Lingling. 句中 I am 可以缩写为：I ___","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Welcome","section":"重点语法与句型","knowledgePoint":["be动词am用于I（我）之后：I''m = I am"],"examAnalysis":"考查I''m = I am的缩写（Welcome语法点1）。I am缩写成I''m，即I''m Lingling.（我是玲玲。）。注意缩写后中间有一个撇号，不能写成Im。","examCorrectAnswer":"I''m","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Welcome"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Welcome', '重点语法与句型', '["be动词am用于I（我）之后：I''m = I am"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-001-004');
