INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-001-011', 'en-repo-001', '11', '老师想让你们打开书，会说：___', 'Radio', '{"id":"en-q-001-011","title":"老师想让你们打开书，会说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Welcome","section":"重点语法与句型","knowledgePoint":["课堂指令祈使句（动词原形开头）：Stand up! Sit down! Open/Close your book!"],"examAnalysis":"考查课堂指令祈使句（Welcome语法点4）。''打开你们的书''是Open your book!，open是动词原形''打开''。B项Close your book!（合上你们的书）是相反指令；C项Stand up!（起立）、D项Sit down!（坐下）与书无关，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Open your book!","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Close your book!","attribute":{}},{"id":"c","title":"Stand up!","attribute":{}},{"id":"d","title":"Sit down!","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Welcome"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Welcome', '重点语法与句型', '["课堂指令祈使句（动词原形开头）：Stand up! Sit down! Open/Close your book!"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-001-011');
