INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-002-010', 'en-repo-002', '10', '下面哪个句子正确表达''让我们成为朋友吧''？', 'Radio', '{"id":"en-q-002-010","title":"下面哪个句子正确表达''让我们成为朋友吧''？","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["Let''s = let us，意为“让我们”，后接动词原形，表建议"],"examAnalysis":"考查Let''s + 动词原形（Unit 1语法点3）。Let''s后接动词原形，且friends用复数（双方互为朋友）。B项friend漏了复数-s；C项Let后应用us而不是we；D项Let''s后不能加to，故只有A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Let''s be friends!","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Let''s be friend!","attribute":{}},{"id":"c","title":"Let we be friends!","attribute":{}},{"id":"d","title":"Let''s to be friends!","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["Let''s = let us，意为“让我们”，后接动词原形，表建议"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-002-010');
