INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-002-011', 'en-repo-002', '11', '下列句子中哪一句是正确的？', 'Radio', '{"id":"en-q-002-011","title":"下列句子中哪一句是正确的？","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["be动词用法：I后用am，第三人称单数he/she后用is，we/they后用are"],"examAnalysis":"考查be动词与主语的搭配（Unit 1语法点1）：I用am，第三人称单数he/she用is，复数we/they用are。A项I后应用am；B项He后应用is；C项They后应用are；D项We are twins.正确，故选D。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"I are Sam.","attribute":{}},{"id":"b","title":"He am Daming.","attribute":{}},{"id":"c","title":"They is twins.","attribute":{}},{"id":"d","title":"We are twins.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["be动词用法：I后用am，第三人称单数he/she后用is，we/they后用are"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-002-011');
