INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-003-009', 'en-repo-003', '9', '下面哪个词组用 an 是正确的？', 'Radio', '{"id":"en-q-003-009","title":"下面哪个词组用 an 是正确的？","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["不定冠词 a/an：以元音音素开头的名词前用 an，其他用 a"],"examAnalysis":"考查不定冠词 a/an 的区别（Unit 2语法点3）。以元音音素开头的名词前用 an。eraser 以元音 /ɪ/ 开头，故 an eraser 正确。book、pencil、bag 都以辅音音素开头，前面用 a，故 C 正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"a book","attribute":{}},{"id":"b","title":"a pencil","attribute":{}},{"id":"c","title":"an eraser","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"a bag","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["不定冠词 a/an：以元音音素开头的名词前用 an，其他用 a"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-003-009');
