INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-004-008', 'en-repo-004', '8', '— What colour is it? — It''s ___.', 'Radio', '{"id":"en-q-004-008","title":"— What colour is it? — It''s ___.","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["特殊疑问句 What colour is it? 询问颜色，回答 It''s + 颜色词"],"examAnalysis":"考查 What colour is it? 的回答（Unit 3语法点1）。问句问颜色，应回答 It''s + 颜色词。A 项 blue（蓝色）是颜色，正确。B、D 是物品名词，C 是数词，均不回答颜色，排除。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"blue","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"a pen","attribute":{}},{"id":"c","title":"one","attribute":{}},{"id":"d","title":"a cat","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["特殊疑问句 What colour is it? 询问颜色，回答 It''s + 颜色词"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-004-008');
