INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-004-009', 'en-repo-004', '9', '在 What colours can you see? 中，can 后面的动词 see 用：___', 'Radio', '{"id":"en-q-004-009","title":"在 What colours can you see? 中，can 后面的动词 see 用：___","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["情态动词 can 表能力“能，会”，后接动词原形"],"examAnalysis":"考查情态动词 can 的用法（Unit 3语法点2）。can 是情态动词，后面必须接动词原形。B、C 是非谓语形式，D 是名词，均不能跟在 can 后，故 A 正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"动词原形","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"动词加 -ing","attribute":{}},{"id":"c","title":"动词加 -ed","attribute":{}},{"id":"d","title":"名词复数","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["情态动词 can 表能力“能，会”，后接动词原形"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-004-009');
