INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-004-010', 'en-repo-004', '10', 'I want ___ umbrella.', 'Radio', '{"id":"en-q-004-010","title":"I want ___ umbrella.","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["表达“想要某物”：I want + 名词"],"examAnalysis":"考查不定冠词 an 与 I want + 名词（Unit 3语法点3）。umbrella（雨伞）以元音音素 /ʌ/ 开头，前面用 an。A 项 a 用于辅音音素开头的词；C、D 是 be 动词，此处不需要，故 B 正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"a","attribute":{}},{"id":"b","title":"an","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"is","attribute":{}},{"id":"d","title":"are","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["表达“想要某物”：I want + 名词"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-004-010');
