INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-006-008', 'en-repo-006', '8', '— Who is that? — ___ my grandma.', 'Radio', '{"id":"en-q-006-008","title":"— Who is that? — ___ my grandma.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["特殊疑问句 Who is that? 询问人物身份，回答 That is / This is + 人物"],"examAnalysis":"考查 Who is that? 的回答（Unit 5语法点1）。问句问“那是谁”，回答用 That is…（那是……）。A 项 That is my grandma. 正确。B、D 项 be 动词搭配错误；C 项 I am 用于自我介绍，不能回答“那是谁”，故 A 正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"That is","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"It are","attribute":{}},{"id":"c","title":"I am","attribute":{}},{"id":"d","title":"You is","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["特殊疑问句 Who is that? 询问人物身份，回答 That is / This is + 人物"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-006-008');
