INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-006-009', 'en-repo-006', '9', '你想向同学介绍身边近处的爸爸，应该说：___', 'Radio', '{"id":"en-q-006-009","title":"你想向同学介绍身边近处的爸爸，应该说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["指示代词 this（近指）与 that（远指）介绍人物"],"examAnalysis":"考查 this 近指介绍人物（Unit 5语法点2）。介绍身边近处的人用 This is…（这是……）。A 项 This is my dad. 正确。B 项 that 指远处；C 项缺 my；D 项 be 动词错误，故 A 正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"This is my dad.","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"That is my dad.","attribute":{}},{"id":"c","title":"It is dad.","attribute":{}},{"id":"d","title":"He are dad.","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["指示代词 this（近指）与 that（远指）介绍人物"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-006-009');
