INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-006-010', 'en-repo-006', '10', '在 Don''t worry! 中，Don''t 后面接：___', 'Radio', '{"id":"en-q-006-010","title":"在 Don''t worry! 中，Don''t 后面接：___","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["祈使句否定形式 Don''t + 动词原形"],"examAnalysis":"考查否定祈使句 Don''t + 动词原形（Unit 5语法点3）。Don''t = Do not，后面必须接动词原形，表示“不要做某事”。B、C、D 都不能跟在 Don''t 后构成祈使句，故 A 正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"动词原形","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"动词加 -ing","attribute":{}},{"id":"c","title":"名词复数","attribute":{}},{"id":"d","title":"颜色词","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["祈使句否定形式 Don''t + 动词原形"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-006-010');
