INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-008-001', 'en-repo-008', '1', 'Are they ___?（它们是老虎吗？）', 'FillBlank', '{"id":"en-q-008-001","title":"Are they ___?（它们是老虎吗？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["确认多个事物的名称：Are they + 可数名词复数?"],"examAnalysis":"考查确认多个事物名称的句型 Are they + 可数名词复数?（Unit 1语法点1）。they（它们）指复数，后面的名词要用复数形式，tiger的复数是tigers，故填tigers。句意为''它们是老虎吗？''。相关规则：确认多个事物是否为某类动物时，用 Are they + 名词复数?，回答用 Yes, they are. / No, they aren''t.","examCorrectAnswer":"tigers","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["确认多个事物的名称：Are they + 可数名词复数?"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-008-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-008-001', 'en-kp-008-01', 'en-q-008-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-008-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-008-002', 'en-repo-008', '2', '— What ___ they? — They are monkeys.（— 它们是什么？— 它们是猴子。）', 'FillBlank', '{"id":"en-q-008-002","title":"— What ___ they? — They are monkeys.（— 它们是什么？— 它们是猴子。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["询问多个事物名称：What are they? 答语 They are + 名词复数"],"examAnalysis":"考查询问多个事物名称的句型 What are they?（Unit 1语法点3）。主语they是复数，be动词用are，即What are they?（它们是什么？）。相关规则：What are they? 用来问''它们是什么''，答语用 They are + 名词复数，如 They are tigers.（它们是老虎。）","examCorrectAnswer":"are","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["询问多个事物名称：What are they? 答语 They are + 名词复数"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-008-002');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-008-002', 'en-kp-008-02', 'en-q-008-002', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-008-002');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-008-003', 'en-repo-008', '3', 'The panda ___ cute.（熊猫很可爱。）', 'FillBlank', '{"id":"en-q-008-003","title":"The panda ___ cute.（熊猫很可爱。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["描述事物特征：事物 + be动词(+not) + 形容词"],"examAnalysis":"考查描述事物特征的句型 事物 + be动词 + 形容词（Unit 1语法点2）。主语The panda（这只熊猫）是单数，be动词用is，故填is。相关规则：描述单个事物的特征用 主语 + is + 形容词，如 The panda is cute.（熊猫很可爱。）","examCorrectAnswer":"is","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["描述事物特征：事物 + be动词(+not) + 形容词"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-008-003');
