INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-008-004', 'en-repo-008', '4', 'Giraffes are ___ short.（长颈鹿不矮。）', 'FillBlank', '{"id":"en-q-008-004","title":"Giraffes are ___ short.（长颈鹿不矮。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["描述事物特征：事物 + be动词(+not) + 形容词"],"examAnalysis":"考查描述事物特征的否定形式 be动词 + not + 形容词（Unit 1语法点2）。句意为''长颈鹿不矮''，在are后加not表示否定，故填not。相关规则：要表达''……不……''时，在be动词后面加not，如 Giraffes are not short.（长颈鹿不矮。）","examCorrectAnswer":"not","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["描述事物特征：事物 + be动词(+not) + 形容词"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-008-004');
