INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-008-005', 'en-repo-008', '5', 'This ___ Linda.（这是琳达。）', 'FillBlank', '{"id":"en-q-008-005","title":"This ___ Linda.（这是琳达。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["介绍某人：This is + 人名"],"examAnalysis":"考查介绍某人的句型 This is + 人名（Unit 1语法点4）。This（这，这个）是单数指示代词，后面be动词用is，即This is Linda.（这是琳达。）。相关规则：向别人介绍身边的人时，用 This is + 人名，不能用 He is/She is 代替这个介绍句型。","examCorrectAnswer":"is","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["介绍某人：This is + 人名"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-008-005');
