INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-008-010', 'en-repo-008', '10', 'The elephant ___ strong.', 'Radio', '{"id":"en-q-008-010","title":"The elephant ___ strong.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["描述事物特征：事物 + be动词(+not) + 形容词"],"examAnalysis":"考查描述事物特征时be动词与主语的搭配（Unit 1语法点2）。主语The elephant（这头大象）是单数，be动词用is。A项is正确。B项am只与I搭配；C项are用于复数主语；D项be是原形不能单独作谓语，故A正确。相关规则：单数主语用is，复数主语用are。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"is","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"am","attribute":{}},{"id":"c","title":"are","attribute":{}},{"id":"d","title":"be","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["描述事物特征：事物 + be动词(+not) + 形容词"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-008-010');
