INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-008-012', 'en-repo-008', '12', '— Are they lions? — No, ___.', 'Radio', '{"id":"en-q-008-012","title":"— Are they lions? — No, ___.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["确认多个事物的名称：Are they + 可数名词复数?"],"examAnalysis":"考查 Are they...? 的否定回答（Unit 1语法点1）。问句用 Are they 开头，否定回答用 No, they aren''t.（aren''t = are not）。A项 they aren''t 正确。B项 they don''t 用于Do开头的问句；C项 it isn''t 用于单数；D项 they are 是肯定回答，与No矛盾，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"they aren''t","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"they don''t","attribute":{}},{"id":"c","title":"it isn''t","attribute":{}},{"id":"d","title":"they are","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["确认多个事物的名称：Are they + 可数名词复数?"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-008-012');
