INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-009-012', 'en-repo-009', '12', 'She hasn''t got a dog. 中 hasn''t 的完整形式是：___', 'Radio', '{"id":"en-q-009-012","title":"She hasn''t got a dog. 中 hasn''t 的完整形式是：___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["have got 与 has got 的区别：I/you/we/they用have got；he/she/it用has "],"examAnalysis":"考查缩写形式 hasn''t = has not（Unit 2语法点3）。hasn''t 是 has not 的缩写。A项 has not 正确。B项 have not 的缩写是 haven''t；C项 is not 的缩写是 isn''t；D项 do not 的缩写是 don''t，均不对应，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"has not","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"have not","attribute":{}},{"id":"c","title":"is not","attribute":{}},{"id":"d","title":"do not","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["have got 与 has got 的区别：I/you/we/they用have got；he/she/it用has "]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-009-012');
