INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-009-013', 'en-repo-009', '13', '"怎么了？"用英语说：___', 'Radio', '{"id":"en-q-009-013","title":"\"怎么了？\"用英语说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["Unit 2 重点句型"],"examAnalysis":"考查本单元日常交际用语 What''s up?（Unit 2重点句子）。What''s up? 意思是''怎么了？/ 出什么事了？''。B项正确。A项 Good work! 是''干得不错！''；C项 Please stop! 是''请停下来！''；D项 You are right! 是''你说得对！''，均不符合，故B正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Good work!","attribute":{}},{"id":"b","title":"What''s up?","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"Please stop!","attribute":{}},{"id":"d","title":"You are right!","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["Unit 2 重点句型"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-009-013');
