INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-010-001', 'en-repo-010', '1', 'I ___ apples.（我喜欢苹果。）', 'FillBlank', '{"id":"en-q-010-001","title":"I ___ apples.（我喜欢苹果。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["表达自己喜欢/不喜欢：I like + 事物 / I don''t like + 事物"],"examAnalysis":"考查表达自己喜欢的句型 I like + 事物（Unit 3语法点1）。主语是I，动词用原形like，故填like。相关规则：表达''我喜欢……''用 I like + 事物，如 I like apples.（我喜欢苹果。）","examCorrectAnswer":"like","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["表达自己喜欢/不喜欢：I like + 事物 / I don''t like + 事物"]', 'easy', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-010-001');
