INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-010-003', 'en-repo-010', '3', 'He ___ apples.（他喜欢苹果。）', 'FillBlank', '{"id":"en-q-010-003","title":"He ___ apples.（他喜欢苹果。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["第三人称单数表喜好：主语(三单) + likes + 事物；否定用 doesn''t + like"],"examAnalysis":"考查第三人称单数表喜好（Unit 3语法点2）。主语He是第三人称单数，动词like要加-s，即likes，故填likes。相关规则：主语是第三人称单数（he/she/it）时，动词要加-s，如 He likes apples.（他喜欢苹果。）","examCorrectAnswer":"likes","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["第三人称单数表喜好：主语(三单) + likes + 事物；否定用 doesn''t + like"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-010-003');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-010-003', 'en-kp-010-02', 'en-q-010-003', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-010-003');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-010-004', 'en-repo-010', '4', 'He doesn''t ___ apples.（他不喜欢苹果。）', 'FillBlank', '{"id":"en-q-010-004","title":"He doesn''t ___ apples.（他不喜欢苹果。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["第三人称单数表喜好：主语(三单) + likes + 事物；否定用 doesn''t + like"],"examAnalysis":"考查第三人称单数的否定句（Unit 3语法点2）。否定借助 doesn''t（= does not），后面动词要用原形，故填like。相关规则：doesn''t 后面的动词必须用原形，不能再加-s，即 He doesn''t like apples.（他不喜欢苹果。）","examCorrectAnswer":"like","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["第三人称单数表喜好：主语(三单) + likes + 事物；否定用 doesn''t + like"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-010-004');
