INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-010-005', 'en-repo-010', '5', '— Do you like milk? — Yes, I ___.（— 你喜欢牛奶吗？— 是的，我喜欢。）', 'FillBlank', '{"id":"en-q-010-005","title":"— Do you like milk? — Yes, I ___.（— 你喜欢牛奶吗？— 是的，我喜欢。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["询问对方是否喜欢：Do you like + 事物? 答 Yes, I/We do. / No, I/We don''t."],"examAnalysis":"考查 Do you like...? 的肯定回答（Unit 3语法点3）。问句用Do开头，肯定回答用 Yes, I do.，故填do。相关规则：Do you like...? 的肯定回答是 Yes, I do.，否定回答是 No, I don''t.。","examCorrectAnswer":"do","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["询问对方是否喜欢：Do you like + 事物? 答 Yes, I/We do. / No, I/We don''t."]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-010-005');
