INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-010-007', 'en-repo-010', '7', 'What ___ some tea?（喝点茶怎么样？）', 'FillBlank', '{"id":"en-q-010-007","title":"What ___ some tea?（喝点茶怎么样？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["Unit 3 重点句型"],"examAnalysis":"考查本单元提建议的句型 What about...?（Unit 3重点句子）。What about...? 意思是''……怎么样？''，用来提建议或询问意见，故填about。相关规则：What about + 事物? 表示''……怎么样？''，如 What about some tea?（喝点茶怎么样？）","examCorrectAnswer":"about","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["Unit 3 重点句型"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-010-007');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-010-007', 'en-kp-010-04', 'en-q-010-007', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-010-007');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-010-008', 'en-repo-010', '8', 'I ___ like noodles.', 'Radio', '{"id":"en-q-010-008","title":"I ___ like noodles.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["表达自己喜欢/不喜欢：I like + 事物 / I don''t like + 事物"],"examAnalysis":"考查表达不喜欢的否定句（Unit 3语法点1）。主语是I，否定用 don''t like。B项 don''t 正确。A项 am not 是be动词否定，不与动词like搭配；C项 doesn''t 用于第三人称单数；D项 not 不能直接跟在I后面，故B正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"am not","attribute":{}},{"id":"b","title":"don''t","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"doesn''t","attribute":{}},{"id":"d","title":"not","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["表达自己喜欢/不喜欢：I like + 事物 / I don''t like + 事物"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-010-008');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-010-008', 'en-kp-010-01', 'en-q-010-008', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-010-008');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-010-009', 'en-repo-010', '9', 'She ___ like fish.', 'Radio', '{"id":"en-q-010-009","title":"She ___ like fish.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["第三人称单数表喜好：主语(三单) + likes + 事物；否定用 doesn''t + like"],"examAnalysis":"考查第三人称单数的否定句（Unit 3语法点2）。主语She是第三人称单数，否定用 doesn''t like。C项 doesn''t 正确。A项 don''t 用于I/you/we/they；B项 isn''t、D项 aren''t 是be动词否定，不与动词like搭配，故C正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"don''t","attribute":{}},{"id":"b","title":"isn''t","attribute":{}},{"id":"c","title":"doesn''t","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"aren''t","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["第三人称单数表喜好：主语(三单) + likes + 事物；否定用 doesn''t + like"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-010-009');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-010-009', 'en-kp-010-02', 'en-q-010-009', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-010-009');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-010-010', 'en-repo-010', '10', 'He ___ oranges.', 'Radio', '{"id":"en-q-010-010","title":"He ___ oranges.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["第三人称单数表喜好：主语(三单) + likes + 事物；否定用 doesn''t + like"],"examAnalysis":"考查第三人称单数表喜好（Unit 3语法点2）。主语He是第三人称单数，动词like要加-s，即likes。A项 likes 正确。B项 like 用于非第三人称单数；C项 is like 意思是''像……''，不是''喜欢''；D项 don''t like 主语应为非三单且与He不搭配，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"likes","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"like","attribute":{}},{"id":"c","title":"is like","attribute":{}},{"id":"d","title":"don''t like","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["第三人称单数表喜好：主语(三单) + likes + 事物；否定用 doesn''t + like"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-010-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-010-010', 'en-kp-010-02', 'en-q-010-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-010-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-010-011', 'en-repo-010', '11', '— Do you like juice? — No, ___.', 'Radio', '{"id":"en-q-010-011","title":"— Do you like juice? — No, ___.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["询问对方是否喜欢：Do you like + 事物? 答 Yes, I/We do. / No, I/We don''t."],"examAnalysis":"考查 Do you like...? 的否定回答（Unit 3语法点3）。问句用Do开头，否定回答用 No, I don''t.。C项 I don''t 正确。A项 I do 是肯定回答，与No矛盾；B、D项是be动词的否定，不用于do开头的问句，故C正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"I do","attribute":{}},{"id":"b","title":"I am not","attribute":{}},{"id":"c","title":"I don''t","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"I''m not","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["询问对方是否喜欢：Do you like + 事物? 答 Yes, I/We do. / No, I/We don''t."]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-010-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-010-011', 'en-kp-010-03', 'en-q-010-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-010-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-010-012', 'en-repo-010', '12', 'They ___ apples.', 'Radio', '{"id":"en-q-010-012","title":"They ___ apples.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["表达自己喜欢/不喜欢：I like + 事物 / I don''t like + 事物"],"examAnalysis":"考查主语为复数时动词用原形（Unit 3语法点1）。主语They（他们）是复数，动词用原形like。B项 like 正确。A项 likes 用于第三人称单数；C项 doesn''t like 用于第三人称单数否定；D项 is liking 形式错误，like不用于进行时，故B正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"likes","attribute":{}},{"id":"b","title":"like","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"doesn''t like","attribute":{}},{"id":"d","title":"is liking","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["表达自己喜欢/不喜欢：I like + 事物 / I don''t like + 事物"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-010-012');
