INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-013-012', 'en-repo-013', '12', '你觉得朋友的主意很好，应该说：___', 'Radio', '{"id":"en-q-013-012","title":"你觉得朋友的主意很好，应该说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["Unit 6 重点句型"],"examAnalysis":"考查赞同用语 Good idea!（Unit 6重点句子）。''好主意！''是 Good idea!，用于赞同别人的提议。A项正确。B项 Good work! 是''干得好！''；C项 Goodbye! 是告别；D项 Good morning! 是早晨问候，均不符合，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Good idea!","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Good work!","attribute":{}},{"id":"c","title":"Goodbye!","attribute":{}},{"id":"d","title":"Good morning!","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["Unit 6 重点句型"]', 'medium', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-013-012');
