INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-013-013', 'en-repo-013', '13', '朋友生病了，你祝他早日康复，应该说：___', 'Radio', '{"id":"en-q-013-013","title":"朋友生病了，你祝他早日康复，应该说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["Unit 6 重点句型"],"examAnalysis":"考查本单元祝福用语 Get well soon!（Unit 6重点句子）。''祝早日康复！''是 Get well soon!。C项正确。A项 Thank you so much! 是道谢；B项 Good idea! 是赞同；D项 You are right! 是赞同对方说得对，都不符合祝病人康复的场合，故C正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Thank you so much!","attribute":{}},{"id":"b","title":"Good idea!","attribute":{}},{"id":"c","title":"Get well soon!","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"You are right!","attribute":{}}]}', 'exam', '单元练习', '["外研版","三年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["Unit 6 重点句型"]', 'hard', '三年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-013-013');
