INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-001', 'en-repo-014', '1', 'Can you ___ high, Daming?（大明，你能跳得高吗？）', 'FillBlank', '{"id":"en-q-014-001","title":"Can you ___ high, Daming?（大明，你能跳得高吗？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"],"examAnalysis":"考查情态动词can表能力的一般疑问句Can+主语+动词原形?（Unit 1语法点1、语法点2）。原句为Can you jump high, Daming?，''跳''是jump，can后必须接动词原形，故填jump。相关规则：can是情态动词，疑问时把can提到主语前，后面的动词用原形，can本身无人称和数的变化。","examCorrectAnswer":"jump","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-001', 'en-kp-014-01', 'en-q-014-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-002', 'en-repo-014', '2', '— Can you run fast? — Yes, I ___.（— 你能跑得快吗？— 是的，我能。）', 'FillBlank', '{"id":"en-q-014-002","title":"— Can you run fast? — Yes, I ___.（— 你能跑得快吗？— 是的，我能。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"],"examAnalysis":"考查can引导一般疑问句的肯定回答（Unit 1语法点1）。问句Can you…?的肯定回答用Yes, 主语+can.，主语是I，故填can。相关规则：Can you…?问，就用Yes, I can. / No, I can''t.回答，不能用do/don''t或am。","examCorrectAnswer":"can","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-002');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-002', 'en-kp-014-01', 'en-q-014-002', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-002');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-003', 'en-repo-014', '3', 'Can you ___ ping-pong?（你会打乒乓球吗？）', 'FillBlank', '{"id":"en-q-014-003","title":"Can you ___ ping-pong?（你会打乒乓球吗？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["can后面必须接动词原形，且无人称和数的变化。"],"examAnalysis":"考查can后接动词原形（Unit 1语法点2）。原句为Can you play ping-pong?，play ping-pong意为''打乒乓球''，can后用动词原形play，故填play。相关规则：can是情态动词，后面必须跟动词原形，不受主语人称和数影响。","examCorrectAnswer":"play","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["can后面必须接动词原形，且无人称和数的变化。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-003');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-003', 'en-kp-014-02', 'en-q-014-003', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-003');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-004', 'en-repo-014', '4', 'No, I ___. But I can learn.（不，我不会。但我可以学。）', 'FillBlank', '{"id":"en-q-014-004","title":"No, I ___. But I can learn.（不，我不会。但我可以学。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"],"examAnalysis":"考查can引导一般疑问句的否定回答（Unit 1语法点1）。原句为No, I can''t. But I can learn.，can''t = cannot，意为''不能、不会''，故填can''t。相关规则：Can you…?的否定回答是No, 主语+can''t.，can''t后面同样接动词原形（如learn）。","examCorrectAnswer":"can''t","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-004');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-004', 'en-kp-014-01', 'en-q-014-004', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-004');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-005', 'en-repo-014', '5', 'She ___ swim fast.（她能游得很快。）', 'FillBlank', '{"id":"en-q-014-005","title":"She ___ swim fast.（她能游得很快。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["can后面必须接动词原形，且无人称和数的变化。"],"examAnalysis":"考查can无人称和数的变化（Unit 1语法点2）。can后面接动词原形swim，不管主语是I还是She，can形式都不变，故填can。相关规则：情态动词can没有人称和数的变化，第三人称单数主语后仍用can，不能写成cans。","examCorrectAnswer":"can","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["can后面必须接动词原形，且无人称和数的变化。"]', 'easy', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-005');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-005', 'en-kp-014-02', 'en-q-014-005', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-005');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-006', 'en-repo-014', '6', 'Don''t ___ up! Never stop!（不要放弃！决不停下！）', 'FillBlank', '{"id":"en-q-014-006","title":"Don''t ___ up! Never stop!（不要放弃！决不停下！）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。"],"examAnalysis":"考查否定祈使句（Unit 1语法点3）。原句出自Don''t give up! Never stop!，否定祈使句在句首加Don''t，后面接动词原形，''放弃''是give up，故填give。相关规则：祈使句肯定句以动词原形开头，否定句在句首加Don''t+动词原形。","examCorrectAnswer":"give","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-006');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-006', 'en-kp-014-03', 'en-q-014-006', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-006');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-007', 'en-repo-014', '7', 'Wow! You can ___ fast!（哇！你能游得很快！）', 'FillBlank', '{"id":"en-q-014-007","title":"Wow! You can ___ fast!（哇！你能游得很快！）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["can后面必须接动词原形，且无人称和数的变化。"],"examAnalysis":"考查can后接动词原形（Unit 1语法点2）。原句为Wow! You can swim fast!，''游泳''是swim，can后用原形，故填swim。相关规则：情态动词can表示能力时，后面必须接动词原形，不能加-ing或-s。","examCorrectAnswer":"swim","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["can后面必须接动词原形，且无人称和数的变化。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-007');
