INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-008', 'en-repo-014', '8', '— Dad, may I play outside? — ___', 'Radio', '{"id":"en-q-014-008","title":"— Dad, may I play outside? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["Unit 1 单元综合"],"examAnalysis":"考查May I…?请求许可的应答。题干问句虽用may，但对照本单元''Can/May I…?''类请求的回答逻辑，回答要针对''我能不能出去''作答；四个选项中只有C项Yes, I can.（是的，我能/可以）是肯定且结构正确的应答。A项用do回答情态动词问句、B项人称错（答句主语应为I而非you）、D项No与场合不符且用don''t，均排除。相关规则：请求许可类问句，答句要前后一致，肯定用Yes, I can/may.，否定用No, I can''t/may not.。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, you do.","attribute":{}},{"id":"b","title":"Yes, you may.","attribute":{}},{"id":"c","title":"Yes, I can.","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"No, I don''t.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["Unit 1 单元综合"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-008');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-008', 'en-kp-014-04', 'en-q-014-008', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-008');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-009', 'en-repo-014', '9', 'Can you ___ volleyball?', 'Radio', '{"id":"en-q-014-009","title":"Can you ___ volleyball?","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["can后面必须接动词原形，且无人称和数的变化。"],"examAnalysis":"考查can后接动词原形（Unit 1语法点2）。情态动词can后面必须接动词原形，''打排球''是play volleyball，故选A。B项plays是第三人称单数形式，C项playing是现在分词，D项to play是不定式，都不能直接跟在can后面。相关规则：can + 动词原形，无人称和数的变化。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"play","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"plays","attribute":{}},{"id":"c","title":"playing","attribute":{}},{"id":"d","title":"to play","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["can后面必须接动词原形，且无人称和数的变化。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-009');
