INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-010', 'en-repo-014', '10', 'She can ___ very high.', 'Radio', '{"id":"en-q-014-010","title":"She can ___ very high.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["can后面必须接动词原形，且无人称和数的变化。"],"examAnalysis":"考查can无人称和数的变化、后接动词原形（Unit 1语法点2）。主语是She（第三人称单数），但can没有形式变化，其后仍用动词原形jump，故选C。A项jumps是一般现在时第三人称单数形式，不能用于can后；B、D项同样不能跟在can后。相关规则：can表能力时无人称变化，can+动词原形。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"jumps","attribute":{}},{"id":"b","title":"jumping","attribute":{}},{"id":"c","title":"jump","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"to jump","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["can后面必须接动词原形，且无人称和数的变化。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-010');
