INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-011', 'en-repo-014', '11', '— Can you play ping-pong? — ___. But I can learn.', 'Radio', '{"id":"en-q-014-011","title":"— Can you play ping-pong? — ___. But I can learn.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"],"examAnalysis":"考查can一般疑问句的否定回答（Unit 1语法点1）。后一句But I can learn.（但我可以学）说明''不会打''，是否定回答，用No, I can''t.，故选D。A项Yes与后句转折矛盾；B项用do回答情态动词问句错误；C项No后面不能接can，前后矛盾。相关规则：Can you…?否定回答为No, I can''t.","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I can.","attribute":{}},{"id":"b","title":"Yes, I do.","attribute":{}},{"id":"c","title":"No, I can.","attribute":{}},{"id":"d","title":"No, I can''t.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-014-011', 'en-kp-014-01', 'en-q-014-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-014-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-012', 'en-repo-014', '12', '___ give up!（不要放弃！）', 'Radio', '{"id":"en-q-014-012","title":"___ give up!（不要放弃！）","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。"],"examAnalysis":"考查否定祈使句（Unit 1语法点3）。否定祈使句在动词原形前加Don''t，Don''t give up!意为''不要放弃！''，故选B。A项Not不能直接放在句首引导祈使句；C项Doesn''t用于第三人称单数的一般现在时否定，不用于祈使句；D项No后接名词或动名词，不能接动词原形give。相关规则：祈使句否定式 = Don''t + 动词原形。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Not","attribute":{}},{"id":"b","title":"Don''t","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"Doesn''t","attribute":{}},{"id":"d","title":"No","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["祈使句表鼓励或命令：肯定句以动词原形开头；否定句在句首加Don''t。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-012');
