INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-013', 'en-repo-014', '13', '下列句子中哪一句是正确的？', 'Radio', '{"id":"en-q-014-013","title":"下列句子中哪一句是正确的？","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["can后面必须接动词原形，且无人称和数的变化。"],"examAnalysis":"考查can后接动词原形（Unit 1语法点2）。can后面必须用动词原形，C项They can run fast.中run是原形，正确。A项can后用了swims、B项用了runs、D项用了playing，都违反''can+动词原形''规则。相关规则：情态动词can无人称和数的变化，其后一律接动词原形。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"She can swims fast.","attribute":{}},{"id":"b","title":"He can runs fast.","attribute":{}},{"id":"c","title":"They can run fast.","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"I can playing ping-pong.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["can后面必须接动词原形，且无人称和数的变化。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-013');
