INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-014-015', 'en-repo-014', '15', '— Can you swim fast? — Yes, ___.', 'Radio', '{"id":"en-q-014-015","title":"— Can you swim fast? — Yes, ___.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"],"examAnalysis":"考查can一般疑问句的肯定回答（Unit 1语法点1）。Can you…?的肯定回答是Yes, I can.，前面已有Yes，故选C。A项I am用于be动词问句；B项I do用于do引导的问句；D项I can''t是否定形式，与Yes矛盾。相关规则：用can问就用can答，Yes, 主语+can.","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"I am","attribute":{}},{"id":"b","title":"I do","attribute":{}},{"id":"c","title":"I can","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"I can''t","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["情态动词can表示\"能力、会\"：疑问句把can提到主语前，即\"Can+主语+动词原形?\"；肯定回答\"Yes, 主语+ca"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-014-015');
