INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-004', 'en-repo-015', '4', 'OK. That''s ___.（好的。那很容易。）', 'FillBlank', '{"id":"en-q-015-004","title":"OK. That''s ___.（好的。那很容易。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["Unit 2 重点句型"],"examAnalysis":"考查本单元重点句子OK. That''s easy.（Unit 2重点句子3）。easy意为''容易的、轻松的''，That''s easy.表示''那很容易''，故填easy。相关规则：That''s+形容词.用于评价某事''是……的''，这里形容做家务很简单。","examCorrectAnswer":"easy","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["Unit 2 重点句型"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-004');
