INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-007', 'en-repo-015', '7', 'Good ___!（干得好！）', 'FillBlank', '{"id":"en-q-015-007","title":"Good ___!（干得好！）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["Unit 2 重点句型"],"examAnalysis":"考查本单元夸赞用语Good job!（Unit 2重点句子5）。Good job!是固定搭配，意为''干得好！做得不错！''，故填job。相关规则：job在这里不是''工作''，与good搭配成口语表扬用语，不能说Good work thing!之类。","examCorrectAnswer":"job","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["Unit 2 重点句型"]', 'easy', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-007');
