INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-008', 'en-repo-015', '8', '— Dad, may I play outside? — ___. Here is your coat.', 'Radio', '{"id":"en-q-015-008","title":"— Dad, may I play outside? — ___. Here is your coat.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["情态动词may表示请求许可：\"May I+动词原形…?\"意为\"我可以……吗？\"，语气委婉。"],"examAnalysis":"考查May I…?请求许可的回答（Unit 2语法点1）。May I…?问，对方同意时可说Yes, you may.（是的，你可以），后句''这是你的外套''说明同意了，故选B。A项用do回答情态动词may错误；C项人称应为you而非I；D项No与同意的语境矛盾且用don''t。相关规则：May I…?肯定回答Yes, you may. / Yes.，否定回答No, you can''t.。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, you do.","attribute":{}},{"id":"b","title":"Yes, you may.","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"Yes, I can.","attribute":{}},{"id":"d","title":"No, I don''t.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["情态动词may表示请求许可：\"May I+动词原形…?\"意为\"我可以……吗？\"，语气委婉。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-008');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-015-008', 'en-kp-015-01', 'en-q-015-008', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-015-008');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-009', 'en-repo-015', '9', 'May I ___ outside?', 'Radio', '{"id":"en-q-015-009","title":"May I ___ outside?","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["情态动词may表示请求许可：\"May I+动词原形…?\"意为\"我可以……吗？\"，语气委婉。"],"examAnalysis":"考查May I…?后接动词原形（Unit 2语法点1）。May I+动词原形…?表示''我可以……吗？''，''出去玩''是play outside，故用原形play，选A。B项plays、C项playing、D项to play都不能直接跟在May I后面。相关规则：情态动词may后接动词原形，无人称和数的变化。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"play","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"plays","attribute":{}},{"id":"c","title":"playing","attribute":{}},{"id":"d","title":"to play","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["情态动词may表示请求许可：\"May I+动词原形…?\"意为\"我可以……吗？\"，语气委婉。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-009');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-015-009', 'en-kp-015-01', 'en-q-015-009', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-015-009');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-010', 'en-repo-015', '10', '你想请同学帮忙打扫地板，应该说：___', 'Radio', '{"id":"en-q-015-010","title":"你想请同学帮忙打扫地板，应该说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["请求别人帮忙用\"Can you+动词原形…?\"，意为\"你能……吗？\"。"],"examAnalysis":"考查请求帮忙的Can you…?句型（Unit 2语法点2）。请别人帮忙做某事用Can you help me+动词原形…?，即Can you help me clean the floor?，故选C。A项May I…?是请求自己许可，方向反了；B项不是请求帮忙的句型；D项help后面不能直接跟物the floor。相关规则：请求别人帮忙用Can you+动词原形…?。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"May I clean the floor?","attribute":{}},{"id":"b","title":"Clean the floor?","attribute":{}},{"id":"c","title":"Can you help me clean the floor?","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"Can I help the floor?","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["请求别人帮忙用\"Can you+动词原形…?\"，意为\"你能……吗？\"。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-015-010', 'en-kp-015-02', 'en-q-015-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-015-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-011', 'en-repo-015', '11', '— Can you help me clean the desk? — ___', 'Radio', '{"id":"en-q-015-011","title":"— Can you help me clean the desk? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["请求别人帮忙用\"Can you+动词原形…?\"，意为\"你能……吗？\"。"],"examAnalysis":"考查Can you…?请求帮忙的应答（Unit 2语法点2）。Can you…?问，肯定回答用Yes, I can.，故选D。A项may是May I问句的回答；B项do用于do引导的问句；C项I''m not用于be动词问句的否定，均不对。相关规则：Can you…?的肯定回答Yes, I can.，否定回答No, I can''t.","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I may.","attribute":{}},{"id":"b","title":"Yes, I do.","attribute":{}},{"id":"c","title":"No, I''m not.","attribute":{}},{"id":"d","title":"Yes, I can.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["请求别人帮忙用\"Can you+动词原形…?\"，意为\"你能……吗？\"。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-015-011', 'en-kp-015-02', 'en-q-015-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-015-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-012', 'en-repo-015', '12', '妈妈让你先整理房间，会说：___', 'Radio', '{"id":"en-q-015-012","title":"妈妈让你先整理房间，会说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["祈使句表指令或要求：以动词原形开头（tidy, clean, stop…）。"],"examAnalysis":"考查祈使句表指令（Unit 2语法点3）。祈使句以动词原形开头，''先整理你的房间''是Tidy your room first.，故选B。A项Tidying是现在分词，不能单独作祈使句谓语；C、D项结构错误，D项your误作you。相关规则：祈使句 = 动词原形开头，表示命令或要求。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Tidying your room.","attribute":{}},{"id":"b","title":"Tidy your room first.","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"You tidy room.","attribute":{}},{"id":"d","title":"Tidy you room.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["祈使句表指令或要求：以动词原形开头（tidy, clean, stop…）。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-012');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-015-012', 'en-kp-015-04', 'en-q-015-012', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-015-012');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-013', 'en-repo-015', '13', '___ the floor, please.', 'Radio', '{"id":"en-q-015-013","title":"___ the floor, please.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["祈使句表指令或要求：以动词原形开头（tidy, clean, stop…）。"],"examAnalysis":"考查祈使句表指令（Unit 2语法点3，原例Clean the floor.）。祈使句以动词原形开头，''打扫地板''是Clean the floor.，句首字母大写，故选C。A项Cleans是第三人称单数形式，B项Cleaning是动名词，D项To clean是不定式，都不能引导祈使句。相关规则：祈使句以动词原形开头，please可放句末表客气。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Cleans","attribute":{}},{"id":"b","title":"Cleaning","attribute":{}},{"id":"c","title":"Clean","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"To clean","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["祈使句表指令或要求：以动词原形开头（tidy, clean, stop…）。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-013');
