INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-014', 'en-repo-015', '14', '— Can you tidy the wall? — ___. I can tidy the wall.', 'Radio', '{"id":"en-q-015-014","title":"— Can you tidy the wall? — ___. I can tidy the wall.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["请求别人帮忙用\"Can you+动词原形…?\"，意为\"你能……吗？\"。"],"examAnalysis":"考查Can you…?的肯定回答（Unit 2语法点2）。后一句I can tidy the wall.说明能做到，是肯定回答，用Yes, I can.，故选D。A项No与后句矛盾；B项may用于May I问句；C项don''t用于do问句且是否定。相关规则：Can you…?肯定回答Yes, I can.","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"No, I can''t.","attribute":{}},{"id":"b","title":"Yes, I may.","attribute":{}},{"id":"c","title":"No, I don''t.","attribute":{}},{"id":"d","title":"Yes, I can.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["请求别人帮忙用\"Can you+动词原形…?\"，意为\"你能……吗？\"。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-014');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-015-014', 'en-kp-015-02', 'en-q-015-014', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-015-014');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-015-015', 'en-repo-015', '15', '同学帮你把地板打扫得很干净，你应说：___', 'Radio', '{"id":"en-q-015-015","title":"同学帮你把地板打扫得很干净，你应说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["Unit 2 重点句型"],"examAnalysis":"考查夸赞用语Good job!（Unit 2重点句子5）。别人做得好时表扬对方用Good job!（干得好！），故选C。A项That''s easy.（那很容易）不是表扬；B项Goodbye!是告别；D项May I?是请求许可，都不合语境。相关规则：Good job! = 干得好！用于肯定、表扬别人。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"That''s easy.","attribute":{}},{"id":"b","title":"Goodbye!","attribute":{}},{"id":"c","title":"Good job!","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"May I?","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["Unit 2 重点句型"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-015-015');
