INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-001', 'en-repo-016', '1', 'What''s the weather ___?（天气怎么样？）', 'FillBlank', '{"id":"en-q-016-001","title":"What''s the weather ___?（天气怎么样？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"],"examAnalysis":"考查询问天气的固定句型（Unit 3语法点1）。原句为What''s the weather like?，固定搭配What''s…like?意为''……怎么样？''，故填like。相关规则：询问天气用What''s the weather like?，不能漏掉like。","examCorrectAnswer":"like","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-016-001', 'en-kp-016-01', 'en-q-016-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-016-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-002', 'en-repo-016', '2', 'It''s sunny and ___. We can go out to play.（阳光明媚，很暖和。我们可以出去玩。）', 'FillBlank', '{"id":"en-q-016-002","title":"It''s sunny and ___. We can go out to play.（阳光明媚，很暖和。我们可以出去玩。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"],"examAnalysis":"考查天气形容词及It''s+形容词回答天气（Unit 3语法点1）。原句为It''s sunny and warm.，warm意为''温暖的、暖和的''，与sunny并列描述天气，故填warm。相关规则：回答天气用It''s+描述天气的形容词，如sunny、warm、windy、cloudy。","examCorrectAnswer":"warm","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-002');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-016-002', 'en-kp-016-01', 'en-q-016-002', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-016-002');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-003', 'en-repo-016', '3', 'It''s windy and cloudy. Let''s ___ home!（有风，天阴了。我们回家吧！）', 'FillBlank', '{"id":"en-q-016-003","title":"It''s windy and cloudy. Let''s ___ home!（有风，天阴了。我们回家吧！）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["提建议用\"Let''s+动词原形\"（让我们……吧）。"],"examAnalysis":"考查提建议句型Let''s+动词原形（Unit 3语法点3）。原句为Let''s go home!，Let''s后接动词原形，''回家''是go home，故填go。相关规则：Let''s = Let us，意为''让我们……吧''，后接动词原形。","examCorrectAnswer":"go","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["提建议用\"Let''s+动词原形\"（让我们……吧）。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-003');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-016-003', 'en-kp-016-02', 'en-q-016-003', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-016-003');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-004', 'en-repo-016', '4', 'It''s rainy now. Let''s ___!（现在下雨了。我们快跑！）', 'FillBlank', '{"id":"en-q-016-004","title":"It''s rainy now. Let''s ___!（现在下雨了。我们快跑！）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["提建议用\"Let''s+动词原形\"（让我们……吧）。"],"examAnalysis":"考查Let''s+动词原形提建议（Unit 3语法点3）。原句为It''s rainy now. Let''s run!，Let''s后用动词原形run，故填run。相关规则：Let''s后面必须接动词原形，不能接runs或running。","examCorrectAnswer":"run","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["提建议用\"Let''s+动词原形\"（让我们……吧）。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-004');
