INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-011', 'en-repo-016', '11', '— Is it rainy or sunny? — ___', 'Radio', '{"id":"en-q-016-011","title":"— Is it rainy or sunny? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["选择疑问句用or连接两个并列选项，不能用yes/no回答，要直接选择回答。"],"examAnalysis":"考查选择疑问句的回答（Unit 3语法点2）。问句用or连接rainy和sunny，必须直接选择回答，A项It''s rainy.（下雨了）正确。B、C项用Yes/No错误；D项It''s rain.误用名词rain，应用形容词rainy。相关规则：选择疑问句直接选一项回答，回答用It''s+形容词。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"It''s rainy.","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Yes, it is.","attribute":{}},{"id":"c","title":"No, it isn''t.","attribute":{}},{"id":"d","title":"It''s rain.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["选择疑问句用or连接两个并列选项，不能用yes/no回答，要直接选择回答。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-011');
