INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-012', 'en-repo-016', '12', '天阴了有风，你想建议同学们回家，应说：___', 'Radio', '{"id":"en-q-016-012","title":"天阴了有风，你想建议同学们回家，应说：___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["提建议用\"Let''s+动词原形\"（让我们……吧）。"],"examAnalysis":"考查Let''s+动词原形提建议（Unit 3语法点3，原句Let''s go home!）。''让我们回家吧''是Let''s go home!，动词用原形go，故选B。A项Let''s后用going错误；C项Let us后应用动词原形go而非goes；D项是问句，不是提建议。相关规则：Let''s+动词原形，表示提议''让我们……吧''。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Let''s going home!","attribute":{}},{"id":"b","title":"Let''s go home!","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"Let us goes home!","attribute":{}},{"id":"d","title":"Go home?","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["提建议用\"Let''s+动词原形\"（让我们……吧）。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-012');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-016-012', 'en-kp-016-02', 'en-q-016-012', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-016-012');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-013', 'en-repo-016', '13', 'It''s ___ and warm.（天气晴朗又暖和。）', 'Radio', '{"id":"en-q-016-013","title":"It''s ___ and warm.（天气晴朗又暖和。）","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"],"examAnalysis":"考查天气形容词的拼写与用法（Unit 3语法点1）。be动词It''s后要接形容词，''晴朗的''是sunny（双写n加-y），故选C。A项sun是名词''太阳''，不能直接跟在It''s后描述天气；B项suny拼写错误；D项the sun是名词短语。相关规则：描述天气用名词+y构成的形容词，sun→sunny、cloud→cloudy、wind→windy、rain→rainy。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"sun","attribute":{}},{"id":"b","title":"suny","attribute":{}},{"id":"c","title":"sunny","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"the sun","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-013');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-016-013', 'en-kp-016-01', 'en-q-016-013', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-016-013');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-016-014', 'en-repo-016', '14', '下面哪个句子是用来询问天气的？', 'Radio', '{"id":"en-q-016-014","title":"下面哪个句子是用来询问天气的？","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"],"examAnalysis":"考查询问天气的句型（Unit 3语法点1）。询问天气用What''s the weather like?，故选D。A项询问姓名，B项询问年龄，C项是提建议的祈使句，都与天气无关。相关规则：What''s the weather like? = 天气怎么样？","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"What''s your name?","attribute":{}},{"id":"b","title":"How old are you?","attribute":{}},{"id":"c","title":"Let''s run!","attribute":{}},{"id":"d","title":"What''s the weather like?","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["询问天气用\"What''s the weather like?\"（天气怎么样？），回答用\"It''s+描述天气的形容词.\"。"]', 'easy', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-016-014');
