INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-001', 'en-repo-017', '1', 'What''s your ___ season?（你最喜欢的季节是什么？）', 'FillBlank', '{"id":"en-q-017-001","title":"What''s your ___ season?（你最喜欢的季节是什么？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"],"examAnalysis":"考查询问''最喜欢……''的句型（Unit 4语法点1）。原句为What''s your favourite season?，favourite意为''特别受喜爱的''，故填favourite。相关规则：询问最喜欢什么用What''s your favourite+名词?。","examCorrectAnswer":"favourite","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-017-001', 'en-kp-017-01', 'en-q-017-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-017-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-002', 'en-repo-017', '2', 'I like winter ___. I can play in the snow.（我最喜欢冬天。我可以在雪地里玩耍。）', 'FillBlank', '{"id":"en-q-017-002","title":"I like winter ___. I can play in the snow.（我最喜欢冬天。我可以在雪地里玩耍。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"],"examAnalysis":"考查表达''最喜欢''用like…best（Unit 4语法点1）。原句为I like winter best.，''最喜欢''用like…best，故填best。相关规则：主语+like(s)+某物+best，表示''最喜欢某事物''。","examCorrectAnswer":"best","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["询问\"最喜欢……\"用\"What''s your favourite…?\"；表达\"最喜欢某事物\"用\"主语+like(s)…b"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-002');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-017-002', 'en-kp-017-01', 'en-q-017-002', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-017-002');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-017-003', 'en-repo-017', '3', 'I like summer best. I can ___ ice cream.（我最喜欢夏天。我可以吃冰淇淋。）', 'FillBlank', '{"id":"en-q-017-003","title":"I like summer best. I can ___ ice cream.（我最喜欢夏天。我可以吃冰淇淋。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["Unit 4 重点句型"],"examAnalysis":"考查can后接动词原形（Unit 4重点句子3）。原句为I can eat ice cream.，''吃''是eat，can后用动词原形，故填eat。相关规则：情态动词can后接动词原形，无人称和数的变化。","examCorrectAnswer":"eat","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["Unit 4 重点句型"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-017-003');
