INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-018-001', 'en-repo-018', '1', '___ do we get there?（我们怎么去那儿呢？）', 'FillBlank', '{"id":"en-q-018-001","title":"___ do we get there?（我们怎么去那儿呢？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["询问交通方式用\"How do/does+主语+get/go…?\"（……怎么去？）。"],"examAnalysis":"考查询问交通方式的句型（Unit 5语法点1）。原句为How do we get there?，询问''怎么去''用How，句首字母大写，故填How。相关规则：询问交通方式用How do/does+主语+get/go…?。","examCorrectAnswer":"How","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["询问交通方式用\"How do/does+主语+get/go…?\"（……怎么去？）。"]', 'easy', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-018-001');
