INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-018-004', 'en-repo-018', '4', 'She ___ by bus.（她坐公交车去。）', 'FillBlank', '{"id":"en-q-018-004","title":"She ___ by bus.（她坐公交车去。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["一般现在时中，主语是第三人称单数时，行为动词要加-s/-es（go→goes）。"],"examAnalysis":"考查一般现在时第三人称单数动词加-es（Unit 5语法点3）。主语She是第三人称单数，动词go要变为goes，即She goes by bus.，故填goes。相关规则：主语是第三人称单数时，行为动词加-s/-es；go以o结尾加-es变goes。","examCorrectAnswer":"goes","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["一般现在时中，主语是第三人称单数时，行为动词要加-s/-es（go→goes）。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-018-004');
