INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-018-005', 'en-repo-018', '5', 'Let''s go for a ___ in the park.（我们去公园野餐吧。）', 'FillBlank', '{"id":"en-q-018-005","title":"Let''s go for a ___ in the park.（我们去公园野餐吧。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["Unit 5 重点句型"],"examAnalysis":"考查短语go for a picnic（Unit 5重点句子1）。原句为Let''s go for a picnic in the park.，picnic意为''野餐''，go for a picnic是固定搭配''去野餐''，故填picnic。相关规则：go for a picnic = 去野餐。","examCorrectAnswer":"picnic","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["Unit 5 重点句型"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-018-005');
