INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-018-008', 'en-repo-018', '8', '— ___ do we get there? — By bus.', 'Radio', '{"id":"en-q-018-008","title":"— ___ do we get there? — By bus.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["询问交通方式用\"How do/does+主语+get/go…?\"（……怎么去？）。"],"examAnalysis":"考查询问交通方式的How问句（Unit 5语法点1）。答句By bus.（乘公交车）回答的是出行方式，问句用How（怎么）提问，故选C。A项What问事物，B项Where问地点，D项When问时间，都不能用by bus回答。相关规则：How do/does+主语+get/go…?问交通方式。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"What","attribute":{}},{"id":"b","title":"Where","attribute":{}},{"id":"c","title":"How","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"When","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["询问交通方式用\"How do/does+主语+get/go…?\"（……怎么去？）。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-018-008');
