INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-018-009', 'en-repo-018', '9', 'Let''s go ___ bike.', 'Radio', '{"id":"en-q-018-009","title":"Let''s go ___ bike.","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["表示\"乘某种交通工具\"用\"by+交通工具名词\"，中间不加冠词。"],"examAnalysis":"考查by+交通工具（Unit 5语法点2）。''骑自行车''是by bike，固定用介词by，故选B。A项on、C项in、D项at都不与交通工具这样搭配表示出行方式。相关规则：by+交通工具名词，中间不加冠词。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"on","attribute":{}},{"id":"b","title":"by","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"in","attribute":{}},{"id":"d","title":"at","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["表示\"乘某种交通工具\"用\"by+交通工具名词\"，中间不加冠词。"]', 'easy', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-018-009');
