INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-018-010', 'en-repo-018', '10', 'She ___ by train.', 'Radio', '{"id":"en-q-018-010","title":"She ___ by train.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["一般现在时中，主语是第三人称单数时，行为动词要加-s/-es（go→goes）。"],"examAnalysis":"考查一般现在时第三人称单数（Unit 5语法点3）。主语She是第三人称单数，动词go要加-es变为goes，故选D。A项go用于第一、二人称或复数；B项going是现在分词；C项to go是不定式，都不能作谓语。相关规则：第三人称单数主语后行为动词加-s/-es，go→goes。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"go","attribute":{}},{"id":"b","title":"going","attribute":{}},{"id":"c","title":"to go","attribute":{}},{"id":"d","title":"goes","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["一般现在时中，主语是第三人称单数时，行为动词要加-s/-es（go→goes）。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-018-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-018-010', 'en-kp-018-03', 'en-q-018-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-018-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-018-011', 'en-repo-018', '11', '— How does she ___ there? — By plane.', 'Radio', '{"id":"en-q-018-011","title":"— How does she ___ there? — By plane.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["询问交通方式用\"How do/does+主语+get/go…?\"（……怎么去？）。"],"examAnalysis":"考查特殊疑问句中助动词后接动词原形（Unit 5语法点1）。疑问句中已用助动词does，后面的实义动词要用原形get，故选A。B项gets是第三人称单数形式，不能放在does后；C项getting、D项to get也不对。相关规则：How does+三单主语+动词原形…?，助动词does后动词还原。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"get","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"gets","attribute":{}},{"id":"c","title":"getting","attribute":{}},{"id":"d","title":"to get","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["询问交通方式用\"How do/does+主语+get/go…?\"（……怎么去？）。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-018-011');
