INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-018-012', 'en-repo-018', '12', '下面哪个正确表示"乘公交车"？', 'Radio', '{"id":"en-q-018-012","title":"下面哪个正确表示\"乘公交车\"？","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 5","section":"重点语法与句型","knowledgePoint":["表示\"乘某种交通工具\"用\"by+交通工具名词\"，中间不加冠词。"],"examAnalysis":"考查by+交通工具不加冠词（Unit 5语法点2）。''乘公交车''是by bus，by后直接跟单数交通工具名词，不加任何冠词，故选D。A项多了a、B项多了the、C项用了复数buses，都违反by+交通工具的规则。相关规则：by+单数交通工具名词，不加冠词。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"by a bus","attribute":{}},{"id":"b","title":"by the bus","attribute":{}},{"id":"c","title":"by buses","attribute":{}},{"id":"d","title":"by bus","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 5"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 5', '重点语法与句型', '["表示\"乘某种交通工具\"用\"by+交通工具名词\"，中间不加冠词。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-018-012');
