INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-019-011', 'en-repo-019', '11', '— Where ___ she go? — She goes to the museum.', 'Radio', '{"id":"en-q-019-011","title":"— Where ___ she go? — She goes to the museum.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["一般现在时表经常性动作：主语是第三人称单数，动词加-s/-es（go→goes, turn→turns）。"],"examAnalysis":"考查特殊疑问句的助动词（Unit 6语法点3，原句Where does she go?）。主语She是第三人称单数，句中已有实义动词go，疑问句要加助动词does，故选C。A项do用于非三单主语；B项is、D项are是be动词，不能与实义动词原形go这样连用。相关规则：三单主语的特殊疑问句：疑问词+does+主语+动词原形。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"do","attribute":{}},{"id":"b","title":"is","attribute":{}},{"id":"c","title":"does","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"are","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["一般现在时表经常性动作：主语是第三人称单数，动词加-s/-es（go→goes, turn→turns）。"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-019-011');
