INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-019-012', 'en-repo-019', '12', '"左转"的英语是：___', 'Radio', '{"id":"en-q-019-012","title":"\"左转\"的英语是：___","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["指路/问路用祈使句：\"Go straight on.\"（直走）、\"Turn left/right.\"（向左/右转）。"],"examAnalysis":"考查指路祈使句Turn left（Unit 6语法点1）。''左转''是Turn left.，故选D。A项Turn right.是''右转''，B项Go straight.是''直走''，C项Be careful.是''当心''，都不对。相关规则：Turn left.左转；Turn right.右转。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Turn right.","attribute":{}},{"id":"b","title":"Go straight.","attribute":{}},{"id":"c","title":"Be careful.","attribute":{}},{"id":"d","title":"Turn left.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["指路/问路用祈使句：\"Go straight on.\"（直走）、\"Turn left/right.\"（向左/右转）。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-019-012');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-019-012', 'en-kp-019-01', 'en-q-019-012', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-019-012');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-019-013', 'en-repo-019', '13', '___ careful! The road is busy.', 'Radio', '{"id":"en-q-019-013","title":"___ careful! The road is busy.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["Unit 6 重点句型"],"examAnalysis":"考查Be careful!祈使句（Unit 6重点句子6）。祈使句以动词原形开头，''当心''是Be careful!，be用原形，句首大写，故选C。A项Is、B项Are是be动词的现在时形式，不用于祈使句句首；D项Being是现在分词。相关规则：祈使句用动词原形，Be+形容词.表示提醒。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Is","attribute":{}},{"id":"b","title":"Are","attribute":{}},{"id":"c","title":"Be","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"Being","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["Unit 6 重点句型"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-019-013');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-019-013', 'en-kp-019-04', 'en-q-019-013', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-019-013');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-019-014', 'en-repo-019', '14', 'He ___ straight on to the museum.', 'Radio', '{"id":"en-q-019-014","title":"He ___ straight on to the museum.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["一般现在时表经常性动作：主语是第三人称单数，动词加-s/-es（go→goes, turn→turns）。"],"examAnalysis":"考查一般现在时第三人称单数（Unit 6语法点3）。主语He是第三人称单数，动词go要加-es变为goes，故选B。A项go用于非三单主语；C项going是现在分词；D项to go是不定式，不能作谓语。相关规则：三单主语后go→goes。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"go","attribute":{}},{"id":"b","title":"goes","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"going","attribute":{}},{"id":"d","title":"to go","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","上册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["一般现在时表经常性动作：主语是第三人称单数，动词加-s/-es（go→goes, turn→turns）。"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-019-014');
