INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-001', 'en-repo-020', '1', '— What''s your father''s ___? — He''s a doctor.（— 你爸爸的工作是什么？— 他是一名医生。）', 'FillBlank', '{"id":"en-q-020-001","title":"— What''s your father''s ___? — He''s a doctor.（— 你爸爸的工作是什么？— 他是一名医生。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["询问职业 What''s sb''s job? / What does sb do?"],"examAnalysis":"考查询问职业的句型 What''s sb''s job?（Unit 1语法点1）。询问某人的工作是什么，用 What''s your father''s job?，''工作（职业）''对应 job。答句 He''s a doctor.（他是一名医生）正好回答职业。注意区分 job（指职业、一份工作）与 work（指劳动、干活这个动作），这里问的是''职业''，用 job。","examCorrectAnswer":"job","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["询问职业 What''s sb''s job? / What does sb do?"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-020-001', 'en-kp-020-01', 'en-q-020-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-020-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-002', 'en-repo-020', '2', 'He''s a doctor. He ___ in a hospital.（他是一名医生，他在医院工作。）', 'FillBlank', '{"id":"en-q-020-002","title":"He''s a doctor. He ___ in a hospital.（他是一名医生，他在医院工作。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["一般现在时第三人称单数动词加-s"],"examAnalysis":"考查一般现在时第三人称单数动词加-s（Unit 1语法点2）。主语 He 是第三人称单数，动词 work 要变为 works。原句即 He works in a hospital.（他在医院工作）。类似的还有 She helps sick people. 中 help→helps。","examCorrectAnswer":"works","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["一般现在时第三人称单数动词加-s"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-002');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-020-002', 'en-kp-020-02', 'en-q-020-002', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-020-002');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-003', 'en-repo-020', '3', 'She''s a nurse. She ___ sick people.（她是一名护士，她帮助生病的人。）', 'FillBlank', '{"id":"en-q-020-003","title":"She''s a nurse. She ___ sick people.（她是一名护士，她帮助生病的人。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["一般现在时第三人称单数动词加-s"],"examAnalysis":"考查一般现在时第三人称单数动词加-s（Unit 1语法点2）。主语 She 是第三人称单数，动词 help 要加-s 变为 helps。sick people 意为''生病的人''。规则：he/she/it 作主语时，一般现在时动词要加 -s 或 -es。","examCorrectAnswer":"helps","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["一般现在时第三人称单数动词加-s"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-003');
