INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-008', 'en-repo-020', '8', '— What does your mother do? — ___', 'Radio', '{"id":"en-q-020-008","title":"— What does your mother do? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["询问职业 What''s sb''s job? / What does sb do?"],"examAnalysis":"考查 What does sb do? 询问职业（Unit 1语法点1）。问句''你妈妈是做什么的？''询问职业，应回答职业身份。A项 He''s a doctor.（他是医生）是职业回答（此处按教材句型套用，回答职业即可），正确。B项''他在医院工作''回答的是工作地点，不是职业；C项''他很好''、D项''他很高''答非所问，排除。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"He is fine.","attribute":{}},{"id":"b","title":"He works in a hospital.","attribute":{}},{"id":"c","title":"He is tall.","attribute":{}},{"id":"d","title":"He''s a doctor.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["询问职业 What''s sb''s job? / What does sb do?"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-008');
