INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-020-010', 'en-repo-020', '10', '— ___ your aunt work? — She works at a school.', 'Radio', '{"id":"en-q-020-010","title":"— ___ your aunt work? — She works at a school.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["询问工作地点 Where does sb work?"],"examAnalysis":"考查询问工作地点 Where does sb work?（Unit 1语法点3）。答句''她在学校工作''回答的是地点，故问句用 Where（在哪里）提问；主语 your aunt 是三单，借助助动词 does，后面动词用原形 work。A、C项 What 问职业或事物；D项 Where are 后面不能接动词原形 work，故B正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Where does","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Where are","attribute":{}},{"id":"c","title":"What does","attribute":{}},{"id":"d","title":"What do","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["询问工作地点 Where does sb work?"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-020-010');
