INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-001', 'en-repo-021', '1', '— How ___ you feel today? — I feel sad.（— 你今天感觉怎么样？— 我感到伤心。）', 'FillBlank', '{"id":"en-q-021-001","title":"— How ___ you feel today? — I feel sad.（— 你今天感觉怎么样？— 我感到伤心。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["询问感受 How do you feel? 回答 I feel + 形容词"],"examAnalysis":"考查询问感受 How do you feel?（Unit 2语法点1）。''你感觉怎么样？''用 How do you feel?，主语是 you，借助助动词 do，后面动词用原形 feel。回答用 I feel + 形容词，如 I feel sad.（我感到伤心）。","examCorrectAnswer":"do","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["询问感受 How do you feel? 回答 I feel + 形容词"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-001');
