INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-004', 'en-repo-021', '4', 'I ___ feeling better now.（我现在感觉好多了。）', 'FillBlank', '{"id":"en-q-021-004","title":"I ___ feeling better now.（我现在感觉好多了。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["现在进行时 be + 动词-ing"],"examAnalysis":"考查现在进行时 be + 动词-ing（Unit 2语法点2）。主语是 I，be 动词用 am，I am feeling better now.（我现在感觉好多了）。feel→feeling。规则：I 用 am，you/we/they 用 are，he/she/it 用 is。","examCorrectAnswer":"am","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["现在进行时 be + 动词-ing"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-004');
