INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-005', 'en-repo-021', '5', 'We should ___ sorry when we make a mistake.（当我们犯错时，我们应该道歉。）', 'FillBlank', '{"id":"en-q-021-005","title":"We should ___ sorry when we make a mistake.（当我们犯错时，我们应该道歉。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["should + 动词原形表应该"],"examAnalysis":"考查 should + 动词原形表''应该''（Unit 2语法点3）。should 是情态动词，后面必须接动词原形，''道歉、说对不起''是 say sorry，故填 say。同类用法：You should help others.","examCorrectAnswer":"say","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["should + 动词原形表应该"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-005');
