INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-006', 'en-repo-021', '6', 'Jay is very ___ and happy when he gets the new ship model.（杰伊收到新轮船模型时，又惊喜又开心。）', 'FillBlank', '{"id":"en-q-021-006","title":"Jay is very ___ and happy when he gets the new ship model.（杰伊收到新轮船模型时，又惊喜又开心。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["Unit 2 重点句型"],"examAnalysis":"考查核心句型 get…时的感受（Unit 2重点句子）。''又惊喜又开心''是 surprised and happy，surprised 意为''吃惊的、惊奇的''。get the new ship model（收到新轮船模型）让人惊喜。surprised 是形容词，作表语。","examCorrectAnswer":"surprised","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["Unit 2 重点句型"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-006');
