INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-008', 'en-repo-021', '8', '— How do you feel today? — ___', 'Radio', '{"id":"en-q-021-008","title":"— How do you feel today? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["询问感受 How do you feel? 回答 I feel + 形容词"],"examAnalysis":"考查 How do you feel? 的回答 I feel + 形容词（Unit 2语法点1）。问句问''你今天感觉怎么样？''，应回答心情感受。A项 I feel sad.（我感到伤心）正确。B项回答身份，C项回答喜好，D项回答行为，都不是感受，排除。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"I feel sad.","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"I like apples.","attribute":{}},{"id":"c","title":"I am a student.","attribute":{}},{"id":"d","title":"I go to school.","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["询问感受 How do you feel? 回答 I feel + 形容词"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-008');
