INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-012', 'en-repo-021', '12', 'I am ___ better now.', 'Radio', '{"id":"en-q-021-012","title":"I am ___ better now.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["现在进行时 be + 动词-ing"],"examAnalysis":"考查现在进行时 be + 动词-ing（Unit 2语法点2）。am 后面接动词的 -ing 形式构成现在进行时，feel→feeling，I am feeling better now.。A项 feel 原形不能直接跟 am；C项 feels 三单；D项 felt 过去式，故B正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"felt","attribute":{}},{"id":"b","title":"feeling","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"feel","attribute":{}},{"id":"d","title":"feels","attribute":{}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["现在进行时 be + 动词-ing"]', 'medium', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-012');
