INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-021-013', 'en-repo-021', '13', '— How do you feel? — I feel ___. I can''t find my gift.', 'Radio', '{"id":"en-q-021-013","title":"— How do you feel? — I feel ___. I can''t find my gift.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["询问感受 How do you feel? 回答 I feel + 形容词"],"examAnalysis":"考查 I feel + 形容词（Unit 2语法点1）。feel 后接形容词表示心情。''找不到礼物''会让人着急，故 angry（生气的）符合。B项 apple（苹果）、C项 school（学校）是名词，D项 run（跑）是动词，都不能跟在 feel 后作心情描述，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"school","attribute":{}},{"id":"b","title":"run","attribute":{}},{"id":"c","title":"apple","attribute":{}},{"id":"d","title":"angry","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","四年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["询问感受 How do you feel? 回答 I feel + 形容词"]', 'hard', '四年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-021-013');
