INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-026-001', 'en-repo-026', '1', 'Don''t ___ (take) too much!（别吃太多！）', 'FillBlank', '{"id":"en-q-026-001","title":"Don''t ___ (take) too much!（别吃太多！）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["祈使句：肯定形式以动词原形开头；否定形式以Don''t+动词原形开头"],"examAnalysis":"考查祈使句的否定形式（Unit1语法点1）。否定祈使句以“Don''t + 动词原形”开头，Don''t 后必须接动词原形，故填 take。原句 Don''t take too much!（别吃太多！）。","examCorrectAnswer":"take","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["祈使句：肯定形式以动词原形开头；否定形式以Don''t+动词原形开头"]', 'easy', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-026-001');
