INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-026-005', 'en-repo-026', '5', 'He ___ (eat) bread and milk for breakfast.（他早餐吃面包和牛奶。）', 'FillBlank', '{"id":"en-q-026-005","title":"He ___ (eat) bread and milk for breakfast.（他早餐吃面包和牛奶。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["询问饮食习惯：What do you eat+三餐? I eat+食物.；第三人称用What does+主语+eat+三"],"examAnalysis":"考查一般现在时第三人称单数动词变化（Unit1语法点3）。主语 He 是第三人称单数，谓语动词 eat 要加 -s 变为 eats，故填 eats。回答 What does Tom eat...? 时要用 He eats...。","examCorrectAnswer":"eats","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["询问饮食习惯：What do you eat+三餐? I eat+食物.；第三人称用What does+主语+eat+三"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-026-005');
