INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-026-007', 'en-repo-026', '7', 'You shouldn''t ___ (eat) too much chocolate.（你不应该吃太多巧克力。）', 'FillBlank', '{"id":"en-q-026-007","title":"You shouldn''t ___ (eat) too much chocolate.（你不应该吃太多巧克力。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["should表示建议：You should+动词原形+其他；否定式shouldn''t=should not"],"examAnalysis":"考查 should 的否定式（Unit1语法点2）。shouldn''t = should not，后面同样接动词原形，故填 eat。","examCorrectAnswer":"eat","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["should表示建议：You should+动词原形+其他；否定式shouldn''t=should not"]', 'easy', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-026-007');
