INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-026-008', 'en-repo-026', '8', '下面哪个句子是否定祈使句？', 'Radio', '{"id":"en-q-026-008","title":"下面哪个句子是否定祈使句？","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["祈使句：肯定形式以动词原形开头；否定形式以Don''t+动词原形开头"],"examAnalysis":"考查否定祈使句的识别（Unit1语法点1）。否定祈使句以“Don''t + 动词原形”开头，C 项 Don''t touch the hot water.（别碰热水）正是这种结构。A 项 Open the window. 是肯定祈使句；B 项是 should 建议句；D 项是特殊疑问句，均不是否定祈使句。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Open the window.","attribute":{}},{"id":"b","title":"You should have some water.","attribute":{}},{"id":"c","title":"Don''t touch the hot water.","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"What does Tom eat?","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["祈使句：肯定形式以动词原形开头；否定形式以Don''t+动词原形开头"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-026-008');
