INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-026-011', 'en-repo-026', '11', 'This apple is ___ you.（这个苹果给你。）', 'Radio', '{"id":"en-q-026-011","title":"This apple is ___ you.（这个苹果给你。）","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["Unit 1 重点句型"],"examAnalysis":"考查重点句型 This ... is for you（Unit1重点句子5）。“某物给某人”用 sth is for sb，介词用 for，故 B 正确。A to、C at、D with 都不构成“给某人”的搭配。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"to","attribute":{}},{"id":"b","title":"for","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"at","attribute":{}},{"id":"d","title":"with","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["Unit 1 重点句型"]', 'easy', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-026-011');
