INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-026-012', 'en-repo-026', '12', '___ some vegetables. It''s healthy.', 'Radio', '{"id":"en-q-026-012","title":"___ some vegetables. It''s healthy.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["祈使句：肯定形式以动词原形开头；否定形式以Don''t+动词原形开头"],"examAnalysis":"考查肯定祈使句（Unit1语法点1）。肯定祈使句以动词原形开头，句首大写，故 D 项 Eat 正确。A 项 Eats 是三单形式、B 项 Eating 是动名词、C 项 To eat 是不定式，都不能直接作祈使句谓语。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Eats","attribute":{}},{"id":"b","title":"Eating","attribute":{}},{"id":"c","title":"To eat","attribute":{}},{"id":"d","title":"Eat","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["祈使句：肯定形式以动词原形开头；否定形式以Don''t+动词原形开头"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-026-012');
