INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-026-013', 'en-repo-026', '13', '下面哪个句子是正确的？', 'Radio', '{"id":"en-q-026-013","title":"下面哪个句子是正确的？","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["should表示建议：You should+动词原形+其他；否定式shouldn''t=should not"],"examAnalysis":"考查 should + 动词原形的正确语序（Unit1语法点2）。should 后必须接动词原形，且 should 前不再加 be 动词，C 项 You should drink milk. 正确。A 项 drinks 用了三单；B 项多了 are；D 项 drinking 用了动名词，均错误。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"You should drinks milk.","attribute":{}},{"id":"b","title":"You are should drink milk.","attribute":{}},{"id":"c","title":"You should drink milk.","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"You should drinking milk.","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["should表示建议：You should+动词原形+其他；否定式shouldn''t=should not"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-026-013');
