INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-027-010', 'en-repo-027', '10', '— What can we do to reduce plastic? — We ___ use reusable bags.', 'Radio', '{"id":"en-q-027-010","title":"— What can we do to reduce plastic? — We ___ use reusable bags.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["询问环保行动：What can we do to...? 回答We can+动词原形；How do we...? 回答具"],"examAnalysis":"考查 What can we do to...? 的回答（Unit2语法点3）。该问句用 We can + 动词原形 回答，故 B 项 can 正确。A、C、D 三项不能与 We 后这样接动词原形来回应“能做什么”。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"are","attribute":{}},{"id":"b","title":"can","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"do","attribute":{}},{"id":"d","title":"is","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["询问环保行动：What can we do to...? 回答We can+动词原形；How do we...? 回答具"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-027-010');
