INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-027-011', 'en-repo-027', '11', 'Earth Day comes ___ 22 April every year.', 'Radio', '{"id":"en-q-027-011","title":"Earth Day comes ___ 22 April every year.","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["介绍节日日期：Earth Day comes on+日期；People+动词原形+活动"],"examAnalysis":"考查节日日期前的介词（Unit2语法点4）。在具体某一天（如 22 April）前要用介词 on，故 C 正确。A 项 in 用于月份/季节，B 项 at 用于具体时刻，D 项 to 不表时间。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"in","attribute":{}},{"id":"b","title":"at","attribute":{}},{"id":"c","title":"on","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"to","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["介绍节日日期：Earth Day comes on+日期；People+动词原形+活动"]', 'easy', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-027-011');
