INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-027-012', 'en-repo-027', '12', '旧物品还能再用，我们应该 ___ 它。', 'Radio', '{"id":"en-q-027-012","title":"旧物品还能再用，我们应该 ___ 它。","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["三个R原则：Recycle（回收利用）/ Reuse（再使用）/ Reduce（减少使用）"],"examAnalysis":"考查三个 R 原则的运用（Unit2语法点2）。“还能再用”对应 reuse（再使用），故 D 正确。A waste 浪费、B throw 扔、C reduce 减少，都不符合“再使用”的意思。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"waste","attribute":{}},{"id":"b","title":"throw","attribute":{}},{"id":"c","title":"reduce","attribute":{}},{"id":"d","title":"reuse","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","五年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["三个R原则：Recycle（回收利用）/ Reuse（再使用）/ Reduce（减少使用）"]', 'easy', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-027-012');
