INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-011', 'en-repo-032', '11', 'We ___ lunch for ourselves yesterday.', 'Radio', '{"id":"en-q-032-011","title":"We ___ lunch for ourselves yesterday.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practic"],"examAnalysis":"考查知识点：规则动词过去式（本单元语法点3）。为什么选C：yesterday表过去，cook的过去式cooked。错误项：A项cook是原形；B项cooks是一般现在时三单；D项cooking是现在分词，不能单独作谓语。相关规则：规则动词一般直接加-ed构成过去式。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"cook","attribute":{}},{"id":"b","title":"cooks","attribute":{}},{"id":"c","title":"cooked","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"cooking","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["实义动词过去式：规则动词加-ed（clap→clapped, cook→cooked, practice→practic"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-011');
