INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-032-014', 'en-repo-032', '14', '— Could you swim three years ago? — ___. I couldn''t swim at all.', 'Radio', '{"id":"en-q-032-014","title":"— Could you swim three years ago? — ___. I couldn''t swim at all.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["情态动词could的过去式用法：could是can的过去式，后接动词原形；否定形式为couldn''t。"],"examAnalysis":"考查知识点：could一般疑问句的回答（本单元语法点2）。为什么选B：答语后句说''我根本不会游泳''，是否定回答，Could开头的否定回答用No, I couldn''t。错误项：A项Yes与后句矛盾；C项did不能回答could问句；D项don''t是现在时，时态与助动词均不符。相关规则：Could you...? 回答用Yes, I could./No, I couldn''t.","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I could.","attribute":{}},{"id":"b","title":"Yes, I did.","attribute":{}},{"id":"c","title":"No, I don''t.","attribute":{}},{"id":"d","title":"No, I couldn''t.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["情态动词could的过去式用法：could是can的过去式，后接动词原形；否定形式为couldn''t。"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-032-014');
