INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-012', 'en-repo-033', '12', '— Can I help you carry the cart? — ___', 'Radio', '{"id":"en-q-033-012","title":"— Can I help you carry the cart? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["can的用法：表能力（主语+can/can''t+动词原形）；表请求/建议（Can I+动词原形...? 回答用Yes,p"],"examAnalysis":"考查知识点：Can I...?表请求的回答（本单元语法点4）。为什么选A：Can I help you?是主动提供帮助，接受用Yes,please.。错误项：B项Yes,I can.回答的是Can you...?；C项No,I don''t.时态/助动词不符；D项You''re welcome.用于回应感谢，不回应请求。相关规则：提供帮助的请求用Yes,please./No,thanks.回答。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, please.","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Yes, I can.","attribute":{}},{"id":"c","title":"No, I don''t.","attribute":{}},{"id":"d","title":"You''re welcome.","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["can的用法：表能力（主语+can/can''t+动词原形）；表请求/建议（Can I+动词原形...? 回答用Yes,p"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-012');
