INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-013', 'en-repo-033', '13', 'Mum ___ me a new book yesterday.', 'Radio', '{"id":"en-q-033-013","title":"Mum ___ me a new book yesterday.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, "],"examAnalysis":"考查知识点：不规则动词过去式give→gave（本单元语法点1）。为什么选B：yesterday表过去，give的过去式是gave。错误项：A项gived是错误拼写；C项gives是现在时三单；D项give是原形。相关规则：give→gave，不规则变化需记忆。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"gived","attribute":{}},{"id":"b","title":"gave","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"gives","attribute":{}},{"id":"d","title":"give","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, "]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-013');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-033-013', 'en-kp-033-01', 'en-q-033-013', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-033-013');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-014', 'en-repo-033', '14', '— Did you clean the classroom? — ___. I went home early.', 'Radio', '{"id":"en-q-033-014","title":"— Did you clean the classroom? — ___. I went home early.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["一般过去时句型结构：陈述句（主语+动词过去式+其他）；否定句（主语+didn''t+动词原形+其他）；疑问句（Did+主语"],"examAnalysis":"考查知识点：Did疑问句否定回答（本单元语法点2）。为什么选B：后句说''我很早就回家了''，说明没打扫，用否定回答No, I didn''t。错误项：A项Yes与后句矛盾；C、D项do/don''t是现在时，与Did问句时态不一致。相关规则：一般过去时一般疑问句否定回答用No,...didn''t.","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I did.","attribute":{}},{"id":"b","title":"No, I didn''t.","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"Yes, I do.","attribute":{}},{"id":"d","title":"No, I don''t.","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["一般过去时句型结构：陈述句（主语+动词过去式+其他）；否定句（主语+didn''t+动词原形+其他）；疑问句（Did+主语"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-014');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-033-014', 'en-kp-033-02', 'en-q-033-014', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-033-014');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-033-015', 'en-repo-033', '15', 'Grandpa ___ under the big tree and told us a story.', 'Radio', '{"id":"en-q-033-015","title":"Grandpa ___ under the big tree and told us a story.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, "],"examAnalysis":"考查知识点：不规则动词过去式sit→sat（本单元语法点1）。为什么选C：与told并列的过去动作，sit的过去式是sat。错误项：A项sit是原形；B项sitted是错误拼写；D项sits是现在时三单。相关规则：sit→sat，不规则变化，需特殊记忆。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"sit","attribute":{}},{"id":"b","title":"sitted","attribute":{}},{"id":"c","title":"sat","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"sits","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["一般过去时动词变化：规则动词加-ed（hurry→hurried, help→helped, push→pushed, "]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-033-015');
