INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-001', 'en-repo-034', '1', '___ you also have library day then, Mum? — Yes, we did.（妈妈，那时你也有图书馆日吗？）', 'FillBlank', '{"id":"en-q-034-001","title":"___ you also have library day then, Mum? — Yes, we did.（妈妈，那时你也有图书馆日吗？）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["Did引导的一般过去时一般疑问句：Did+主语+动词原形+其他？肯定回答Yes,主语+did. 否定回答No,主语+di"],"examAnalysis":"考查知识点：Did引导的一般过去时一般疑问句（本单元语法点1）。为什么填这个：由答句Yes, we did.可知问句以Did开头，主语you后接动词原形have。相关规则：Did+主语+动词原形+其他？回答Yes,主语+did./No,主语+didn''t.","examCorrectAnswer":"Did","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["Did引导的一般过去时一般疑问句：Did+主语+动词原形+其他？肯定回答Yes,主语+did. 否定回答No,主语+di"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-034-001', 'en-kp-034-01', 'en-q-034-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-034-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-002', 'en-repo-034', '2', '___ there many books in the library? — No, there weren''t.（图书馆里有很多书吗？——不，没有。）', 'FillBlank', '{"id":"en-q-034-002","title":"___ there many books in the library? — No, there weren''t.（图书馆里有很多书吗？——不，没有。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./N"],"examAnalysis":"考查知识点：there be句型一般过去时疑问句（本单元语法点2）。为什么填这个：many books是复数，过去时用Were there...? 答句也用there weren''t。相关规则：复数名词用Were there...? 回答Yes,there were./No,there weren''t.","examCorrectAnswer":"Were","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./N"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-002');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-034-002', 'en-kp-034-02', 'en-q-034-002', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-034-002');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-003', 'en-repo-034', '3', '___ there a library in your school before? — Yes, there was.（你们学校以前有图书馆吗？——是的，有。）', 'FillBlank', '{"id":"en-q-034-003","title":"___ there a library in your school before? — Yes, there was.（你们学校以前有图书馆吗？——是的，有。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./N"],"examAnalysis":"考查知识点：there be过去时疑问句——单数用Was there（本单元语法点2）。为什么填这个：a library是单数名词，过去时疑问句用Was there...? 答句there was也呼应。相关规则：单数/不可数名词用Was there...? 回答Yes,there was.","examCorrectAnswer":"Was","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./N"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-003');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-034-003', 'en-kp-034-02', 'en-q-034-003', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-034-003');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-004', 'en-repo-034', '4', 'It ___ (keep) raining and raining last week.（上周雨一直下。）', 'FillBlank', '{"id":"en-q-034-004","title":"It ___ (keep) raining and raining last week.（上周雨一直下。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["一般过去时陈述句：描述过去发生的动作或存在的状态，谓语动词用过去式。时间状语有yesterday, last week,"],"examAnalysis":"考查知识点：一般过去时陈述句，谓语动词用过去式（本单元语法点3）。为什么填这个：last week表过去，keep的过去式为不规则变化kept。相关规则：描述过去发生的动作，谓语动词用过去式；时间状语有last week, yesterday, when I was young等。","examCorrectAnswer":"kept","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["一般过去时陈述句：描述过去发生的动作或存在的状态，谓语动词用过去式。时间状语有yesterday, last week,"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-004');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-034-004', 'en-kp-034-03', 'en-q-034-004', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-034-004');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-005', 'en-repo-034', '5', 'Her cousin Colin ___ (be) ill in bed then.（她的表弟科林那时卧病在床。）', 'FillBlank', '{"id":"en-q-034-005","title":"Her cousin Colin ___ (be) ill in bed then.（她的表弟科林那时卧病在床。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["一般过去时陈述句：描述过去发生的动作或存在的状态，谓语动词用过去式。时间状语有yesterday, last week,"],"examAnalysis":"考查知识点：一般过去时陈述句——be动词用was/were（本单元语法点3）。为什么填这个：主语Colin是单数，then表过去，be动词用was。相关规则：描述过去存在的状态用主语+was/were+表语。","examCorrectAnswer":"was","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["一般过去时陈述句：描述过去发生的动作或存在的状态，谓语动词用过去式。时间状语有yesterday, last week,"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-005');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-034-005', 'en-kp-034-03', 'en-q-034-005', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-034-005');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-006', 'en-repo-034', '6', 'They ___ (work) together to bring the garden back to life.（他们一起努力让花园恢复了生机。）', 'FillBlank', '{"id":"en-q-034-006","title":"They ___ (work) together to bring the garden back to life.（他们一起努力让花园恢复了生机。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["一般过去时陈述句：描述过去发生的动作或存在的状态，谓语动词用过去式。时间状语有yesterday, last week,"],"examAnalysis":"考查知识点：一般过去时陈述句——规则动词加-ed（本单元语法点3）。为什么填这个：描述过去的动作，work是规则动词，过去式直接加-ed为worked。相关规则：一般过去时陈述句主语+动词过去式+其他。","examCorrectAnswer":"worked","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["一般过去时陈述句：描述过去发生的动作或存在的状态，谓语动词用过去式。时间状语有yesterday, last week,"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-006');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-034-006', 'en-kp-034-03', 'en-q-034-006', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-034-006');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-007', 'en-repo-034', '7', 'Books bring not only joy ___ also knowledge to children.（书不仅给孩子们带来快乐，也带来知识。）', 'FillBlank', '{"id":"en-q-034-007","title":"Books bring not only joy ___ also knowledge to children.（书不仅给孩子们带来快乐，也带来知识。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["并列连词not only...but also...：表示''不仅……而且……''，连接两个并列成分。"],"examAnalysis":"考查知识点：并列连词not only...but also...（本单元语法点4）。为什么填这个：not only...but also...是固定搭配，意为''不仅……而且……''，故填but。相关规则：not only...but also...连接两个并列成分。","examCorrectAnswer":"but","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["并列连词not only...but also...：表示''不仅……而且……''，连接两个并列成分。"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-007');
