INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-008', 'en-repo-034', '8', '— Did you read this book last year? — ___', 'Radio', '{"id":"en-q-034-008","title":"— Did you read this book last year? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["Did引导的一般过去时一般疑问句：Did+主语+动词原形+其他？肯定回答Yes,主语+did. 否定回答No,主语+di"],"examAnalysis":"考查知识点：Did一般疑问句的回答（本单元语法点1）。为什么选A：Did开头的问句肯定回答用Yes, I did。错误项：B项do是现在时；C项No与did矛盾；D项was是be动词，不回答did问句。相关规则：第三人称单数也用Did，回答统一用did/didn''t。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, I did.","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Yes, I do.","attribute":{}},{"id":"c","title":"No, I did.","attribute":{}},{"id":"d","title":"Yes, I was.","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["Did引导的一般过去时一般疑问句：Did+主语+动词原形+其他？肯定回答Yes,主语+did. 否定回答No,主语+di"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-008');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-034-008', 'en-kp-034-01', 'en-q-034-008', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-034-008');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-009', 'en-repo-034', '9', '— Did he ___ the book yesterday? — No, he didn''t.', 'Radio', '{"id":"en-q-034-009","title":"— Did he ___ the book yesterday? — No, he didn''t.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["Did引导的一般过去时一般疑问句：Did+主语+动词原形+其他？肯定回答Yes,主语+did. 否定回答No,主语+di"],"examAnalysis":"考查知识点：Did后接动词原形（本单元语法点1）。为什么选B：Did后必须接动词原形read（read原形与过去式同形，但此处Did后用原形）。错误项：A项readed是错误拼写；C项reads是三单；D项reading是现在分词。相关规则：Did+主语+动词原形。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"readed","attribute":{}},{"id":"b","title":"read","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"reads","attribute":{}},{"id":"d","title":"reading","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["Did引导的一般过去时一般疑问句：Did+主语+动词原形+其他？肯定回答Yes,主语+did. 否定回答No,主语+di"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-009');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-034-009', 'en-kp-034-01', 'en-q-034-009', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-034-009');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-010', 'en-repo-034', '10', '— Were there many books on the shelf? — ___', 'Radio', '{"id":"en-q-034-010","title":"— Were there many books on the shelf? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./N"],"examAnalysis":"考查知识点：Were there问句的回答（本单元语法点2）。为什么选D：many books是复数，Were there...?的肯定回答用Yes, there were。错误项：A、B项was/wasn''t用于单数；C项they不能用于there be句型回答。相关规则：复数用there were/weren''t回答。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, there was.","attribute":{}},{"id":"b","title":"No, there wasn''t.","attribute":{}},{"id":"c","title":"Yes, they were.","attribute":{}},{"id":"d","title":"Yes, there were.","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["there be句型一般过去时疑问句：Were there+名词复数+地点/时间？回答Yes,there were./N"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-010');
