INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-013', 'en-repo-034', '13', 'Books bring not only joy ___ also knowledge.', 'Radio', '{"id":"en-q-034-013","title":"Books bring not only joy ___ also knowledge.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["并列连词not only...but also...：表示''不仅……而且……''，连接两个并列成分。"],"examAnalysis":"考查知识点：not only...but also...固定搭配（本单元语法点4）。为什么选B：not only后必须搭配but also。错误项：A项and、C项or、D项so都不能与not only构成固定搭配。相关规则：not only...but also...意为''不仅……而且……''。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"and","attribute":{}},{"id":"b","title":"but","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"or","attribute":{}},{"id":"d","title":"so","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["并列连词not only...but also...：表示''不仅……而且……''，连接两个并列成分。"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-013');
