INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-014', 'en-repo-034', '14', '— What''s your favourite book? — My favourite book is a novel. — ___ kind of books do you like best? — I like adventure stories best.', 'Radio', '{"id":"en-q-034-014","title":"— What''s your favourite book? — My favourite book is a novel. — ___ kind of books do you like best? — I like adventure stories best.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["Unit 3 重点句型"],"examAnalysis":"考查知识点：询问喜欢哪种书的句型（本单元重点句What kind of books do you like best?）。为什么选A：What kind of...?是固定问法，意为''哪一种……''。错误项：B项Where问地点、C项When问时间、D项Who问人，均不与kind of books搭配。相关规则：What kind of books do you like best? 回答I like...best.","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"What","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Where","attribute":{}},{"id":"c","title":"When","attribute":{}},{"id":"d","title":"Who","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["Unit 3 重点句型"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-014');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-034-014', 'en-kp-034-05', 'en-q-034-014', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-034-014');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-034-015', 'en-repo-034', '15', '— What ___ the book about? — It ___ about a boy and his garden.', 'Radio', '{"id":"en-q-034-015","title":"— What ___ the book about? — It ___ about a boy and his garden.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["Unit 3 重点句型"],"examAnalysis":"考查知识点：What was...about?询问书的内容（本单元重点句型）。为什么选D：询问过去那本书的内容，主语the book/it都是单数，be动词用was。错误项：A项is与were不一致、时态不当；B项were与单数主语the book搭配错误；C项did是助动词，不能与about搭配。相关规则：What was the book about? It was about...","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"is; were","attribute":{}},{"id":"b","title":"were; was","attribute":{}},{"id":"c","title":"did; was","attribute":{}},{"id":"d","title":"was; was","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["Unit 3 重点句型"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-034-015');
