INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-035-007', 'en-repo-035', '7', 'The dumpling dates ___ to the Tang Dynasty.（这种饺子可以追溯到唐朝。）', 'FillBlank', '{"id":"en-q-035-007","title":"The dumpling dates ___ to the Tang Dynasty.（这种饺子可以追溯到唐朝。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["Unit 4 重点句型"],"examAnalysis":"考查知识点：固定短语date back to（本单元重点句子）。为什么填这个：date back to意为''追溯到、始于''，是固定搭配，故填back。相关规则：date back to+时间，表示某事物可追溯到某朝代/时期。","examCorrectAnswer":"back","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["Unit 4 重点句型"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-035-007');
