INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-035-009', 'en-repo-035', '9', 'How ___ dumplings come to Xinjiang?', 'Radio', '{"id":"en-q-035-009","title":"How ___ dumplings come to Xinjiang?","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["一般过去时特殊疑问句：对动作提问用 What/How/When+did+主语+动词原形？；对状态提问用 Why/How+"],"examAnalysis":"考查知识点：How+did+主语+动词原形（本单元语法点1）。为什么选A：come是实义动词原形，过去时特殊疑问句用did。错误项：B、C项was/were是be动词，后不接动词原形come；D项do是现在时，与过去语境不符。相关规则：对过去动作提问用did。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"did","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"was","attribute":{}},{"id":"c","title":"were","attribute":{}},{"id":"d","title":"do","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["一般过去时特殊疑问句：对动作提问用 What/How/When+did+主语+动词原形？；对状态提问用 Why/How+"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-035-009');
