INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-035-010', 'en-repo-035', '10', 'People ___ them along the Silk Road long ago.', 'Radio', '{"id":"en-q-035-010","title":"People ___ them along the Silk Road long ago.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["一般过去时肯定句：be动词用主语+was/were+表语；实义动词用主语+动词过去式。不规则变化：go→went, do"],"examAnalysis":"考查知识点：bring的过去式（本单元语法点2）。为什么选D：long ago表过去，bring过去式brought。错误项：A项bringed错误拼写；B项brings现在时三单；C项bring原形。相关规则：bring→brought，不规则变化。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"bringed","attribute":{}},{"id":"b","title":"brings","attribute":{}},{"id":"c","title":"bring","attribute":{}},{"id":"d","title":"brought","attribute":{"examCorrectAnswer":"d"}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["一般过去时肯定句：be动词用主语+was/were+表语；实义动词用主语+动词过去式。不规则变化：go→went, do"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-035-010');
