INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-035-013', 'en-repo-035', '13', '— Was Xinjiang an important trade centre? — ___', 'Radio', '{"id":"en-q-035-013","title":"— Was Xinjiang an important trade centre? — ___","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 4","section":"重点语法与句型","knowledgePoint":["一般过去时一般疑问句：实义动词用 Did+主语+动词原形？回答Yes,...did./No,...didn''t.；be动"],"examAnalysis":"考查知识点：Was/Were一般疑问句的回答（本单元语法点3）。为什么选A：Was问句肯定回答用Yes, it was。错误项：B项did回答实义动词did问句；C项No与was矛盾；D项is是现在时。相关规则：be动词过去时疑问句回答用was/were。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"Yes, it was.","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"Yes, it did.","attribute":{}},{"id":"c","title":"No, it was.","attribute":{}},{"id":"d","title":"Yes, it is.","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 4"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 4', '重点语法与句型', '["一般过去时一般疑问句：实义动词用 Did+主语+动词原形？回答Yes,...did./No,...didn''t.；be动"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-035-013');
