INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-037-004', 'en-repo-037', '4', 'Now the streets ___ (be) still full of bikes.（现在街道上仍然满是自行车。）', 'FillBlank', '{"id":"en-q-037-004","title":"Now the streets ___ (be) still full of bikes.（现在街道上仍然满是自行车。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["一般过去时与一般现在时对比：用was/were描述过去状态，用is/are/looks描述现在状态，通过系动词时态变化体"],"examAnalysis":"考查知识点：一般现在时描述现在状态（本单元语法点1、3）。为什么填这个：Now表现在，streets是复数，用are，与上句过去时were形成对比。相关规则：现在状态用is/are/looks+形容词或介词短语。","examCorrectAnswer":"are","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["一般过去时与一般现在时对比：用was/were描述过去状态，用is/are/looks描述现在状态，通过系动词时态变化体"]', 'medium', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-037-004');
