INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-037-015', 'en-repo-037', '15', 'Today, there ___ lots of buildings and roads in my hometown.', 'Radio', '{"id":"en-q-037-015","title":"Today, there ___ lots of buildings and roads in my hometown.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 6","section":"重点语法与句型","knowledgePoint":["一般过去时与一般现在时对比：用was/were描述过去状态，用is/are/looks描述现在状态，通过系动词时态变化体"],"examAnalysis":"考查知识点：现在状态there be句型（本单元语法点1、3）。为什么选B：Today表现在，lots of buildings是复数，用are。错误项：A项is用于单数；C、D项was/were是过去时，与Today不符。相关规则：现在存在的状态用there is/are，复数用are。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"is","attribute":{}},{"id":"b","title":"are","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"was","attribute":{}},{"id":"d","title":"were","attribute":{}}]}', 'exam', '单元练习', '["外研版","五年级","下册","Unit 6"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 6', '重点语法与句型', '["一般过去时与一般现在时对比：用was/were描述过去状态，用is/are/looks描述现在状态，通过系动词时态变化体"]', 'hard', '五年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-037-015');
