INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-001', 'en-repo-038', '1', '— How much ___ the robot? — It''s 35 yuan.（— 这个机器人多少钱？— 35元。）', 'FillBlank', '{"id":"en-q-038-001","title":"— How much ___ the robot? — It''s 35 yuan.（— 这个机器人多少钱？— 35元。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"],"examAnalysis":"考查how much询问价格的用法（Unit 1语法点1）。How much + is + 单数/不可数名词？询问单件物品价格，回答用It''s + 价格。句中robot是单数名词，故用is：How much is the robot?。","examCorrectAnswer":"is","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-038-001', 'en-kp-038-01', 'en-q-038-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-038-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-002', 'en-repo-038', '2', '— How much ___ the cupcakes? — They''re 10 yuan.（— 这些纸杯蛋糕多少钱？— 它们10元。）', 'FillBlank', '{"id":"en-q-038-002","title":"— How much ___ the cupcakes? — They''re 10 yuan.（— 这些纸杯蛋糕多少钱？— 它们10元。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"],"examAnalysis":"考查how much询问价格的用法（Unit 1语法点1）。How much + are + 复数名词？询问多件物品价格，回答用They''re + 价格。句中cupcakes是复数名词，故用are：How much are the cupcakes?。","examCorrectAnswer":"are","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-002');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-038-002', 'en-kp-038-01', 'en-q-038-002', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-038-002');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-003', 'en-repo-038', '3', 'Sam always ___ (spend) his money on toys.（萨姆总是把钱花在玩具上。）', 'FillBlank', '{"id":"en-q-038-003","title":"Sam always ___ (spend) his money on toys.（萨姆总是把钱花在玩具上。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["一般现在时表示经常性、习惯性的动作或状态，常与every week, always, usually等时间状语连用；第三"],"examAnalysis":"考查一般现在时第三人称单数（Unit 1语法点2）。句中有always（总是）表经常性动作，用一般现在时；主语Sam是第三人称单数，动词spend要加-s变spends，故填spends。注意spend money on sth意为''在某物上花钱''。","examCorrectAnswer":"spends","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["一般现在时表示经常性、习惯性的动作或状态，常与every week, always, usually等时间状语连用；第三"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-003');
