INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-004', 'en-repo-038', '4', 'Amy usually ___ (save) her money.（艾米通常存钱。）', 'FillBlank', '{"id":"en-q-038-004","title":"Amy usually ___ (save) her money.（艾米通常存钱。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["一般现在时表示经常性、习惯性的动作或状态，常与every week, always, usually等时间状语连用；第三"],"examAnalysis":"考查一般现在时第三人称单数（Unit 1语法点2）。句中有usually（通常）表习惯性动作，用一般现在时；主语Amy是第三人称单数，动词save加-s变saves，故填saves。save money意为''存钱''。","examCorrectAnswer":"saves","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["一般现在时表示经常性、习惯性的动作或状态，常与every week, always, usually等时间状语连用；第三"]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-004');
