INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-007', 'en-repo-038', '7', 'His dream ___（实现）at last.（他的梦想终于实现了。）', 'FillBlank', '{"id":"en-q-038-007","title":"His dream ___（实现）at last.（他的梦想终于实现了。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn."],"examAnalysis":"考查动词短语come true（Unit 1语法点3）。come true意为''实现''，dream是主语；一般现在时下主语His dream是第三人称单数，come要变comes，故填comes true。注意come true是不及物动词短语，后不接宾语。","examCorrectAnswer":"comes true","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["动词短语：save money存钱；spend money on sth在某物上花钱；come true实现；turn."]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-007');
