INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-010', 'en-repo-038', '10', 'Sam always ___ his money on computer games.', 'Radio', '{"id":"en-q-038-010","title":"Sam always ___ his money on computer games.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["一般现在时表示经常性、习惯性的动作或状态，常与every week, always, usually等时间状语连用；第三"],"examAnalysis":"考查一般现在时第三人称单数（Unit 1语法点2）。always（总是）表明用一般现在时，主语Sam是第三人称单数，动词要用三单形式spends，故B正确。A项spend用于非三单主语，C项spending是现在分词不能单独作谓语，D项spent是过去式，与always表经常性动作不符。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"spend","attribute":{}},{"id":"b","title":"spends","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"spending","attribute":{}},{"id":"d","title":"spent","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["一般现在时表示经常性、习惯性的动作或状态，常与every week, always, usually等时间状语连用；第三"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-010');
