INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-011', 'en-repo-038', '11', 'It''s a good thing for us to share with people ___ need.（和需要帮助的人分享对我们来说是一件好事。）', 'Radio', '{"id":"en-q-038-011","title":"It''s a good thing for us to share with people ___ need.（和需要帮助的人分享对我们来说是一件好事。）","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["Unit 1 重点句型"],"examAnalysis":"考查固定短语in need（Unit 1重点句子）。people in need意为''需要帮助的人''，in need是固定搭配。B项on need、C项at need、D项for need均无此用法，故A正确。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"in","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"on","attribute":{}},{"id":"c","title":"at","attribute":{}},{"id":"d","title":"for","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["Unit 1 重点句型"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-011');
