INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-038-013', 'en-repo-038', '13', '下面哪个句子是正确的？', 'Radio', '{"id":"en-q-038-013","title":"下面哪个句子是正确的？","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 1","section":"重点语法与句型","knowledgePoint":["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"],"examAnalysis":"考查how much询问价格的句式（Unit 1语法点1）。单数名词用How much is…?，复数名词用How much are…?。cupcakes是复数，故C项How much are the cupcakes?正确。A项复数用了is，B项单数robot用了are，D项语序错误，均排除。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"How much is the cupcakes?","attribute":{}},{"id":"b","title":"How much are the robot?","attribute":{}},{"id":"c","title":"How much are the cupcakes?","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"How much the cupcakes is?","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 1"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 1', '重点语法与句型', '["how much引导特殊疑问句询问价格：How much + is + 单数/不可数名词？回答用It''s + 价格；Ho"]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-038-013');
