INSERT INTO t_knowledge_point (id, section_id, name, sort, grade, term, importance, content, image_url, is_deleted, create_at, create_by) SELECT 'en-kp-039-04', 'en-sec-039', 'Unit 2 重点句型', '4', '六年级', '上册', 'key', '{"points":["Unit 2 重点句型"]}', NULL, '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point WHERE id = 'en-kp-039-04');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-001', 'en-repo-039', '1', 'Apples are ___ (healthy) than sweet cakes.（苹果比甜蛋糕更健康。）', 'FillBlank', '{"id":"en-q-039-001","title":"Apples are ___ (healthy) than sweet cakes.（苹果比甜蛋糕更健康。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。"],"examAnalysis":"考查形容词比较级句型（Unit 2语法点1）。句中有than表示两者比较，要用比较级；healthy是以辅音字母+y结尾的双音节词，变y为i加-er，故填healthier。句型结构为 A + be + 比较级 + than + B，表示A比B更……。","examCorrectAnswer":"healthier","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-039-001', 'en-kp-039-01', 'en-q-039-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-039-001');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-002', 'en-repo-039', '2', 'This box is ___ (big) than that one.（这个盒子比那个大。）', 'FillBlank', '{"id":"en-q-039-002","title":"This box is ___ (big) than that one.（这个盒子比那个大。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"],"examAnalysis":"考查形容词比较级规则变化（Unit 2语法点2）。big是重读闭音节单词，末尾只有一个辅音字母，要双写尾字母g再加-er，故填bigger。than是比较级标志词。","examCorrectAnswer":"bigger","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-002');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-039-002', 'en-kp-039-02', 'en-q-039-002', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-039-002');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-003', 'en-repo-039', '3', 'My bag is ___ (nice) than yours.（我的包比你的好看。）', 'FillBlank', '{"id":"en-q-039-003","title":"My bag is ___ (nice) than yours.（我的包比你的好看。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"],"examAnalysis":"考查形容词比较级规则变化（Unit 2语法点2）。nice以不发音的e结尾，比较级直接加-r，故填nicer。","examCorrectAnswer":"nicer","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-003');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-039-003', 'en-kp-039-02', 'en-q-039-003', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-039-003');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-004', 'en-repo-039', '4', 'Mary feels ___ (happy) today than yesterday.（玛丽今天比昨天更开心。）', 'FillBlank', '{"id":"en-q-039-004","title":"Mary feels ___ (happy) today than yesterday.（玛丽今天比昨天更开心。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"],"examAnalysis":"考查形容词比较级规则变化（Unit 2语法点2）。happy以辅音字母+y结尾，变y为i再加-er，故填happier。注意主语Mary是第三人称单数，feel用了feels，不影响比较级变形。","examCorrectAnswer":"happier","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-004');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-039-004', 'en-kp-039-02', 'en-q-039-004', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-039-004');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-005', 'en-repo-039', '5', 'In my ___, this book is very interesting.（在我看来，这本书很有趣。）', 'FillBlank', '{"id":"en-q-039-005","title":"In my ___, this book is very interesting.（在我看来，这本书很有趣。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."],"examAnalysis":"考查表达观点的句型（Unit 2语法点3）。In my opinion是固定短语，意为''在我看来、依我看''，opinion用单数。原句为In my opinion, this book is very interesting.，故填opinion。","examCorrectAnswer":"opinion","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-005');
