INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-007', 'en-repo-039', '7', 'I don''t think ___.（我不这么认为。）', 'FillBlank', '{"id":"en-q-039-007","title":"I don''t think ___.（我不这么认为。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["Unit 2 重点句型"],"examAnalysis":"考查表达观点的日常用语（Unit 2重点句子）。I don''t think so.是固定表达，意为''我不这么认为''，用来不同意对方看法，so不能换成it/that。","examCorrectAnswer":"so","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["Unit 2 重点句型"]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-007');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-039-007', 'en-kp-039-04', 'en-q-039-007', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-039-007');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-008', 'en-repo-039', '8', 'Apples are ___ than sweet cakes.', 'Radio', '{"id":"en-q-039-008","title":"Apples are ___ than sweet cakes.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。"],"examAnalysis":"考查形容词比较级句型（Unit 2语法点1）。句中有than，需用比较级；healthy的比较级为healthier，故选B。A项healthy是原级，不能与than连用；C项more healthier错误，比较级前不能再加more；D项healthiest是最高级，用于三者及以上。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"healthy","attribute":{}},{"id":"b","title":"healthier","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"more healthier","attribute":{}},{"id":"d","title":"healthiest","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-008');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-039-008', 'en-kp-039-01', 'en-q-039-008', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-039-008');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-009', 'en-repo-039', '9', 'Which is the comparative (比较级) of "tall"?', 'Radio', '{"id":"en-q-039-009","title":"Which is the comparative (比较级) of \"tall\"?","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"],"examAnalysis":"考查比较级规则变化（Unit 2语法点2）。tall是一般单音节词，直接加-er变taller，故选C。A项tallest是最高级；B项more tall错误，单音节词比较级不加more；D项tallier拼写错误。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"tallest","attribute":{}},{"id":"b","title":"more tall","attribute":{}},{"id":"c","title":"taller","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"tallier","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-009');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-039-009', 'en-kp-039-02', 'en-q-039-009', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-039-009');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-010', 'en-repo-039', '10', 'Which is the comparative (比较级) of "beautiful"?', 'Radio', '{"id":"en-q-039-010","title":"Which is the comparative (比较级) of \"beautiful\"?","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"],"examAnalysis":"考查多音节词比较级（Unit 2语法点2）。beautiful是多音节词，比较级在前面加more，即more beautiful，故选B。A、D项把beautiful变成-er/-est是错误的；D项most beautiful是最高级，不是比较级。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"beautifuler","attribute":{}},{"id":"b","title":"more beautiful","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"beautifulest","attribute":{}},{"id":"d","title":"most beautiful","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级规则变化：一般加-er；不发音e结尾加-r；重读闭音节双写尾字母加-er；辅音+y结尾变y为i加-er；多音"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-010');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-039-010', 'en-kp-039-02', 'en-q-039-010', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-039-010');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-011', 'en-repo-039', '11', 'This ruler is longer ___ that one.', 'Radio', '{"id":"en-q-039-011","title":"This ruler is longer ___ that one.","type":"Radio","attribute":{"subject":"英语","difficulty":"medium","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。"],"examAnalysis":"考查比较级句型的连接词（Unit 2语法点1）。''A + be + 比较级 + than + B''中than用来引出比较对象，意为''比''，故选B。A项then是副词''然后''，不能引出比较对象；C项as用于原级比较as...as；D项that不能用于此结构。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"then","attribute":{}},{"id":"b","title":"than","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"as","attribute":{}},{"id":"d","title":"that","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。"]', 'medium', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-011');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-039-011', 'en-kp-039-01', 'en-q-039-011', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-039-011');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-012', 'en-repo-039', '12', 'Why not ___ to the park with us?', 'Radio', '{"id":"en-q-039-012","title":"Why not ___ to the park with us?","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."],"examAnalysis":"考查Why not提建议句型（Unit 2语法点3）。Why not后接动词原形，意为''为什么不……呢？''，故选C项go。A项going是动名词、B项goes是三单、D项went是过去式，都不能跟在Why not后面。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"going","attribute":{}},{"id":"b","title":"goes","attribute":{}},{"id":"c","title":"go","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"went","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-012');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-039-012', 'en-kp-039-03', 'en-q-039-012', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-039-012');
INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-013', 'en-repo-039', '13', '___, this book is very interesting.', 'Radio', '{"id":"en-q-039-013","title":"___, this book is very interesting.","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."],"examAnalysis":"考查表达观点的固定短语（Unit 2语法点3）。''在我看来''是In my opinion，介词用in，opinion用单数，故选B。A、C项介词错误；D项opinions用复数，习惯上用单数。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"On my opinion","attribute":{}},{"id":"b","title":"In my opinion","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"At my opinion","attribute":{}},{"id":"d","title":"In my opinions","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["提出建议用\"Why not + 动词原形…?\"（为什么不……呢？）；表达观点用\"In my opinion, + 句子."]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-013');
