INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-014', 'en-repo-039', '14', '"An apple a day keeps the doctor away." 的意思是？', 'Radio', '{"id":"en-q-039-014","title":"\"An apple a day keeps the doctor away.\" 的意思是？","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["Unit 2 重点句型"],"examAnalysis":"考查本单元谚语理解（Unit 2重点句子）。原句是英语谚语，意为''一天一苹果，医生远离我''，即常吃苹果有益健康，故选A。B、C、D项都是望文生义的错误理解。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"一天一苹果，医生远离我","attribute":{"examCorrectAnswer":"a"}},{"id":"b","title":"一天吃一个医生","attribute":{}},{"id":"c","title":"苹果比医生贵","attribute":{}},{"id":"d","title":"医生喜欢吃苹果","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["Unit 2 重点句型"]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-014');
