INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-039-015', 'en-repo-039', '15', 'Apples without peel taste ___.', 'Radio', '{"id":"en-q-039-015","title":"Apples without peel taste ___.","type":"Radio","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 2","section":"重点语法与句型","knowledgePoint":["形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。"],"examAnalysis":"考查比较级用法（Unit 2语法点1/重点句子）。原句Apples without peel taste sweeter.（去皮的苹果尝起来更甜），sweet的比较级直接加-er变sweeter，故选C。A项sweetest是最高级；B项more sweet错误，单音节词不加more；D项sweet是原级，不能表示''更甜''的比较含义。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"sweetest","attribute":{}},{"id":"b","title":"more sweet","attribute":{}},{"id":"c","title":"sweeter","attribute":{"examCorrectAnswer":"c"}},{"id":"d","title":"sweet","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 2"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 2', '重点语法与句型', '["形容词比较级：A + be动词 + 形容词比较级 + than + B，表示A比B更……。"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-039-015');
