INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-040-001', 'en-repo-040', '1', 'Mount Qomolangma is the world''s ___ (high) mountain.（珠穆朗玛峰是世界上最高的山。）', 'FillBlank', '{"id":"en-q-040-001","title":"Mount Qomolangma is the world''s ___ (high) mountain.（珠穆朗玛峰是世界上最高的山。）","type":"FillBlank","attribute":{"subject":"英语","difficulty":"hard","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["形容词最高级：主语 + be动词 + the + 形容词最高级 + 范围(in/of...)，表示三者或以上中最……的，"],"examAnalysis":"考查形容词最高级（Unit 3语法点1）。''世界上最高的山''是三者以上范围中的最高，用最高级；high是一般单音节词，直接加-est变highest，前面已有the world''s修饰，故填highest。","examCorrectAnswer":"highest","examAnswerMode":"selectAll","examMatchRule":"completeSame"},"children":[{"id":"c1","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["形容词最高级：主语 + be动词 + the + 形容词最高级 + 范围(in/of...)，表示三者或以上中最……的，"]', 'hard', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-040-001');
INSERT INTO t_knowledge_point_question (id, knowledge_point_id, question_id, is_deleted, create_at, create_by) SELECT 'en-kpq-040-001', 'en-kp-040-01', 'en-q-040-001', '0', CURRENT_TIMESTAMP, '1457995481966747649' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_knowledge_point_question WHERE id = 'en-kpq-040-001');
