INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'en-q-040-014', 'en-repo-040', '14', '下面哪个句子是正确的？', 'Radio', '{"id":"en-q-040-014","title":"下面哪个句子是正确的？","type":"Radio","attribute":{"subject":"英语","difficulty":"easy","chapter":"Unit 3","section":"重点语法与句型","knowledgePoint":["形容词最高级：主语 + be动词 + the + 形容词最高级 + 范围(in/of...)，表示三者或以上中最……的，"],"examAnalysis":"考查最高级句型（Unit 3语法点1/重点句子）。形容词最高级前要加the，''世界上''是in the world，需要定冠词the，故B正确。A项in world少the；C项Longest前缺the；D项longer是比较级，不能表示''世界最长''。","examAnswerMode":"onlyOne"},"children":[{"id":"a","title":"The longest river in world is the Nile.","attribute":{}},{"id":"b","title":"The longest river in the world is the Nile.","attribute":{"examCorrectAnswer":"b"}},{"id":"c","title":"Longest river in the world is the Nile.","attribute":{}},{"id":"d","title":"The longer river in the world is the Nile.","attribute":{}}]}', 'exam', '单元练习', '["外研版","六年级","上册","Unit 3"]', NULL, NULL, '0', '0', CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Unit 3', '重点语法与句型', '["形容词最高级：主语 + be动词 + the + 形容词最高级 + 范围(in/of...)，表示三者或以上中最……的，"]', 'easy', '六年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'en-q-040-014');
