INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0147', 'want 的用法：want + 名词/代词 表示"想要某物"；want to + 动词原形 表示"想要做某事"；want sb to do sth 表示"想要某人做某事"。主语为第三人称单数时 want 变为 wants。', 'want 的用法：want + 名词/代词 表示"想要某物"；want to + 动词原形 表示"想要做某事"；want sb to do sth 表示"想要某人做某事"。主语为第三人称单数时 want 变为 wants。', '["I want a hamburger. / She wants an ice cream. / I want to go to the park. / My mother wants me to clean the bedroom."]', '外研版', '六年级', '下册', 'Unit 1', NULL, '1' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0147');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0148', '询问对方需求：What do you want? 回答用 I want + 某物。委婉说法用 What would you like? 回答 I''d like...（I''d = I would），接动作时用 I would like to do sth。', '询问对方需求：What do you want? 回答用 I want + 某物。委婉说法用 What would you like? 回答 I''d like...（I''d = I would），接动作时用 I would like to do sth。', '["—What do you want? —I want a hot dog, please. / —What would you like? —I''d like a cup of coffee."]', '外研版', '六年级', '下册', 'Unit 1', NULL, '2' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0148');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0149', 'look 作系动词意为"看上去"，后接形容词；look 还可作实义动词"看"。常见短语：look for 寻找，look out 当心，look after 照顾，look like 看起来像。', 'look 作系动词意为"看上去"，后接形容词；look 还可作实义动词"看"。常见短语：look for 寻找，look out 当心，look after 照顾，look like 看起来像。', '["The cake looks good. / Look! There is a dog over there. / Please look after your little sister."]', '外研版', '六年级', '下册', 'Unit 1', NULL, '3' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0149');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0150', 'How much 引导特殊疑问句询问价格：How much + is/are + 物品？回答 It''s/They''re + 价格。How much 还可询问不可数名词的数量。', 'How much 引导特殊疑问句询问价格：How much + is/are + 物品？回答 It''s/They''re + 价格。How much 还可询问不可数名词的数量。', '["—How much is this pen? —It''s thirteen yuan. / —How much are the books? —They''re fifty yuan. / How much water do you want?"]', '外研版', '六年级', '下册', 'Unit 1', NULL, '4' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0150');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0151', 'enjoy 作及物动词：①后接名词或代词；②后接动词-ing 形式；③enjoy oneself = have a good time 意为"玩得开心"。', 'enjoy 作及物动词：①后接名词或代词；②后接动词-ing 形式；③enjoy oneself = have a good time 意为"玩得开心"。', '["They are enjoying their dinner. / He doesn''t enjoy singing. / Did you enjoy yourself at the party?"]', '外研版', '六年级', '下册', 'Unit 1', NULL, '5' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0151');
