INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0154', '现在进行时：Be (am/is/are) + doing(现在分词)。表示正在发生的动作或事情，通常与now连用。（M3U2教案原文板书设计）', '现在进行时：Be (am/is/are) + doing(现在分词)。表示正在发生的动作或事情，通常与now连用。（M3U2教案原文板书设计）', '["The sun is shining. / The cows are drinking water. / What are you doing? I am cleaning my room."]', '外研版', '六年级', '下册', 'Unit 3', NULL, '1' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0154');
INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0155', '现在进行时特殊疑问句：What are/is + 主语 + doing? 回答用主语 + be + doing。（M3U2教案原文教学重点）', '现在进行时特殊疑问句：What are/is + 主语 + doing? 回答用主语 + be + doing。（M3U2教案原文教学重点）', '["—What are cows doing? —The cows are drinking water. / —What are you doing? —I am cleaning my room."]', '外研版', '六年级', '下册', 'Unit 3', NULL, '2' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0155');
