INSERT INTO t_english_grammar (id, title, content, examples, version, grade, term, unit, section, sort) SELECT 'egwy0157', '现在进行时 Be + doing：表示正在进行的动作。（M5U1教案原文：学习并掌握Be+doing现在进行时结构）', '现在进行时 Be + doing：表示正在进行的动作。（M5U1教案原文：学习并掌握Be+doing现在进行时结构）', '["Daming is having a birthday party. / He is playing the suona."]', '外研版', '六年级', '下册', 'Unit 5', NULL, '1' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_grammar WHERE id = 'egwy0157');
