INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00225', 'exciting', '/ɪkˈsaɪtɪŋ/', 'adj. 令人兴奋的，令人激动的；惊险刺激的（尤指无法预知下一步将发生什么）；v. 使兴奋，使激动；激发，引起（excite 的现在分词形式）', 'This piece of equipment is an exciting new development.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'exciting');
