INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00229', 'watery', '/ˈwɔːtəri/', 'adj. 含水的，水状的，似水的；（眼睛）泪汪汪的，水汪汪的，湿润的；（食物或饮料）稀薄的，淡而无味的；（光线、颜色等）淡的，微弱的；（土壤、地面等）湿的，浸水的；软绵绵的，松软的；有雨意的，像要下雨的', 'His eyes were a watery blue.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'watery');
