INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00233', 'touch', '/tʌtʃ/', 'v. 触摸，碰；接触，触及；损坏，伤害；吃，喝，使用；感动，触动；影响，与……有关；与……媲美，比得上；达到（某一水平等）；参与，涉及；处理，做（某事）；（在脸上）闪现，掠过；轻轻击（球）；具有……特性；<非正式>向（某人）讨要（物品）；跑垒得分；（几何）与（曲线，表面）切触；（用画笔、铅笔）轻轻勾勒；n. 触觉，触感；触摸，碰；触摸时的感觉；润色，装点；作风，风格，手法；一点儿，少许；略微，稍微；边线以外的区域；触球，控球；（音乐家的）触键法，弹奏法；（乐器键、弦的）弹性，弹力；（钢笔、铅笔等的）轻触；转调较少的钟乐；【名】 （Touch）（柬）杜（人名）', 'Don''t touch that plate—it''s hot!', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'touch');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00234', 'sunless', '/ˈsʌnləs/', 'adj. 无阳光的，阳光照射不到的，阴暗的', 'Carmen stayed behind in the dark, sunless room.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'sunless');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00235', 'reason', '/ˈriːzən/', 'n. 原因，理由；充分理由，正当理由；道理，情理；判断力，理智；v. 推理，逻辑思考；推论出，推断出（reason sth. out）；对（某人）以理相劝，劝告（reason with）；【名】 （Reason）（英）里森（人名）', 'My sole reason for coming here was to see you.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'reason');
