INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00237', 'rich', '/rɪtʃ/', 'adj. 有钱的，富有的；富含……的，丰富的；非常有趣的，丰富多彩的；（食物）油腻的；（色彩、气味）浓郁的，（声音）浑厚的；肥沃的，丰产的；华丽昂贵的；<非正式>（指某人的评论或批评）荒唐的，可笑的；值钱的，生财的；（内燃机内的混合燃料）可燃性成分高的；【名】 （Rich）（丹）里克，（捷）里赫，（英、西）里奇，（葡、法）里什（人名）', 'Oranges are rich in vitamin C.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'rich');
