INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00239', 'bath', '/bɑːθ/', 'n. 浴缸，浴盆；洗澡，沐浴；浴室；池，盆；v. 给……洗澡；洗澡，沐浴', 'A bath can relax tense muscles.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'bath');
