INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00241', 'princess', '/ˈprɪnsɪs/', 'n. （除女王或王后外的）王室女成员，（尤指）公主；王妃，王公贵族夫人；（受宠溺而自以为优越的）娇小姐；<英，非正式>大小姐；小国女君主；出众的妇女（或事物），巾帼英雄；【名】 （Princess）（英）普琳西丝（人名）', 'She was like a princess in a fairy tale.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'princess');
