INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00244', 'believe', '/bɪˈliːv/', 'v. 相信；认为，猜想；信教', 'I believe in education for its own sake.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'believe');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00245', 'survey', '/ˈsɜːveɪ/', 'n. 民意调查，民意测验；考察，调查；（对课题或情况的）全面考察，概述；测量，勘测；测绘图，勘测记录；测量部门；<英> （尤指为欲购房者所做的）房屋鉴定；查勘报告；v. 做民意测验，做民意调查；（尤指认真地）审视，检查；测量，勘测；<英> （尤指为可能的买家）查勘，检视（建筑物的状况）；全面评述，概述', 'We would welcome your views about the survey.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'survey');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00246', 'instruction', '/ɪnˈstrʌkʃən/', 'n. 用法说明；指示，吩咐；教授，指导；（计算机的）指令，命令；给初级律师（或辩护律师、陪审团）的指示；adj. 说明用法的', 'Each candidate is given instruction in safety.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'instruction');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00247', 'empty', '/ˈempti/', 'adj. 空的；空洞的，无意义的；空虚的；无知的，愚蠢的；无用的，徒劳的；v. 清空；变空；流入；使失去；n. 空容器', 'Do not let the golden cup remain empty beneath the moon.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'empty');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00248', 'happen', '/ˈhæpən/', 'v. 发生；使遭遇；碰巧；adv. <北英格兰>或许，大概', 'We will never allow that to happen! No sir!', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'happen');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00249', 'presentation', '/ˌprezənˈteɪʃən/', 'n. （颁奖等）仪式，典礼；授予，颁发；（在仪式上接受的）奖项，赠予物；展示会，介绍会，发布会；陈述，报告，说明；（事物的）呈现方式；（证件等的）出示；（证物的）提交，提供；（戏剧的）演出；（胎儿的）先露位置，产位；（尤指在帝王前）正式引见，引……朝见；<史>（圣职等的）推荐', 'Computer graphics will give your presentation the professional touch.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'presentation');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00250', 'hat', '/hæt/', 'n. （常指带檐的）帽子；（双重的）职位，角色；v. 给……戴上帽子；供应帽子，制造帽子', 'She looks a sight in that hat!', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'hat');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00251', 'blow', '/bləʊ/', 'v. （风）刮，吹；（用嘴）吹气；吹响，吹奏；毁掉，炸毁；（轮胎）爆开，爆裂；（保险丝）烧断，熔化；擤（鼻子）；浪费，挥霍（金钱）；<非正式>出错，错失机会；泄露，暴露；<美，非正式>迅速离开（某地）；<美，非正式>用力投（球）；<英，非正式>讨厌，糟糕；开花；（鲸鱼）喷水；吹制（玻璃）；（苍蝇）产卵于；n. 大风，强风；吹气，擤鼻子；猛击，一击；奋斗，努力；打击，挫折；开花，开花期；<非正式>爵士乐演奏；<非正式>大麻；（炼钢用语）吹炼', 'Let''s blow out the candles together.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'blow');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00252', 'wave', '/weɪv/', 'v. 挥手；挥手示意；挥舞，挥动；飘扬，摆动，摇晃；使（头发）略呈波形；（威胁地）举起（某物）；n. 海浪；大海（the waves）；（活动、行为的）爆发，浪潮；涌现的人（或物）；挥手；波，波状运动；（头发的）卷曲；波浪形；（地震、爆炸的）冲击波；人浪（the wave）', 'The driver gave me a wave and a toot.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'wave');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00253', 'voice', '/vɔɪs/', 'n. 嗓音，说话声，歌唱声；发言权，表达意愿的权利；愿望，意见，呼声；（突然闪现的）想法，感觉；代言人，喉舌；（语法）语态；（语音）浊音；（文学作品或作者的）独特风格；（乐曲）声部；单音，单声；v. 表达，吐露（感情或意见）；（语音）发浊音；（乐）给（管风琴）调音', 'Her voice wobbled with emotion.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'voice');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00254', 'himself', '/hɪmˈself/', 'pron. 他自己；他亲自，他本人；<书面英语，泛指>他自己；by himself（或 all by himself）独自，独力', 'He was willing to make himself a servant of his art.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'himself');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00255', 'shame', '/ʃeɪm/', 'n. 羞耻，羞愧；羞耻心，羞耻感；令人惋惜的事，让人遗憾的事；耻辱，丢脸；带来耻辱的人（或行为、局面）；v. 使感到羞耻（或羞愧）；使蒙羞，使丢脸；使黯然失色，使相形见绌；int. <南非>（表示赞叹或喜爱）真可惜，好极了；（用于表示不赞同演讲者所说的话）可耻；【名】 （Shame）（科特）沙梅（人名）', 'She bowed her head in shame.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'shame');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00256', 'finally', '/ˈfaɪnəli/', 'adv. 终于；总之，最后；决定性地，不可变更地', 'He finally actualized his dream.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'finally');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00257', 'barber', '/ˈbɑːbə/', 'n. 理发师；（男子）理发店 （the barber''s）；v. 给（男子）理发；【名】 （Barber）（美）巴伯（人名）', 'I gave the barber a tip.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'barber');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00258', 'fall', '/fɔːl/', 'v. 降落，落下；跌倒，倒塌；（水平、数量、价格等）下跌，减少；属于；下垂，低垂；照射（到），（阴影）落在；降临，发生；倒台，失势；被打败，沦陷；阵亡，被击毙；打中，击中；（嗓音或声音）变轻，变小；进入（某状态），开始变成（某事物）；n. 落下，跌倒；（数量、水平、价格等的）下降，降低；秋天，秋季；失败，垮台 ；瀑布；（摔跤或柔道项目中的）摔倒，压倒；（雨、雪等的）降落；堕落；【名】 （Fall）（西）法勒（人名）', 'Let me fall if I must <b>fall</b>. The one I become will catch me.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'fall');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00259', 'shoulder', '/ˈʃəʊldə/', 'n. 肩，肩膀；双肩，上背部（shoulders）；（衣服的）肩部；（动物的）前腿连肩肉，肘子；山肩，瓶肩；<美> （公路旁的）路肩，紧急停车道；（担负责任或艰难困苦或提供力量的）肩膀；（四足动物的）肩背；（鸟、昆虫的）肩背；v. 承担，担负；挤，闯；（用肩膀）推开，顶开；肩扛，肩挑', 'Ralph tapped me on the shoulder.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'shoulder');
