INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00261', 'surprised', '/səˈpraɪzd/', 'adj. 意外的，惊讶的，诧异的；v. 使惊奇，使诧异，使感到意外（surprise 的过去式和过去分词形式）', 'He has surprised us before with his inventiveness.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'surprised');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00262', 'scissors', '/ˈsɪzəz/', 'n. 剪刀；（英橄）交叉配合，交叉移动；（跳高）剪式跳法；v. 用剪刀剪；使（腿）作剪式运动（scissor 的第三人称单数形式）', 'Snip, snip, went the scissors.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'scissors');
