INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00264', 'post office', NULL, 'n. 邮局；The Post Office（首字母大写，常与 the 连用）指国家邮政机构，在美国亦指美国邮政局', 'I went round to the post office.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'post office');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00265', 'receive', '/rɪˈsiːv/', 'v. 得到，收到；遭受，经受（特定待遇）；对……作出反应；接待，招待；接收（某人为成员）；接收，收听（信号）；（通过无线电）听到；购买，窝藏（赃物）；接（球）；领受（圣餐面包或葡萄酒）；接受（治疗）；形成（看法，印象）；容纳，承接', 'All joiners will receive a welcome pack.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'receive');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00266', 'cancer', '/ˈkænsə/', 'n. 癌症；痼疾，社会恶习；巨蟹宫，巨蟹座（Cancer）；出生于巨蟹宫时段（即6月22日至7月22日）的人（Cancer）', 'He battled cancer for four years.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'cancer');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00267', 'wig', '/wɪɡ/', 'n. 假发；<美，俚>头脑；v. <英，非正式，旧>严斥，斥责；使戴假发；激动，发狂（wig out）；【名】  （Wig）（英、瑞典）威格，（德）维希（人名）', 'She wore glasses and a wig as a disguise.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'wig');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00268', 'smart', '/smɑːt/', 'adj. 聪明的，明智的；（人）衣着得体的；整洁而漂亮的，光鲜的；耍小聪明的，不恭的；时髦的，高档的；迅速有力的，迅猛的；智能的；v. （身体部位）感到刺痛；（因批评、失败等）难过，烦恼；n. 剧痛，刺痛；痛苦，苦恼；<美，非正式>聪明，敏锐（smarts）；adv. 机敏地，整洁地，潇洒地；【名】 （Smart）（法）斯马尔，（英、德）斯马特（人名）', 'She''s just as smart as her sister.', '外研版', '七年级', '下册', 'Unit 1', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 1' AND (section IS NULL OR section = '') AND spell = 'smart');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00269', 'last but not least', NULL, '最后但同样重要的一点：表示最后提到的事物虽然排在最后，但并不是最不重要的。', 'And last but not least -it''s FREE!', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'last but not least');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00270', 'marathon', '/ˈmærəθən/', 'n. 马拉松赛跑；马拉松式的活动（或工作）；adj. 马拉松式的，漫长而累人的；v. 参加马拉松赛跑（或马拉松式的比赛、活动）', 'She came second in the marathon.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'marathon');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00271', 'line', '/laɪn/', 'n. 线，线条；（运动场地的）场界，场地线；皱纹，褶子；分界线，边界线；（思想或行为等的）界限；轮廓，外形；排，行，列；队列，队伍；一系列（类似事物），家族；各级人员；字行，诗行；（戏剧或电影的）台词，对白；<英>罚抄写（对学童的处罚）（lines）；妙语，谎话；线，绳，索；电话线（路）；热线（电话），电话服务；（铁道或公交）线路；铁轨，轨道；管线；（行进的）方向，路线；路径，渠道；（尤指公开表明的）态度，看法；方法，方式；行业，行当；种类，类型；运输公司，航运公司；防线，前线，战线；生产线，流水线；一串音符；（准备吸用的）散放成细线的毒品；赤道（the Line）；（印刷，计算机）线条的；字母底部水平线（the line）；（正规）战斗部队（the line）；v. 沿……形成行（或列、排）；给……安衬里，铺，垫；（在某物的内部）形成一层；击出（平直球）；用线条标出，布满线条（lined）；【名】 （Line）（英）莱恩，（俄）利涅（人名）', 'Everything he said is all my lines!', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'line');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00272', 'the finishing line', NULL, '终点线：在赛跑或竞赛中，表示比赛结束的线。', 'The two horses crossed the finishing line together.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'the finishing line');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00273', 'breath', '/breθ/', 'n. 呼吸，气息；一次吸入的空气；（风或气流的）一丝，丝毫；微量，迹象；一瞬间', 'I''m dying for a breath of fresh air.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'breath');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00274', 'hold your breath', NULL, '屏住呼吸：在紧张、期待或焦虑的情况下，要求某人暂时停止呼吸。', 'She said she''d do it this week, but don''t hold your breath!', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'hold your breath');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00275', 'confident', '/ˈkɒnfɪdənt/', 'adj. （性格，态度）自信的，充满信心的；坚信的，肯定的；n. <古>密友，知己', 'Marina was a confident, happy child.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'confident');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00276', 'stomachache', '/ˈstʌmək-eɪk/', 'n. 胃痛，肚子痛', 'I can''t stand this stomachache.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'stomachache');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00277', 'shall', '/ʃæl/ 或 /ʃəl/', 'aux. 将要，将会（同I和we连用，表示将来）； ……好吗？要不要……？（用于主动提供帮助、建议或询问意见）；必须，一定（表示决心、命令或指示）；可以（与“you”连用，用以告知某人能做某事或拥有想要的东西）；应，必须（用于法律、规则）；应该，就会（表示可能的结果或后果）；（用于 look forward to 和 hope 之类的动词前表示语气的委婉）', 'We shall love you whatever happens, Diana.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'shall');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00278', 'either', '/ˈaɪðə(r)/ 或 /ˈiːðə(r)/', 'conj. 或者，要么；两者都（不），既（不）；pron. （两者之中）任意一个；两者都（不）；adv. 也（不），亦（不）；而且，还；det. （两者中的）每个，各方；adj. （两者中的）每个的，各方的', 'Every member contributes to the rap, singing either solo or as part of a rap chorus.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'either');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00279', 'choice', '/tʃɔɪs/', 'n. 选择，抉择；选择的机会，选择权；选择范围，选择余地；入选者，被选中的东西；精选品；adj. 上等的，优质的；尖刻的，刻薄的；精选的', 'It hit me that I had a choice.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'choice');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00280', 'neither', '/ˈnaɪðə(r)/ 或 /ˈniːðə(r)/', 'det. 两者都不；pron. （两者中）无一个；conj. 既不……（也不……）；也不（用于否定句后，表示前句适用于所有提到的人或物）；也不（用于否定句后，强调要引出另一否定句）；adv. （否定的陈述同样适用于其他人或物）也不；（否定的陈述适用于两方面）既不……也不……；adj. 两者都不的', 'If you don''t go, neither will I.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'neither');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00281', 'cheer', '/tʃɪə/', 'n. 欢呼声，喝彩声；加油口号，加油歌；欢快，愉快的情绪；v. 欢呼，喝彩；鼓励，鼓舞；【名】 （Cheer）（英、美、加、澳）舍尔（人名）', 'A great cheer went up from the crowd.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'cheer');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00282', 'cross', '/krɒs/', 'v. 反对；杂交；在（支票）上划线（表示只能转入银行帐户）；超过，超出（极限或范围）；（表情）掠过，闪过；（基督教徒）画十字；横传；（两封来往的信）相互错过，相互交错；做斗鸡眼；穿越，横渡；交叉；n. 十字标记，十字形（或叉形）物；杂交，混合物；十字架；苦难；横传；（拳击中的）钩拳迎击；adj. 恼怒的；脾气坏的，易怒的；（街道）交叉的，十字的', 'Currency-conversion costs remain one of the biggest obstacles to cross-border trade.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'cross');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00283', 'lifelong', '/ˈlaɪflɒŋ/', 'adj. 终身的，毕生的，终生的', 'It had been her lifelong ambition.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'lifelong');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00284', 'dream', '/drɪm/', 'n. 梦；梦想；恍惚，出神；梦一般美妙的人或事物；v. 做梦，梦见；梦想，想象；做白日梦，开小差；考虑，料想；白白浪费时间，虚度光阴；adj. 理想的，完美的', 'He finally actualized his dream.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'dream');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00285', 'record', '/ˈrekɔːd/', 'n. 记录，记载；（某人或某物过去的）记录，经历；（尤指体育运动中的）最佳纪录，最好成绩；唱片；前科，犯罪记录；唱片乐曲；（计算机）记录（指作为一个单位处理的一批相关信息）；v. 记录，记载；录制；（仪器）显示，标示；（尤指体育上）获得（好成绩）；发表正式（或法律方面的）声明，申明；演奏音乐供录制；adj. 创纪录的；【名】 （Record）（美）勒科尔（人名）', 'He has a spotless record so far.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'record');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00286', 'none', '/nʌn/', 'pron. 全无；adv. 毫无，绝不（none the）；（与 too 加形容词或副词连用）绝不；n. 申初经（天主教七段祈祷时间中的一部分，通常在一天中的第九个小时 下午3点）；【名】 （None）（葡、罗）诺内（人名）', 'She has lost none of her naivety.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'none');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00287', 'finish', '/ˈfɪnɪʃ/', 'v. 完成，做好；（使）结束；消耗尽（所剩之物）；（比赛中）获得（名次）；（英式足球用语）进球；对（物件）做最后加工；杀死，歼灭；使精疲力竭；<旧>为（少女）进入上流社会做好准备；<非正式>使精疲力竭；n. 结尾，结局；（赛跑、比赛的）终点；最后精细加工；饰面，饰面材料；（葡萄酒或啤酒的）余味', 'She tried gamely to finish the race.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'finish');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00288', 'encourage', '/ɪnˈkʌrɪdʒ/', 'v. 鼓励，激励；鼓动，怂恿；刺激，促进', 'We encourage all members to strive for the highest standards.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'encourage');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00289', 'both', '/bəʊθ/', 'det. 双方，两者；pron. 两者；conj. …和…都；……和……都；adj. 两…，双…', 'Luckily, we both love football.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'both');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00290', 'sink', '/sɪŋk/', 'v. 下沉，沉没；使失败，受挫；下降，下陷；倒下，坐下；衰退，恶化；渗透，渐渐陷入；减少，降低；（声音）变低，变小；堕落，沉沦；挖掘；插入，打入；投进，滚进；投资；<英，非正式>喝（酒）；adj. <英>贫困的，贫民窟的；n. 水槽，水池；洼地，渗坑；<英，喻>位于社会贫困地区的学校或房产；<喻>藏垢的场所；<技>汇，壑；【名】 （Sink）（美、英、罗）辛克（人名）', 'He decided to scour the sink.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'sink');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00291', 'sink or swim', NULL, '生死存亡：用来形容一个人要么靠自己的努力成功，要么完全失败的情况。', 'I think athletes sink or swim depending on how they motivate themselves.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'sink or swim');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00292', 'surfer', '/ˈsɜːfə/', 'n. 冲浪运动员，乘冲浪板冲浪的人；（互联网上）冲浪者，漫游者，网迷', 'Every web surfer, in the course of his or her browsing, has been forced to stop and perform this weird little task.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'surfer');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00293', 'shark', '/ʃɑːk/', 'n. 鲨鱼；<非正式>坑蒙拐骗的人，诈骗者；鲨尾鱼；冬夜蛾；v. <英，非正式>（多指男子在社交场合中）努力追逐性伴侣', 'The shark described a circle around the shoal of fish.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'shark');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00294', 'attack', '/əˈtæk/', 'v. 批评，抨击；侵蚀，侵害；全力应对，奋力处理；袭击，攻击；（体育比赛中）进攻；n. （疾病的）突然发作；（情感的）一阵突发；（体育运动中的）进攻；袭击，攻击；批评，抨击；进攻队员；（病虫等的）损害，伤害；【名】 （Attack）（瑞典）阿塔克（人名）', 'They were caught flat-footed by the attack.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'attack');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00295', 'lose', '/luːz/', 'v. 遗失，丢失；失去（某一特性、特点、态度或信念）；被剥夺，被损坏；失去（亲人或朋友等）；输掉（比赛、战斗、争论等）；降低，减少；摆脱，甩掉（追赶者）；使不明白，使迷惑；去掉，拿掉；亏（本），赔（钱）；浪费，错过；（钟、表）走慢；【名】 （Lose）（英）洛斯，（德）洛泽（人名）', 'Don''t lose heart. Try it again.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'lose');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00296', 'surfing', '/ˈsɜːfɪŋ/', 'n. 冲浪运动；网上冲浪，网络浏览；v. 上网；冲浪；<非正式>坐在高速行驶的车辆（尤指火车）顶部（或外面）享受刺激感（surf 的现在分词）', 'He''s into surfing in a big way.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'surfing');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00297', 'compare', '/kəmˈpeə/', 'v. 比较，对比；把……比作；（与……）相比；构成（形容词或副词）的比较级和最高级；n. 比较', 'It is particularly interesting to compare the two versions.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'compare');
