INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00299', 'wave', '/weɪv/', 'v. 挥手；挥手示意；挥舞，挥动；飘扬，摆动，摇晃；使（头发）略呈波形；（威胁地）举起（某物）；n. 海浪；大海（the waves）；（活动、行为的）爆发，浪潮；涌现的人（或物）；挥手；波，波状运动；（头发的）卷曲；波浪形；（地震、爆炸的）冲击波；人浪（the wave）', 'The driver gave me a wave and a toot.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'wave');
