INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00303', 'fit', '/fɪt/', 'v. 适合，合身；适应，合得来；可容纳，装进；试穿（衣服）；和……相称，符合；为放置（于……）而设计；安置，安装（在某处）；安排时间会面，安排时间做（某事）；（疾病）发作；adj. 健康的，健壮的；合适的，适当的；合格的，胜任的；<俚>性感的；<非正式>快要，就要；n. 适合，合身；匹配，相配；痉挛，昏厥；一阵，突发；【名】 （Fit）（捷、罗）菲特（人名）', 'I work out regularly to keep fit.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'fit');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00304', 'final', '/ˈfaɪnəl/', 'adj. 最终的，结束的；(出现次序)最后的，末尾的；决定性的，不可变更的；无比的，极度的；n. 决赛；期末考试，课程终结考试；主调音；当日报纸的末版；（飞机进入着陆跑道的）最终边，第五边', 'The final decision is yours.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'final');
