INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00317', 'spirit', '/ˈspɪrɪt/', 'n. 精神，心灵；情绪，心境；勇气，意志，活力；（对团体、队伍、社会的）忠心，（群体中的）态度，精神；心态，态度；本质，精髓，基本精神；真实意义，实质；灵魂，鬼魂；具有特别品质的人物，在群体或活动中发挥特殊作用的人物；烈酒；挥发性液体（尤指用蒸馏法提炼的燃料）；神灵；圣灵（Spirit，Holy Spirit 的简称）；v. 偷偷带走，秘密弄走；鼓励，鼓舞', 'The human spirit is virtually indestructible.', '外研版', '七年级', '下册', 'Unit 2', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 2' AND (section IS NULL OR section = '') AND spell = 'spirit');
