INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00324', 'hen', '/hen/', 'n. 母鸡；雌禽；<苏格兰>（小）姑娘；用于其他鸟的名称（尤指秧鸡科水鸟）；雌龙虾（或螃蟹、鲑鱼）；【名】 （Hen）（法）昂，（波、柬）亨，（日）边（人名）', 'The hen may not be able to feed its young.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'hen');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00325', 'pot', '/pɒt/', 'n. 锅；（盛食品的）罐，瓶；壶；花盆；陶盆，陶罐，碗；一罐，一壶（的量）；（纸牌游戏的）全部赌注；凑集的资金；<非正式>大麻；<非正式>大量；大肚子；（球等的）击球入袋；幼儿用便盆；<非正式>发动机气缸；<非正式>（体育运动的）奖品，奖杯；射击；（主要用于橄榄球）射门；v. 把（植物）栽入盆中；将（食物）用密封罐煮（或储存）；射杀（动物）；击（球）入袋；制陶；<非正式>成功获得，赢得；把（电子元件，电路）密封于绝缘材料中；<英>使（小孩）坐便盆；得（分）；【名】 （Pot）（柬）布特，（捷）波特，（法）波（人名）', 'Usually, I like to eat hot pot.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'pot');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00326', 'onion', '/ˈʌnɪən/', 'n. 洋葱，洋葱头', 'I sliced up an onion.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'onion');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00327', 'pancake', '/ˈpænkeɪk/', 'n. 薄煎（烤，烙）饼；<美>（当早点吃的）厚煎饼（通常和枫糖浆一起食用）；（尤为演员化装用的）粉饼；平坠降落（同 pancake landing）；v. （飞机）平坠降落；（飞行员）驾机平坠降落；<非正式>使平展，把……压平', 'This pancake tastes delicious.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'pancake');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00328', 'porridge', '/ˈpɒrɪdʒ/', 'n. <英>燕麦粥，麦片粥；<英，非正式>关押期，监禁期', 'You can have muesli, porridge, or cereal.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'porridge');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00329', 'plain', '/pleɪn/', 'adj. 无装饰的，朴素的；单色的，无花纹的；单纯的，不掺杂的；显而易见的；（书面或口头用法）表达清楚的；直截了当的，坦率的；相貌平平的；普通的；直呼其名的；完全的；（编织）平针的；adv. 完全地，简直；明白地，不含糊地；n. （大）平原；（编织的）平针；朴实无华的东西；【名】 （Plain）（英）普莱恩，（法）普兰（人名）', 'She swapped her plain suit for a girlie dress.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'plain');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00330', 'menu', '/ˈmenjuː/', 'n. 菜单；饭菜，菜肴；（电脑屏幕上的）菜单，功能选择单', 'The menu varies with the season.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'menu');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00331', 'medicine', '/ˈmedɪsən/', 'n. 药物，药剂；医疗，医学；内科；（北美印第安人等民族所信奉的具有治疗或保护效力的）咒语，魔法；v. 用药物治疗，给……用药', 'Laughter is the best medicine.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'medicine');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00332', 'pill', '/pɪl/', 'n. 药片，药丸；（女用）口服避孕药 （the pill）；<美>（衣服或布料上的）球粒，纤维绒球； <美>讨厌的家伙；<非正式>（某些运动用的）球，弹；v. （衣服或布料）起球粒，结绒；把……制成丸剂；（使）服用药丸；<古>抢劫，掠夺；【名】 （pill）（英）皮尔（人名）', 'She had been on the pill for three years.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'pill');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00333', 'remain', '/rɪˈmeɪn/', 'v. 逗留，留下；剩余，遗留；保持不变，一直是；仍需去做（或处理）；n. 剩余（物），遗迹；遗体，残骸', 'They remain unshaken in their loyalty.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'remain');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00334', 'sandwich', '/ˈsænwɪdʒ/', 'n. 三明治，夹心面包片；<英>果酱（或奶油）夹心松蛋糕；<美>夹心饼干；三明治状物；<英>教学与实习交替培训课程；v. 插入，夹入；粘合（sandwich sth. together）；把……做成三明治', 'I ordered a beer and a sandwich.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'sandwich');
