INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00358', 'store', '/stɔː/', 'n. 商店；仓库，储存处；（事物的）储存，储备；大量，丰富；储存的物品（stores）；军需品，补给品（stores）；<英>（计算机的）存储器；重视，注重；待育肥的小羊（或小公牛、小母牛、小猪）；v. 贮存，储藏；（在头脑或计算机中）储存（事实或信息）；【名】 （Store）（德）施托雷（人名）', 'The staff in this store is very helpful.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'store');
