INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00362', 'stomach', '/ˈstʌmək/', 'n. 胃；腹部；（低级动物的）类胃器官；（反刍动物的）四胃之一；心窝，内脏； 食欲，胃口；（对有冲突、困难或不快之事的）欲望，倾向；（做困难或不愉快的事所需的）意愿，勇气，决心；（对令人反胃的东西的）承受能力；v. 忍受，承受；吃得下', 'Her stomach rumbled. She hadn''t eaten any breakfast.', '外研版', '七年级', '下册', 'Unit 3', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 3' AND (section IS NULL OR section = '') AND spell = 'stomach');
