INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00376', 'solar', '/ˈsəʊlə/', 'adj. 太阳的，和太阳有关的；（与）太阳能（有关）的；n. <英>（中世纪房屋的）屋顶室，顶层房间；【名】 （Solar）（法、英、意、西、塞、捷）索拉尔（人名）', 'The spacecraft will enable scientists to study some dark corners of the solar system.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'solar');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00377', 'media', '/ˈmiːdiə/', 'n. 新闻媒体，传媒（medium的复数形式）；媒体工作者；（尤指血管壁的）中间层（复数mediae）；浊塞音；中脉', 'The new-media industry attracts young and creative people.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'media');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00378', 'bored', '/bɔːd/', 'adj. 无聊的，厌倦的；（枪）有特定口径的；v. 使厌烦；钻；盯着看（bore 的过去式和过去分词形式）', 'Anna tried to look interested. Actually, she was bored stiff.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'bored');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00379', 'feeling', '/ˈfiːlɪŋ/', 'n. 感觉，感触；预感；看法，态度；情感，情绪；理解力，领悟力；好感，同情；知觉；氛围；品质，特点；adj. 多愁善感的，多情的；v. 感受到，体会到；觉得，相信；使人感觉……(feel 的现在分词形式)', 'I awoke feeling rested and refreshed.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'feeling');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00380', 'lift', '/lɪft/', 'v. 提起，举起；抬起（身体某一部位）；空运；解除，撤销；高兴起来，使更愉快；消散，消失；偷盗，盗窃；剽窃，抄袭；挖出，拔起（蔬菜或植物）；提高（嗓音）；提高，增加；使更有趣；（个人、运动队的）晋级；赢得（奖品或比赛）；n. 电梯，升降机；免费搭车，搭便车；鼓舞，振奋；抬，提；（空气的）升力，提升力；（飞机的）最大提升重量；高飞（投出的球触地反弹时急速上升）；后跟垫，插跟', 'He had a car and often gave me a lift home.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'lift');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00381', 'lift sb’s spirits', '—', '使某人振作起来；使某人心情好转', NULL, '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'lift sb’s spirits');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00382', 'funny', '/ˈfʌni/', 'adj. 滑稽的，有趣的；古怪的，难以解释的；微恙的，稍有不适的；生气的，不友好的；疯疯癫癫的；出故障的；可疑的，不诚实的；放肆的；n. <美>（报纸上的）滑稽连环漫画；<非正式>笑话；adv. 古怪地，奇怪地', 'She found it hilariously funny.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'funny');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00383', 'moment', '/ˈməʊmənt/', 'n. 片刻，瞬间；某一时刻；现在，目前；时机，机会；（事物发展的）关头，转折点；重大，重要；力矩；矩，动差；【名】 （Moment）（英）莫门特（人名）', 'This is the proudest moment of my life.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'moment');
