INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00386', 'number', '/ˈnʌmbə/', 'n. 数字；编号，序数；电话号码；总量，数量；大量（numbers）；一群人；（杂志的）期，号；（演出中的）一首歌，一段舞蹈；<非正式>有吸引力的人（或事物）；数，单复数；历史数据（numbers）；数字彩票（numbers）；钱数（numbers）；<俚>具有……特征的人；常说的事；v. 标号，编号；总计；包括，列入（某类）；计算，数', 'She scribbled down her phone number and pushed it into his hand.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'number');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00387', 'a number of', NULL, '若干，一些：表示不确定但超过两个的数量，介于"两个"和"很多"之间。；许多，不少：表示相当数量的人或事物，强调数量不少但又不至于特别多。', 'He sent for a number of books he admired with the idea of rereading them.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'a number of');
