INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00397', 'interest', '/ˈɪntrəst/', 'n. 兴趣，关注；吸引力，趣味；爱好；利息；利益，好处；权益，股权；利害关系，重要影响；利益集团，利益相关者；v. 使感兴趣，引起……的关注；劝说（某人）做（或参与）', 'They soon discovered a mutual interest in music.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'interest');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00398', 'butterfly', '/ˈbʌtəflaɪ/', 'n. 蝴蝶；见异思迁的人，轻浮易变的人；蝶泳，蝶泳比赛；<非正式>紧张，心慌；耳环托；v. （将食物）切成蝴蝶展翅状，使成蝶形；adj. 蝴蝶状', 'The butterfly fluttered from flower to flower.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'butterfly');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00399', 'prince', '/prɪns/', 'n. 王子，王孙；（小国的）国君，亲王；佼佼者，名家； （某些欧洲国家的）贵族；【名】 （Prince）（英、葡）普林斯，（法）普兰斯（人名）', 'A prince turns into a frog in this cartoon fairytale.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'prince');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00400', 'monster', '/ˈmɒnstə/', 'n. 怪兽，怪物；残忍的人，恶魔；小恶棍，捣蛋鬼；巨大的东西，庞然大物；难以驾驭的人，难以掌控的事物；畸形动物（或植物）；adj. 很受欢迎的；庞大的，巨大的；v. 严厉批评，斥责', 'Sarah jokingly called her "my monster."', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'monster');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00401', 'notice', '/ˈnəʊtɪs/', 'n. 注意，察觉；通告，布告；公告牌，警示牌；通知；事先声明，警告；预先通知期；剧评，书评；辞职信，搬迁通知；（报纸、杂志上的）小型广告，简短通告；警告书，说明书；v. 意识，注意；留意；正式通知；简评；客气对待；<古>提到，谈到', 'It was very perceptive of you to notice that.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'notice');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00402', 'form', '/fɔːm/', 'v. （使）出现；（使）（关系、习惯或想法）形成；构成，是……的组成部分；陶冶，培养；组织，建立；n. 表，表格；类别，种类；形状，外形；体形；（存在的）形态，形式；（尤指艺术作品或文章的）结构；体能，良好的健康状态；良好表现；词形；惯常做法，习俗；（英国的）班级，年级；不礼貌的行为；【名】 （Form）（英）福姆，（法、德）福尔姆（人名）', 'I don''t condone violence in any shape or form.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'form');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00403', 'social', '/ˈsəʊʃ(ə)l/', 'adj. 社会的；社会地位的，社会阶层的；社交的，交际的；好交际的，合群的；群居的；n. 社交聚会，联欢会；<英>社会保障（the social）', 'The conditions were ripe for social change.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'social');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00404', 'screen', '/skriːn/', 'n. 屏幕，荧光屏；银幕；电影（总称）；屏风，隔板；掩蔽物，屏障；纱窗，纱门；（医疗）化验，检查；（机动车的）挡风玻璃；（篮球、冰球等运动的）掩护；掩护部队，护航舰队；大筛子，滤网；（纱门或纱窗的）金属丝，塑料线；（印刷）网屏，网版；屏蔽器；v. 隐藏，遮蔽；庇护，包庇；检查，筛查；审查，甄别；筛选，检查排除；防止（或免受）电磁干扰；放映（影片），播放（电视节目）；分析，评估；加网印刷；【名】 （Screen）斯克林（人名）', 'The movie helped boost her screen career.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'screen');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00405', 'couch', '/kaʊtʃ/', 'n. 长沙发，长榻；诊察台；v. 表达，措辞；<文>躺下，躺卧；<古>平端（矛或枪）（准备攻击）；用下压及后压晶状体的方式治疗（白内障）；贴线缝绣；【名】 （Couch）（英）库奇（人名）', 'She slipped out of the jacket and tossed it on the couch.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'couch');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00406', 'couch potato', NULL, 'n. <非正式>懒人，电视迷，沙发土豆', 'Americans view five hours of TV each day, and while we know that spending so much time sitting passively can lead to obesity and other diseases, researchers have now quantified just how harmful being a couch potato can be.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'couch potato');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00407', 'sore', '/sɔː/', 'adj. （发炎）疼痛的，酸痛的；<美，非正式>恼火的，恼怒的；（精神上）痛苦的，困扰的；极度的，非常的；n. 伤处，痛处，疮；痛处，伤心事；【名】 （Sore）（法）索尔，（意）索雷', 'Symptoms include a sore throat.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'sore');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00408', 'neck', '/nek/', 'n. 颈项，脖子；衣领，领口；（物体的）细长部分，颈部；狭长地带，狭长水域；（动物的）颈肉；（赛马）以微弱优势（获胜），险（胜）；<非正式>在这一带，在某人的地区；<英>受到惩罚（批评）；（喻）（对责任或过失的）背负；（剖）颈；（蕨、苔藓或菌类的）茎部；v. 搂着脖子亲吻，相拥互吻；<英，非正式>一口喝下（某物，尤指酒）；（因拉伸而）变狭，变细；【名】 （Neck）（德、意、英）内克（人名）', 'She threw her arms around his neck.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'neck');
