INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00410', 'be deaf to sth', '—', '对某事充耳不闻；对某事置之不理', NULL, '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'be deaf to sth');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00411', 'balanced', '/ˈbælənst/', 'adj. 平衡的，均衡的，和谐的；（指报道、文章等）全面公正的，公允的；（指人）沉着冷静的，安定的；（会计）收支相抵的，已结平的；v. 用天平称；保持平衡，保持稳定；使平衡，使……相称；权衡；结算（balance 的过去式和过去分词）', 'It is essential that your diet is varied and balanced.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'balanced');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00412', 'jog', '/dʒɒɡ/', 'v. 慢跑；轻推，轻撞；（多指缓慢地）颠簸着行进；（上下）颠动；使颠簸；n. 慢跑锻炼；轻推；平稳的慢速；【名】 （Jog）（尼）乔格（人名）', 'I like to go for a jog after work.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'jog');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00413', 'fresh', '/freʃ/', 'adj. 新鲜的；新近的，刚经历的；新的，不同的；新颖的，独创的；清新的，清爽的；（水）淡的，无盐的；（风）凉爽的，强劲的；洁净的，亮丽的；精力充沛的；刚来的；（对异性）放肆的，无礼的；年轻可爱但缺乏经验的；<西印度>气味难闻的；adv. 刚刚，新近地', 'We sell only fresh local produce.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'fresh');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00414', 'tennis', '/ˈtenɪs/', 'n. 网球，网球运动；（Tennis）<英>坦尼斯（人名）', 'She''s really hot stuff at tennis.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'tennis');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00415', 'hike', '/haɪk/', 'n. 徒步旅行，远足；（价格、花费等的）大幅度提高，猛增；v. 远足，徒步旅行；突然增加，突然提高；拉起，提起（尤指衣物）；后传（发球）给四分卫；【名】 （Hike）（美、俄）海克（人名）', 'They went on a ten-mile hike through the forest.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'hike');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00416', 'ours', '/ˈaʊəz/', 'pron. 我们的，属于我们的；n. （Ours）（美）乌尔斯（人名）', 'He lived in a gentler age than ours.', '外研版', '七年级', '下册', 'Unit 4', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 4' AND (section IS NULL OR section = '') AND spell = 'ours');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00417', 'plateau', '/ˈplætəʊ/', 'n. 高原；（发展、增长后的）稳定期，停滞期；高原印第安人；托盘；v. （在一段时间的发展之后）趋于平稳，进入停滞期', 'We took a plane southwest across the Anatolian plateau to Cappadocia.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'plateau');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00418', 'most', '/məʊst/', 'det. （数量上）最多，最大（ much, a lot of, many 的最高级）；大多数；pron. （数量上）最多，最大（ much, a lot of, many 的最高级）；大多数；adv. 最；（程度上）最大；极其，非常；<北美，非正式>几乎；（在谈话中用于引起注意）最……；通常；（可能的）最大量；adj. 大多数的；最大程度的，最大数量的；【名】 【名】（Most）人名；（德、俄、法、芬、捷、英）莫斯特', 'We spent a most agreeable day together.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'most');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00419', 'cloud', '/klaʊd/', 'n. 云，云朵；云状物，一团；阴影，令人忧虑的事；皱眉，沮丧的表情；v. 把……搞糊涂，使难以理解；破坏，给……蒙上阴影；（使）显得阴沉；模糊不清，（使）起雾；布满云；使（房间、天空等）烟雾缭绕，使尘土飞扬；【名】 （Cloud）克劳德（人名）', 'The sun went behind a cloud.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'cloud');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00420', 'soft', '/sɒft/', 'adj. 易弯曲的，柔软的；柔滑的，细嫩的；无棱角的，轮廓不鲜明的；柔和的，悦目的；（声音）安静的，轻柔的；（雨、风等）温和的，不猛烈的；有同情心的，心肠软的；力度不够的，不严厉的；轻松的，安逸的；（水）软性的；胆小的，懦弱的；虚弱的，健康欠佳的；发软音的；（毒品）毒性不强的；（饮料）不含酒精的；（市场或经济）疲软的；<非正式>愚蠢的；（目标）易被攻击的；非严肃性的，不重要的；<方>（天气）多雨的，潮湿的，解冻的；（辐射）穿透力弱的；（洗涤剂）生物降解性的；（色情描写）非赤裸裸的，隐晦的；adv. 温柔地；<美>轻轻地；<非正式>无力地，愚蠢地；n. 柔性；柔软的东西；柔软部分', 'He had rich, soft ebony hair.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'soft');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00421', 'brightly', '/ˈbraɪtli/', 'adv. 明亮地，光亮地，生辉地；鲜艳地，鲜明地，色彩鲜明地；欢快地，喜气洋洋地', 'The sun shone brightly in a cloudless sky.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'brightly');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00422', 'sky', '/skaɪ/', 'n. 天，天空；<文>天堂，天国之力；v. <非正式>把（球）击向空中；（尤指在展览中）把（画）高挂在墙上；踢或击高空球；把桨叶翘得过高；飞涨；【名】 （Sky）（英）斯凯（人名）', 'They woke to a clear blue sky.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'sky');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00423', 'calm', '/kɑːm/', 'adj. 镇静的，沉着的；平静的，稳定的；风平浪静的；n. （精神或情感状态的）镇静，平和；宁静，安静；v. 使平静，使镇静；冷静下来，镇静下来；恢复平静，恢复正常；【名】 （Calm）（法、德）卡尔姆（人名）', 'Look, calm down! We''ll find her.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'calm');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00424', 'above', '/əˈbʌv/', 'prep. （数量或度量）在……以上，超过；在（或向）……上面；（级别或地位上）高于； （重要性、质量）超过，胜过；（因善良或诚实正直而）不至于，不屑于（做某事）；（声音）比……更响亮，盖过；不受……影响，免于；（重要性、质量）超过，胜过；adv. （级别或地位上）高于；在（或向）上面，在（或向）较高处；高于，超出（特定数量、比率或标准）；上文，前文；adj. 前文述及的，上述的；n. 上文提及之事，前文所提之事（the above）', 'The two candidates stood head and shoulders above the rest.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'above');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00425', 'express', '/ɪkˈspres/', 'v. 表达，表露；表现，体现；（用数学方法）表示；压榨，挤压出（空气或液体）；特快发运；n. 快车；快递；初速大的猎枪；专使；捷运公司；adj. 快递的，特快的；明确的；特意的；adv. 用快递寄送', 'How can I ever express my thanks to you for all you''ve done?', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'express');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00426', 'grassland', '/ˈɡræslaɪnd/', 'n. 草原，草地，牧草地', 'Tropical forest is felled to make way for grassland.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'grassland');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00427', 'field', '/fiːld/', 'n. 田地，田野；专业，领域；现场，实地；体育场；全体参赛者；矿场，油田；战场；视野；（物理）场；信息栏，字段；外场员，防守队；盾面，底；v. 组建，派出；担任守方；接（球），守（球）；处理，应付（问题或电话）；adj. 实地的，野外的；（军事装备）轻便机动的，战役用的；（比赛）田赛的；【名】 （Field）（英、法、德、葡）菲尔德（人名）', 'When I''m on the soccer field, I''m at my happiest.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'field');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00428', 'than', '/ðæn/', 'conj. （用以引出比较的第二部分）比；（比较数量、距离等）多于；（表示一事紧跟另一事发生）就；除……（外）；prep. （用以引出比较的第二部分）比；（比较数量、距离等）多于；（表示一事紧跟另一事发生）就；除……（外）；n. （Than）（越）丹（人名）', 'Children learn faster than adults.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'than');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00429', 'few', '/fjuː/', 'det. 一些，几个；很少，不多，几乎没有；pron. 一些人（或物）；很少的人（或物）；adj. 少数的；很少（的），几乎没有（的）；n. （尤指享有某种机遇等的）少数派，少数（the few） ；参加过不列颠之战的少数几个英国皇家空军飞行员（the Few）；【名】 （Few）（英）菲尤（人名）', 'The seeds will sprout in a few days.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'few');
