INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00447', 'lie', '/laɪ/', 'v. 平躺，平卧；位于，坐落在；存在，在于；处于，保持（某种状态）；（尤用于墓碑上的文字中）长眠；（比赛时）名列，排名；撒谎，编造谎言；（物体）平放在……上，平放着；朝……方向；造成假象，不可靠；（尤指不快或困难之事）将发生，在等待；（光、云、雾等）存在，展现；（诉讼，控告，索赔）可受理，可立案；n. 方向，位置；谎言，谎话；（动物的）穴，（鸟的）巢；【名】 （Lie）（罗、挪、瑞典）利，（中）李（普通话·威妥玛）（人名）', 'Father, I cannot lie to you.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'lie');
