INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00454', 'snake', '/sneɪk/', 'n. 蛇；阴险狡诈的人；管道疏通器；蛇形浮动汇率制（the snake）；v. 蛇行，蜿蜒前进；拉（重物）', 'The snake writhed and hissed.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'snake');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00455', 'only', '/ˈəʊnli/', 'adv. 只，只有；仅在……情况下（或地方等）；只是，不过（表示不重要、不严重等）；（强调数量少或时间段）仅仅，才；不早于，直到……才；（除此之外别无可为）只能；（用于说明事情的恶果）只会；不料，竟然；只能（希望或愿望等）；（强调行动恰当）完全，真正；刚刚（强调某事刚发生）；险些没，差点没；adj. 仅有的，唯一的；最好的，最适合的；独生的；conj. <非正式>不过，但是；<非正式>要不是，若非', 'We sell only fresh local produce.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'only');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00456', 'however', '/haʊˈevə/', 'adv. 然而，可是，不过；无论如何；（用于表示惊讶）究竟怎样；……左右，……上下；conj. 不管怎样，无论如何；然而，可是', 'There is little doubt, however, that things will improve in the not too distant future.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'however');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00457', 'wood', '/wʊd/', 'n. 木材，木料，木头；树林，林地；（高尔夫）木头球棒，木棒；木制酒桶；木棒挥击；（滚木球戏中所用重心略偏的）圆球；（保龄球戏的）木瓶；上天保佑（表示希望继续走好运）；adj. 木制的；用来切割或加工木材的；用木材做燃料的；v. 收集木材；植林于；给……添加木柴；【名】 （Wood）（英、法、西、葡、阿拉伯）伍德（人名）', 'I found wood carving satisfying.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'wood');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00458', 'disappear', '/ˌdɪsəˈpɪə/', 'v. 消失，不见；失踪，丢失；不复存在，灭绝', 'They watched the bus disappear into the distance.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'disappear');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00459', 'if', '/ɪf/', 'conj. 如果，假如，要是；每当，无论何时；即使，虽然，尽管；（用于间接问句或礼貌问询）是否；〔if only〕要是…多好；〔as if〕好像，仿佛；〔if not〕如果不；即便不；或许不；（常与 can、could、may、might 等情态动词连用）表示婉转请求；（if it isn''t…）这不是……吗；n. 条件，设想；不确定的情况（常用复数 ifs）', 'I''d be glad if you could help me.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'if');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00460', 'glacier', '/ˈɡleɪsiə/', 'n. 冰河，冰川', 'Do you think we can glide down this glacier?', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'glacier');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00461', 'climate', '/ˈklaɪmət/', 'n. 气候；气候区；氛围，局势', 'These plants flourish in a damp climate.', '外研版', '七年级', '下册', 'Unit 5', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 5' AND (section IS NULL OR section = '') AND spell = 'climate');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00462', 'airport', '/ˈeəpɔːt/', 'n. 机场，航空站 （港）；空旅通俗读物', 'Will you meet me at the airport?', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'airport');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00463', 'burn', '/bɜːn/', 'v. 燃烧，消耗；烧坏，烧毁，烧焦；晒伤，晒黑；火辣辣地发痛，发烫；发光，发亮；激怒；刻录；渴望；迅速移动；n. 灼伤，烧伤，烧痕；肌肉酸痛感；小溪；【名】 （Burn）（英）伯恩（人名）', 'Ford vowed that he would sooner burn his factory to the ground than build a single vehicle for war purposes.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'burn');
