INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00465', 'deep', '/diːp/', 'adj. 深的，厚的；纵深的，宽的；有……深的；成……排的；深呼吸的；（声音）低沉的；深色的；酣睡的；严重的；（感情）深厚的；透彻的，深刻的；深奥的；全神贯注，深陷；（人）深沉的；（目光）锐利的，深邃的；靠近场地边界的；神秘的；<美>大幅下降的；<美>有很多优秀选手的；adv. 深深地，至深处；有……深；成……排地；靠近场地边界地；n. <文>海洋（the deep）；海洋深处（deeps）；<文>中间部分（the deep）；（板球）外围场地（the deep）；【名】 （Deep）迪普（人名）', 'His voice was deep and mellow.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'deep');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00466', 'lemon', '/ˈlemən/', 'n. 柠檬；柠檬汁；柠檬色；柠檬树（=lemon tree）；<非正式>蹩脚的人（或物）；adj. 柠檬色的；【名】 （Lemon）（美）莱蒙（人名）', 'I plucked a lemon from the tree.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'lemon');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00467', 'reply', '/rɪˈplaɪ/', 'v. 回答，答复；（以行动）作出回应，回击；（在体育比赛中）以得分回应，回敬；n. （口头或书面）回答，答复；回应，作出反应；<英>（比赛）一方得分（进球）但对方未得分（进球）；<法律>（原告对被告抗辩的）驳复，答辩', 'His reply was not repeatable.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'reply');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00468', 'mouthful', '/ˈmaʊθfʊl/', 'n. 一口，一满口（的量）；<非正式>又长又拗口的词（或短语）；意味深长的话，重要的话', 'He ate his meal slowly, savouring every mouthful.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'mouthful');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00469', 'surprisingly', '/səˈpraɪzɪŋli/', 'adv. 惊人地，出人意料地', 'She looked surprisingly well.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'surprisingly');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00470', 'mask', '/mɑːsk/', 'n. 面罩，口罩；防毒面具，呼吸面罩；面膜；假面具，假面；伪装，掩饰；表情，面容；遮盖物，遮蔽物；（古希腊和罗马演员佩戴的）人头面具；遮光板，遮光片；（制造微电路用）模板；（蜻蜓幼虫）脸盖；v. 掩饰，伪装，隐瞒；盖住（气味、味道、声音等）；遮盖；戴面具', 'She whipped the mask off her face.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'mask');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00471', 'normal', '/ˈnɔːm(ə)l/', 'adj. 正常的，标准的；（身心）健康的，（人）普通的；（线或线性特征）正交的，垂直的；（盐溶液）与血液的盐浓度相同的；正（断层）的；平常的，通常的；n. 常态，通常标准；<非正式>正常人，循规蹈矩者；法线，正交；【名】 （Normal）（德）诺马尔（人名）', 'It''s perfectly normal to feel like this.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'normal');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00472', 'ancient', '/ˈeɪnʃ(ə)nt/', 'adj. 古代的，远古的；古老的，年代久远的；老的，老掉牙的；n. （尤指埃及、希腊和罗马的）古代人；<古>老头', 'The temple is one of the glories of ancient Greece.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'ancient');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00473', 'further', '/ˈfɜːðə/', 'adv. 更远地，再往前地；进一步；此外，而且；adj. 更多的，进一步的；（距离上）更远的，较远的；v. 促进，推进', 'She took the new job to further her career.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'further');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00474', 'look forward to', NULL, '期待：指对未来的某事或某人充满期待和期望。；期望：指对未来的某事或某人抱有希望和期望。', 'I look forward to hearing from you.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'look forward to');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00475', 'trip', '/trɪp/', 'n. （尤指短程往返的）旅行，旅游；出门，出行；绊倒；<非正式>（吸毒所致的）幻觉，迷幻感受；<美，非正式>让人开心的奇人，奇妙有趣的经历；强烈的情感体验；（赛跑等比赛的）赛程；自我放纵的态度（或行动）；（机器、电路的）开关；<古>轻捷的脚步；<古>错误；v. 绊，绊倒；脚步轻快地走（或跑、跳舞）；（尤指意外地）触动（开关）；（部分电路）自动断开；<非正式>（服用毒品后）产生幻觉；（字句）轻松自如地吐出；作短程旅行；竖起（帆桁等）；（航海）起（锚）；【名】 （Trip）（美）特里普（人名）', 'Your trip must have been fun!', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'trip');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00476', 'general', '/ˈdʒen(ə)rəl/', 'adj. 总体的，普遍的；一般的，常规的；大致的，大概的；综合的，广泛的；首席的，总管的；n. 上将，将军；半军事化管理的宗教组织（如耶稣会修士、多明我会修士或救世军）的领袖；<古>大众，公众；【名】 （General）（英）杰纳勒尔（人名）', 'He was effusive in his praise for the general.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'general');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00477', 'in general', NULL, '通常，一般来说；总体上，就整体而言', 'I think what screen dance will do, though, is heighten awareness of dance in general.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'in general');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00478', 'curious', '/ˈkjʊəriəs/', 'adj. 好奇的，求知欲强的；稀奇的，不寻常的；爱挑剔的', 'Steve was intensely curious about the world I came from.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'curious');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00479', 'local', '/ˈləʊk(ə)l/', 'adj. 当地的，地方的；局部的；（汽车或火车）每站都停的，慢的；（计算机）局域的；（食品或饮料）低热量的；n. 当地人，本地人；<英>住处附近的酒吧；<美>（工会的）地方分会；慢车，市内公交车；<俚>炒股散户；本地新闻；局部', 'We sell only fresh local produce.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'local');
