INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00482', 'comfortable', '/ˈkʌmftəbl/', 'adj. 令人舒适的；感到舒服的，安逸的；自信的，自在的；富裕的，宽裕的；满意的；易取胜的，轻松领先的；（病、伤后）疼痛减缓的，状况良好的；足够的；n. <美>温暖的盖被', 'It''s such a comfortable bed.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'comfortable');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00483', 'other', '/ˈʌðə/', 'adj. （表示与已知的人或事物不同）别的，另外的；（表示在与已知的人或事物同一类中）别的，另外的；（两个中）另一的；（一组人或事物中）其余的；（用于列举之后）其他的；对面的，相反方向的；（泛指）别（人）的，他（人）的；最近的，前不久的；pron. （表示与已知的人或事物不同）另外；（表示在与已知的人或事物同一类中）另外；（两个中）另一个（the other）；其余的人（或事物）（the others）；（用于列举之后）其他；对面，相反方向（the other）；<非正式>性交（the other）；v. 将……看作异类，以异类对待', 'He easily outpaced the other runners.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'other');
