INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00487', 'painting', '/ˈpeɪntɪŋ/', 'n. （一幅）画，绘画作品；绘画创作，绘画；粉刷，上油漆；v. 给……上油漆（或涂料）；（用颜料）绘，画；往（指甲、嘴唇等上）施化妆品（paint 的现在分词形式）；【名】 （Painting）（英）佩因廷（人名）', 'He derived great pleasure from painting.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'painting');
INSERT INTO t_english_word (id, spell, phonetic, meaning, example_sentence, version, grade, term, unit, section) SELECT 'ewjn00488', 'roller coaster', NULL, 'n. 过山车，云霄飞车：游乐场中的高架轨道游乐设施，轨道设有急转弯和陡坡，供人乘坐体验；（比喻）起伏不定的经历：指经历、局势或情绪在短时间内突然而剧烈地变化。', 'I''ve been on an emotional roller coaster since I''ve been here.', '外研版', '七年级', '下册', 'Unit 6', NULL FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_english_word WHERE version = '外研版' AND grade = '七年级' AND term = '下册' AND unit = 'Unit 6' AND (section IS NULL OR section = '') AND spell = 'roller coaster');
