INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'jc-q-019-030', 'jc-repo-019', '30', 'Passage: Six Chi Lane is a famous story in China. Once, two families lived next to each other. When one family built a wall, they argued about the land between them. The wall became a dividing line. One family wrote to their relative in the capital for help. The relative wrote back, saying, "Why not make the wall three chi wider?" The family did so. The other family was moved and also made their wall wider. Now there is a narrow lane between the two houses. It is called Six Chi Lane. Why did the family write to their relative?', 'Radio', '{"id": "jc-q-019-030", "title": "Passage: Six Chi Lane is a famous story in China. Once, two families lived next to each other. When one family built a wall, they argued about the land between them. The wall became a dividing line. One family wrote to their relative in the capital for help. The relative wrote back, saying, \"Why not make the wall three chi wider?\" The family did so. The other family was moved and also made their wall wider. Now there is a narrow lane between the two houses. It is called Six Chi Lane. Why did the family write to their relative?", "type": "Radio", "attribute": {"subject": "英语", "difficulty": "medium", "chapter": "Unit 2", "section": "同步练习", "knowledgePoint": ["细节理解"], "examAnalysis": "原文 they argued about the land", "examAnswerMode": "onlyOne"}, "children": [{"id": "a", "title": "To ask for money", "attribute": {}}, {"id": "b", "title": "To ask about the wall problem", "attribute": {"examCorrectAnswer": "b"}}, {"id": "c", "title": "To say hello", "attribute": {}}, {"id": "d", "title": "To send a gift", "attribute": {}}]}', 'exam', '同步练习', '["外研版", "八年级", "上册", "Unit 2"]', NULL, NULL, 0, 0, CURRENT_TIMESTAMP, '