INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'jc-q-034-029', 'jc-repo-034', '29', 'Confucius was a great teacher and thinker in ancient China. He lived about 2,500 years ago. He had many students. His ideas are still influential today, and people still read his books. He taught us to be wise and to learn from others. Many people describe him more as a teacher than a writer. 1. Confucius was a great ______.', 'Radio', '{"id": "jc-q-034-029", "title": "Confucius was a great teacher and thinker in ancient China. He lived about 2,500 years ago. He had many students. His ideas are still influential today, and people still read his books. He taught us to be wise and to learn from others. Many people describe him more as a teacher than a writer. 1. Confucius was a great ______.", "type": "Radio", "attribute": {"subject": "英语", "difficulty": "easy", "chapter": "Module 7 Great books", "section": "Unit 1", "knowledgePoint": ["细节理解"], "examAnalysis": "文章第一句即说明Confucius was a great teacher and thinker。", "examAnswerMode": "onlyOne"}, "children": [{"id": "a", "title": "worker and doctor", "attribute": {}}, {"id": "b", "title": "teacher and thinker", "attribute": {"examCorrectAnswer": "b"}}, {"id": "c", "title": "writer and farmer", "attribute": {}}, {"id": "d", "title": "singer and dancer", "attribute": {}}]}', 'exam', '同步练习', '["外研版", "九年级", "上册", "Module 7 Great books"]', NULL, NULL, 0, 0, CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Module 7 Great books', 'Unit 1', '["细节理解"]', 'easy', '九年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'jc-q-034-029');
