INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'jc-q-035-029', 'jc-repo-035', '29', 'Liu Xiang is a famous Chinese sportsman. He was good at hurdling. At first, he was encouraged to train for the high jump. Later, he changed to hurdling. In 2004, he won the first place in the Athens Olympics. His races were recorded and he was compared with the world''s best sports stars. He suffered from a foot injury later, but Chinese people take pride in him. 1. What sport was Liu Xiang good at?', 'Radio', '{"id": "jc-q-035-029", "title": "Liu Xiang is a famous Chinese sportsman. He was good at hurdling. At first, he was encouraged to train for the high jump. Later, he changed to hurdling. In 2004, he won the first place in the Athens Olympics. His races were recorded and he was compared with the world''s best sports stars. He suffered from a foot injury later, but Chinese people take pride in him. 1. What sport was Liu Xiang good at?", "type": "Radio", "attribute": {"subject": "英语", "difficulty": "easy", "chapter": "Module 8 Sports life", "section": "Unit 2", "knowledgePoint": ["细节理解"], "examAnalysis": "文章第二句He was good at hurdling。", "examAnswerMode": "onlyOne"}, "children": [{"id": "a", "title": "Running.", "attribute": {}}, {"id": "b", "title": "Hurdling.", "attribute": {"examCorrectAnswer": "b"}}, {"id": "c", "title": "High jump.", "attribute": {}}, {"id": "d", "title": "Swimming.", "attribute": {}}]}', 'exam', '同步练习', '["外研版", "九年级", "上册", "Module 8 Sports life"]', NULL, NULL, 0, 0, CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Module 8 Sports life', 'Unit 2', '["细节理解"]', 'easy', '九年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'jc-q-035-029');
