INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'jc-q-037-029', 'jc-repo-037', '29', 'Last summer, I went to Australia with my parents. I have some photos that I took there. In the first photo, you can see a kangaroo. We saw kangaroos and sheep on a farm. We also went surfing on the beach. According to my diary, the weather was sunny and warm. The view was so beautiful that we were surprised at it. It was a magical trip. 1. Where did the writer go last summer?', 'Radio', '{"id": "jc-q-037-029", "title": "Last summer, I went to Australia with my parents. I have some photos that I took there. In the first photo, you can see a kangaroo. We saw kangaroos and sheep on a farm. We also went surfing on the beach. According to my diary, the weather was sunny and warm. The view was so beautiful that we were surprised at it. It was a magical trip. 1. Where did the writer go last summer?", "type": "Radio", "attribute": {"subject": "英语", "difficulty": "easy", "chapter": "Module 10 Australia", "section": "Unit 1", "knowledgePoint": ["细节理解"], "examAnalysis": "文章第一句I went to Australia with my parents。", "examAnswerMode": "onlyOne"}, "children": [{"id": "a", "title": "China.", "attribute": {}}, {"id": "b", "title": "Australia.", "attribute": {"examCorrectAnswer": "b"}}, {"id": "c", "title": "America.", "attribute": {}}, {"id": "d", "title": "Japan.", "attribute": {}}]}', 'exam', '同步练习', '["外研版", "九年级", "上册", "Module 10 Australia"]', NULL, NULL, 0, 0, CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Module 10 Australia', 'Unit 1', '["细节理解"]', 'easy', '九年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'jc-q-037-029');
