INSERT INTO t_template (id, repo_id, serial_no, name, question_type, template, mode, category, tag, priority, preview_url, shared, is_deleted, create_at, create_by, update_at, update_by, subject, chapter, section, knowledge_point, difficulty, grade) SELECT 'jc-q-039-032', 'jc-repo-039', '32', 'There are three words for green life: reduce, reuse and recycle. Reduce means use less. For example, use less paper. Reuse means use things again. Cloth bags can be used many times. Recycle means change old things into new things. We divide the waste into things to recycle, such as paper, glass and plastic. Do not throw away bottles that can be recycled. 1. What does ''reduce'' mean?', 'Radio', '{"id": "jc-q-039-032", "title": "There are three words for green life: reduce, reuse and recycle. Reduce means use less. For example, use less paper. Reuse means use things again. Cloth bags can be used many times. Recycle means change old things into new things. We divide the waste into things to recycle, such as paper, glass and plastic. Do not throw away bottles that can be recycled. 1. What does ''reduce'' mean?", "type": "Radio", "attribute": {"subject": "英语", "difficulty": "easy", "chapter": "Module 12 Save our world", "section": "Unit 2", "knowledgePoint": ["细节理解"], "examAnalysis": "文章Reduce means use less。", "examAnswerMode": "onlyOne"}, "children": [{"id": "a", "title": "Use more.", "attribute": {}}, {"id": "b", "title": "Use less.", "attribute": {"examCorrectAnswer": "b"}}, {"id": "c", "title": "Use nothing.", "attribute": {}}, {"id": "d", "title": "Use again.", "attribute": {}}]}', 'exam', '同步练习', '["外研版", "九年级", "上册", "Module 12 Save our world"]', NULL, NULL, 0, 0, CURRENT_TIMESTAMP, '1457995481966747649', NULL, NULL, '英语', 'Module 12 Save our world', 'Unit 2', '["细节理解"]', 'easy', '九年级' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM t_template WHERE id = 'jc-q-039-032');
