  school varchar(100) DEFAULT NULL COMMENT '学校',
  campus varchar(50) DEFAULT NULL COMMENT '校区(本迭代仅占位，业务逻辑后续迭代)',
  extra text DEFAULT NULL COMMENT '扩展预留字段(JSON，前端不展示，供后续数据分析)',
