-- 英语知识点学习状态（三态 + 攻克计数 + 角度使用，供单词/句式/语法三模块共用）
-- 与 t_english_word_book / t_english_sentence_book / t_english_grammar_book 并存：
--   *_book 管熟练度与复习时间；本表管熟练/一般/陌生三态、连续正确计数与输出题达标计数。
CREATE TABLE IF NOT EXISTS t_english_learning_state (
  id varchar(64) NOT NULL,
  user_id varchar(64) NOT NULL,
  module varchar(16) NOT NULL COMMENT '模块：word/sentence/grammar',
  knowledge_id varchar(191) NOT NULL COMMENT '知识点ID：单词ID/句子ID/语法点ID',
  state varchar(16) DEFAULT 'unfamiliar' COMMENT '掌握状态：familiar/ordinary/unfamiliar',
  consecutive_correct int DEFAULT 0 COMMENT '连续答对计数（攻克判定用，答错清零）',
  consecutive_wrong int DEFAULT 0 COMMENT '连续答错计数（薄弱判定用，答对清零）',
  output_correct_count int DEFAULT 0 COMMENT '输出类题型答对次数（默写/填空/组句/改写）',
  last_angle varchar(32) COMMENT '最近一次作答的考察角度',
  memory_total int DEFAULT 0 COMMENT '记忆阶段答题总数',
  memory_correct int DEFAULT 0 COMMENT '记忆阶段答对总数',
  practice_total int DEFAULT 0 COMMENT '练习阶段答题总数',
  practice_correct int DEFAULT 0 COMMENT '练习阶段答对总数',
  use_total int DEFAULT 0 COMMENT '运用阶段答题总数',
  use_correct int DEFAULT 0 COMMENT '运用阶段答对总数',
  weak_flag tinyint DEFAULT 0 COMMENT '是否在薄弱池',
  weak_reason varchar(64) COMMENT '薄弱原因：consecutive_wrong/accuracy/output_error',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uk_user_module_kp (user_id, module, knowledge_id)
);
CREATE INDEX IF NOT EXISTS idx_english_learning_state_weak ON t_english_learning_state (user_id, module, weak_flag);

-- 英语考察角度使用记录（防止同一知识点连续用同一角度，形成「换汤不换药」）
CREATE TABLE IF NOT EXISTS t_english_exam_angle_use (
  id varchar(64) NOT NULL,
  user_id varchar(64) NOT NULL,
  module varchar(16) NOT NULL COMMENT '模块：word/sentence/grammar',
  knowledge_id varchar(191) NOT NULL COMMENT '知识点ID',
  angle varchar(32) NOT NULL COMMENT '考察角度编码',
  use_count int DEFAULT 1 COMMENT '使用次数',
  last_use_at timestamp COMMENT '最近使用时间',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uk_user_module_kp_angle (user_id, module, knowledge_id, angle)
);

-- 用户语法本（熟练度 + 复习调度，供英语语法练习与复习）
CREATE TABLE IF NOT EXISTS t_english_grammar_book (
  id varchar(64) NOT NULL,
  user_id varchar(64) NOT NULL,
  grammar_id varchar(64) NOT NULL,
  familiarity tinyint DEFAULT 0 COMMENT '熟练度 0-未学习 1-生疏 2-熟悉 3-熟练 4-精通',
  correct_count int DEFAULT 0 COMMENT '累计答对次数',
  wrong_count int DEFAULT 0 COMMENT '累计答错次数',
  last_review_time timestamp COMMENT '最近复习时间',
  next_review_time timestamp COMMENT '下次复习时间',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uk_user_grammar (user_id, grammar_id)
);

CREATE TABLE IF NOT EXISTS t_english_learning_log (
  id varchar(64) NOT NULL,
  user_id varchar(64) NOT NULL,
  type varchar(16) NOT NULL COMMENT '类型 word/grammar',
  content_id varchar(64) NOT NULL,
  duration int COMMENT '学习时长 (秒)',
  correct_count int COMMENT '正确数',
  created_at timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_english_log_user ON t_english_learning_log (user_id, created_at);

-- 英语错题消灭记录表（学员重做正确后落库，作为「已消灭」依据，复习聚合错题时剔除）
CREATE TABLE IF NOT EXISTS t_english_wrong_redo (
  id varchar(64) NOT NULL,
  student_id varchar(64) NOT NULL COMMENT '学员ID',
  question_id varchar(64) NOT NULL COMMENT '已消灭的题目ID',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  create_by varchar(256) DEFAULT NULL COMMENT '创建人',
  update_at timestamp DEFAULT NULL COMMENT '更新时间',
  update_by varchar(256) DEFAULT NULL COMMENT '更新人',
  is_deleted tinyint DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_english_wrong_redo ON t_english_wrong_redo (student_id, question_id);

-- 学员学习记录表（学员督学功能）
CREATE TABLE IF NOT EXISTS t_student_record (
  id varchar(64) NOT NULL,
  student_id varchar(64) DEFAULT NULL COMMENT '学员 ID',
  current_location varchar(255) DEFAULT NULL COMMENT '当前学习位置（chapter/ID, section/ID, knowledge/ID, exercise/ID）',
  last_active_time varchar(32) DEFAULT NULL COMMENT '最后活跃时间',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_at timestamp DEFAULT NULL COMMENT '更新时间',
  is_deleted tinyint DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (id)
);

-- 学员任务分配表
CREATE TABLE IF NOT EXISTS t_student_task (
  id varchar(64) NOT NULL,
  school_id varchar(64) DEFAULT NULL COMMENT '学校 ID',
  student_id varchar(64) DEFAULT NULL COMMENT '学员 ID',
  task_content varchar(500) DEFAULT NULL COMMENT '任务内容（文本）',
  task_type varchar(32) DEFAULT NULL COMMENT '任务类型（chapter/section/knowledge/exercise）',
  task_target varchar(64) DEFAULT NULL COMMENT '任务目标 ID（章节/小节/知识点/习题 ID）',
  status varchar(16) DEFAULT 'pending' COMMENT '状态（pending-待完成，completed-已完成）',
  create_by varchar(64) DEFAULT NULL COMMENT '创建人（教师 ID）',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  update_at timestamp DEFAULT NULL COMMENT '更新时间',
  is_deleted tinyint DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (id)
);

-- AI 单元内容包（AI 为某 版本/年级/单元 生成的整套学习内容，供人工审核后同步入词库/语法库）
CREATE TABLE IF NOT EXISTS t_english_ai_pack (
  id varchar(64) NOT NULL,
  version varchar(32) COMMENT '教材版本',
  grade varchar(16) COMMENT '年级',
  unit varchar(32) COMMENT '单元',
  topic varchar(256) COMMENT '主题',
  title varchar(256) COMMENT '内容包标题',
  content text COMMENT 'AI 生成的整套内容 JSON',
  word_count int DEFAULT 0 COMMENT '单词数量',
  created_at timestamp DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);

-- 补齐 BaseModel 审计列（与既有表结构一致）
ALTER TABLE t_english_ai_pack ADD COLUMN IF NOT EXISTS create_at timestamp DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE t_english_ai_pack ADD COLUMN IF NOT EXISTS create_by varchar(256);
ALTER TABLE t_english_ai_pack ADD COLUMN IF NOT EXISTS update_at timestamp;
ALTER TABLE t_english_ai_pack ADD COLUMN IF NOT EXISTS update_by varchar(256);
ALTER TABLE t_english_ai_pack ADD COLUMN IF NOT EXISTS is_deleted tinyint DEFAULT 0;
UPDATE t_english_ai_pack SET create_at = created_at WHERE create_at IS NULL AND created_at IS NOT NULL;

-- 英语单元情景练习内容包（预生成固化：单词情景 + 句式情景，按 版本/年级/册别/单元 唯一）
CREATE TABLE IF NOT EXISTS t_english_scenario_pack (
  id varchar(64) NOT NULL,
  version varchar(32) COMMENT '教材版本',
  grade varchar(16) COMMENT '年级',
  term varchar(16) COMMENT '学期（上册/下册）',
  unit varchar(32) COMMENT '单元',
  word_content text COMMENT '单词情景分组 JSON',
  word_count int DEFAULT 0 COMMENT '单词情景场景总数',
  pattern_content text COMMENT '句式情景分组 JSON',
  pattern_count int DEFAULT 0 COMMENT '句式情景情景总数',
  reading_content text COMMENT '单元阅读理解 JSON',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  create_by varchar(256) COMMENT '创建人',
  update_at timestamp COMMENT '更新时间',
  update_by varchar(256) COMMENT '更新人',
  is_deleted tinyint DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (id)
);

-- 补齐 BaseModel 审计列（幂等，兼容历史表结构）
ALTER TABLE t_english_scenario_pack ADD COLUMN IF NOT EXISTS create_at timestamp DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE t_english_scenario_pack ADD COLUMN IF NOT EXISTS create_by varchar(256);
ALTER TABLE t_english_scenario_pack ADD COLUMN IF NOT EXISTS update_at timestamp;
ALTER TABLE t_english_scenario_pack ADD COLUMN IF NOT EXISTS update_by varchar(256);
ALTER TABLE t_english_scenario_pack ADD COLUMN IF NOT EXISTS is_deleted tinyint DEFAULT 0;
ALTER TABLE t_english_scenario_pack ADD COLUMN IF NOT EXISTS reading_content text;

-- 英语单元句子同步练习内容包（预生成固化：多题型句子练习，按 版本/年级/册别/单元 唯一）
CREATE TABLE IF NOT EXISTS t_english_sentence_pack (
  id varchar(64) NOT NULL,
  version varchar(32) COMMENT '教材版本',
  grade varchar(16) COMMENT '年级',
  term varchar(16) COMMENT '学期（上册/下册）',
  unit varchar(32) COMMENT '单元',
  content text COMMENT '题目 JSON 数组',
  count int DEFAULT 0 COMMENT '题目总数',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  create_by varchar(256) COMMENT '创建人',
  update_at timestamp COMMENT '更新时间',
  update_by varchar(256) COMMENT '更新人',
  is_deleted tinyint DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (id)
);

-- 补齐 BaseModel 审计列（幂等，兼容历史表结构）
ALTER TABLE t_english_sentence_pack ADD COLUMN IF NOT EXISTS create_at timestamp DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE t_english_sentence_pack ADD COLUMN IF NOT EXISTS create_by varchar(256);
ALTER TABLE t_english_sentence_pack ADD COLUMN IF NOT EXISTS update_at timestamp;
ALTER TABLE t_english_sentence_pack ADD COLUMN IF NOT EXISTS update_by varchar(256);
ALTER TABLE t_english_sentence_pack ADD COLUMN IF NOT EXISTS is_deleted tinyint DEFAULT 0;

-- 英语题目打标标签（按内容键绑定句子包/情景包中的真实考题，供薄弱点组卷按知识点与难度取题）
CREATE TABLE IF NOT EXISTS t_english_content_tag (
  id varchar(64) NOT NULL,
  module varchar(16) NOT NULL COMMENT '模块：句子/单词/句式',
  content_key varchar(255) NOT NULL COMMENT '内容唯一键（句子=来源ID+题型，情景=单元+分组+标题+轮次）',
  version varchar(32) COMMENT '教材版本',
  grade varchar(16) COMMENT '年级',
  term varchar(16) COMMENT '学期（上册/下册）',
  unit varchar(64) COMMENT '单元',
  group_no varchar(32) COMMENT '情景分组序号',
  scene_title varchar(128) COMMENT '情景标题',
  turn_no int COMMENT '轮次',
  question_type varchar(32) COMMENT '题型',
  knowledge_point varchar(255) COMMENT '打标知识点（诊断最小单位）',
  language_skill varchar(16) COMMENT '语言技能：词汇/语法/语用',
  cognitive_level varchar(16) COMMENT '认知层级：记忆/理解/应用',
  distractor_strength varchar(32) COMMENT '干扰项强度：无/单一陷阱/多重陷阱',
  difficulty_seed varchar(8) COMMENT '难度初标：D1~D5',
  is_exam_question tinyint DEFAULT 1 COMMENT '是否考题：1 是 0 否',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  create_by varchar(256) COMMENT '创建人',
  update_at timestamp COMMENT '更新时间',
  update_by varchar(256) COMMENT '更新人',
  is_deleted tinyint DEFAULT 0 COMMENT '是否删除',
  PRIMARY KEY (id),
  UNIQUE (content_key)
);
CREATE INDEX IF NOT EXISTS idx_english_content_tag_query ON t_english_content_tag (module, unit, difficulty_seed);

-- 英语课文跟读篇章（一篇课文一条记录，逐句中英文以 JSON 保存）
CREATE TABLE IF NOT EXISTS t_english_read_aloud (
  id varchar(64) NOT NULL,
  version varchar(32) COMMENT '教材版本',
  grade varchar(16) COMMENT '年级',
  term varchar(16) COMMENT '学期（上册/下册）',
  unit varchar(64) COMMENT '单元',
  title varchar(255) COMMENT '课文标题/板块名',
  source varchar(512) COMMENT '教材版本与来源说明',
  sort int DEFAULT 0 COMMENT '单元内排序',
  content text COMMENT '逐句内容 JSON：[{en, zh}]',
  line_count int DEFAULT 0 COMMENT '句子数量',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE (version, grade, term, unit, title)
);
CREATE INDEX IF NOT EXISTS idx_english_read_aloud_unit ON t_english_read_aloud (version, grade, term, unit, sort);

-- 英语单元目录（词库/句库单元 + 自定义排序/占位单元）
CREATE TABLE IF NOT EXISTS t_english_unit (
  id varchar(64) NOT NULL,
  version varchar(32) COMMENT '教材版本',
  grade varchar(16) COMMENT '年级',
  term varchar(16) COMMENT '学期（上册/下册）',
  unit varchar(128) COMMENT '单元',
  sort int DEFAULT 0 COMMENT '排序',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uk_unit (version, grade, term, unit)
);

-- 英语小节目录（单元下属的小节，词库/句库/语法共用）
CREATE TABLE IF NOT EXISTS t_english_section (
  id varchar(64) NOT NULL,
  version varchar(32) COMMENT '教材版本',
  grade varchar(16) COMMENT '年级',
  term varchar(16) COMMENT '学期（上册/下册）',
  unit varchar(128) COMMENT '单元',
  section varchar(128) COMMENT '小节',
  sort int DEFAULT 0 COMMENT '排序',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uk_section (version, grade, term, unit, section)
);

-- 英语句库（独立于单词，可单独维护与导入）
CREATE TABLE IF NOT EXISTS t_english_sentence (
  id varchar(64) NOT NULL,
  en text NOT NULL COMMENT '英文句子',
  zh varchar(512) COMMENT '中文释义',
  audio_url varchar(512) COMMENT '音频 URL',
  version varchar(32) COMMENT '教材版本',
  grade varchar(16) COMMENT '年级',
  term varchar(16) COMMENT '学期（上册/下册）',
  unit varchar(128) COMMENT '单元',
  section varchar(128) COMMENT '小节',
  sort int DEFAULT 0 COMMENT '单元内排序',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_english_sentence_unit ON t_english_sentence (version, grade, term, unit, sort);

-- 句库新增小节（幂等）
ALTER TABLE t_english_sentence ADD COLUMN IF NOT EXISTS section varchar(128);

-- 用户句子本（熟练度 + 复习调度）
CREATE TABLE IF NOT EXISTS t_english_sentence_book (
  id varchar(64) NOT NULL,
  user_id varchar(64) NOT NULL,
  sentence_id varchar(64) NOT NULL,
  familiarity tinyint DEFAULT 0 COMMENT '熟练度 0-未学习 1-生疏 2-熟悉 3-熟练 4-精通',
  correct_count int DEFAULT 0 COMMENT '累计答对次数',
  wrong_count int DEFAULT 0 COMMENT '累计答错次数',
  last_review_time timestamp COMMENT '最近复习时间',
  next_review_time timestamp COMMENT '下次复习时间',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uk_user_sentence (user_id, sentence_id)
);

-- ============================================================
-- 学员积分·学币体系（双轨数值账本）
-- 学海积分：终身、全学科、只作荣誉评价；学习币：分学科、单学期上限 10000、只作商品兑换
-- ============================================================
CREATE TABLE IF NOT EXISTS t_user_points (
  id varchar(64) NOT NULL,
  user_id varchar(64) NOT NULL COMMENT '学员ID',
  points int DEFAULT 0 COMMENT '累计学海积分(终身/全学科)',
  title_level int DEFAULT 1 COMMENT '头衔等级1-5',
  title_name varchar(32) DEFAULT '初探者' COMMENT '头衔名称',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_user_points ON t_user_points (user_id);

CREATE TABLE IF NOT EXISTS t_subject_semester (
  id varchar(64) NOT NULL,
  user_id varchar(64) NOT NULL COMMENT '学员ID',
  subject_id varchar(64) NOT NULL COMMENT '学科ID(t_subject.id)',
  semester varchar(16) NOT NULL COMMENT '学期键，如 2026-1',
  coins int DEFAULT 0 COMMENT '本学期该学科学习币(0..10000)',
  reached_limit tinyint DEFAULT 0 COMMENT '是否已达单科上限',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_subject_semester ON t_subject_semester (user_id, subject_id, semester);

CREATE TABLE IF NOT EXISTS t_user_learning_record (
  id varchar(64) NOT NULL,
  user_id varchar(64) NOT NULL COMMENT '学员ID',
  subject_id varchar(64) DEFAULT NULL COMMENT '学科ID，可空',
  knowledge_point_id varchar(64) DEFAULT NULL COMMENT '知识点ID，可空',
  section_id varchar(64) DEFAULT NULL COMMENT '小节ID，可空',
  action_type varchar(32) NOT NULL COMMENT '学习行为类型',
  ref_id varchar(64) DEFAULT NULL COMMENT '业务关联ID(练习会话/日期等)',
  coins int DEFAULT 0 COMMENT '本次发放学习币(上限裁剪后)',
  points int DEFAULT 0 COMMENT '本次发放学海积分',
  semester varchar(16) DEFAULT NULL COMMENT '学期键',
  learned_at timestamp DEFAULT CURRENT_TIMESTAMP COMMENT '行为发生时间',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_ulr_user_action ON t_user_learning_record (user_id, action_type, knowledge_point_id, learned_at);
CREATE INDEX IF NOT EXISTS idx_ulr_ref ON t_user_learning_record (user_id, action_type, ref_id);
-- 学期幂等兜底：同一学员同一行为同一 ref_id 只允许一条记录
CREATE UNIQUE INDEX IF NOT EXISTS uk_ulr_user_action_ref ON t_user_learning_record (user_id, action_type, ref_id);

-- ============================================================
-- 学员薄弱点·学习结果评价体系
-- ============================================================
CREATE TABLE IF NOT EXISTS t_user_knowledge_progress (
  id varchar(64) NOT NULL,
  user_id varchar(64) NOT NULL COMMENT '学员ID',
  subject_id varchar(64) DEFAULT NULL COMMENT '学科ID',
  version_id varchar(64) DEFAULT NULL COMMENT '教材版本ID',
  chapter_id varchar(64) DEFAULT NULL COMMENT '章节ID',
  knowledge_point_id varchar(64) NOT NULL COMMENT '知识点ID',
  mastery int DEFAULT 0 COMMENT '掌握度0-100',
  level varchar(16) DEFAULT NULL COMMENT '评级标签',
  times int DEFAULT 0 COMMENT '练习会话次数',
  total_count int DEFAULT 0 COMMENT '累计题数',
  correct_count int DEFAULT 0 COMMENT '累计正确题数',
  last_correct_rate int DEFAULT 0 COMMENT '最近一次正确率0-100',
  last_practice_at timestamp NULL DEFAULT NULL COMMENT '最近练习时间',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_kp_progress ON t_user_knowledge_progress (user_id, subject_id, version_id, knowledge_point_id);

CREATE TABLE IF NOT EXISTS t_user_weak_knowledge (
  id varchar(64) NOT NULL,
  user_id varchar(64) NOT NULL COMMENT '学员ID',
  subject_id varchar(64) DEFAULT NULL COMMENT '学科ID',
  knowledge_point_id varchar(64) NOT NULL COMMENT '知识点ID',
  status varchar(16) DEFAULT 'active' COMMENT 'active/conquered',
  conquer_times int DEFAULT 0 COMMENT '攻克次数',
  first_weak_at timestamp NULL DEFAULT NULL COMMENT '首次薄弱时间',
  conquered_at timestamp NULL DEFAULT NULL COMMENT '最近攻克时间',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_weak ON t_user_weak_knowledge (user_id, subject_id, knowledge_point_id);
CREATE INDEX IF NOT EXISTS idx_weak_status ON t_user_weak_knowledge (user_id, status);

-- ============================================================
-- 精准破弱模型（WPB）：检测基线 + 薄弱点变化事件流
-- ============================================================
CREATE TABLE IF NOT EXISTS t_detect_record (
  id varchar(64) NOT NULL,
  student_id varchar(64) NOT NULL COMMENT '学员ID',
  subject_id varchar(64) DEFAULT NULL COMMENT '学科ID',
  subject_name varchar(64) DEFAULT NULL COMMENT '学科名称快照',
  grade varchar(32) DEFAULT NULL COMMENT '年级快照',
  term varchar(16) DEFAULT NULL COMMENT '册别快照',
  semester varchar(16) DEFAULT NULL COMMENT '学期键',
  detect_type varchar(16) DEFAULT 'STAGE' COMMENT 'PRE/STAGE',
  is_baseline tinyint DEFAULT 0 COMMENT '是否成长基线',
  baseline_key varchar(192) DEFAULT NULL COMMENT '基线唯一键 学员:学科:学期，仅PRE写入',
  chapter_ids text DEFAULT NULL COMMENT '勾选章节ID JSON数组',
  chapter_names text DEFAULT NULL COMMENT '勾选章节名称 JSON数组',
  question_count int DEFAULT 0 COMMENT '组卷题量',
  total int DEFAULT 0 COMMENT '实际判分题数',
  correct_count int DEFAULT 0 COMMENT '正确题数',
  accuracy int DEFAULT 0 COMMENT '正确率0-100',
  duration_ms bigint DEFAULT 0 COMMENT '作答耗时(ms)',
  weak_points text DEFAULT NULL COMMENT '薄弱点JSON数组',
  details text DEFAULT NULL COMMENT '逐题结果JSON数组',
  client_token varchar(64) DEFAULT NULL COMMENT '客户端幂等令牌',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_detect_record ON t_detect_record (student_id, subject_id, semester, create_at);
-- 基线唯一：仅 PRE 行写 baseline_key（非空），STAGE 行为 NULL，唯一索引下多行 NULL 互不冲突
CREATE UNIQUE INDEX IF NOT EXISTS uk_detect_baseline ON t_detect_record (student_id, subject_id, semester, baseline_key);
CREATE UNIQUE INDEX IF NOT EXISTS uk_detect_client ON t_detect_record (student_id, client_token);

CREATE TABLE IF NOT EXISTS t_weak_point_event (
  id varchar(64) NOT NULL,
  student_id varchar(64) NOT NULL COMMENT '学员ID',
  subject_id varchar(64) DEFAULT NULL COMMENT '学科ID',
  knowledge_point_id varchar(64) NOT NULL COMMENT '知识点ID',
  section_id varchar(64) DEFAULT NULL COMMENT '小节ID',
  chapter_id varchar(64) DEFAULT NULL COMMENT '章节ID',
  event_type varchar(16) NOT NULL COMMENT 'discovered/conquered/reopened',
  mastery int DEFAULT 0 COMMENT '事件发生时掌握度0-100',
  source varchar(16) DEFAULT NULL COMMENT 'detect/practice/correction',
  ref_id varchar(128) DEFAULT NULL COMMENT '业务来源ID(幂等键)',
  kp_name varchar(255) DEFAULT NULL COMMENT '知识点名称快照',
  section_name varchar(255) DEFAULT NULL COMMENT '小节名称快照',
  chapter_name varchar(255) DEFAULT NULL COMMENT '章节名称快照',
  occurred_at timestamp DEFAULT CURRENT_TIMESTAMP COMMENT '发生时间',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_weak_event ON t_weak_point_event (student_id, knowledge_point_id, event_type, ref_id);
CREATE INDEX IF NOT EXISTS idx_weak_event ON t_weak_point_event (student_id, subject_id, occurred_at);

-- ============================================================
-- 学员成长档案：学习轨迹事件流水
-- ============================================================
CREATE TABLE IF NOT EXISTS t_learning_growth (
  id varchar(64) NOT NULL,
  student_id varchar(64) NOT NULL COMMENT '学员ID',
  subject_id varchar(64) DEFAULT NULL COMMENT '学科ID',
  subject_name varchar(64) DEFAULT NULL COMMENT '学科名称快照',
  event_type varchar(16) DEFAULT NULL COMMENT 'PRACTICE/DETECT/GRAMMAR/CLASS',
  source_type varchar(16) DEFAULT NULL COMMENT 'practice/detect/grammar/archive_record',
  source_id varchar(128) DEFAULT NULL COMMENT '业务对象ID(幂等键)',
  event_date varchar(10) DEFAULT NULL COMMENT '发生日期 yyyy-MM-dd',
  occurred_at timestamp DEFAULT CURRENT_TIMESTAMP COMMENT '发生时间',
  chapter_id varchar(64) DEFAULT NULL COMMENT '章节/单元ID',
  chapter varchar(128) DEFAULT NULL COMMENT '章节/单元名称',
  knowledge_points text DEFAULT NULL COMMENT '知识点名称JSON数组',
  question_count int DEFAULT 0 COMMENT '题量',
  correct_count int DEFAULT 0 COMMENT '正确数',
  accuracy int DEFAULT 0 COMMENT '正确率0-100',
  duration_ms bigint DEFAULT 0 COMMENT '时长(ms)',
  points int DEFAULT 0 COMMENT '积分',
  coins int DEFAULT 0 COMMENT '学习币',
  title varchar(256) DEFAULT NULL COMMENT '事件标题',
  remark varchar(512) DEFAULT NULL COMMENT '备注',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_growth_source ON t_learning_growth (student_id, source_type, source_id);
CREATE INDEX IF NOT EXISTS idx_growth_timeline ON t_learning_growth (student_id, subject_id, occurred_at);

-- ============================================================
-- 学员档案：基线与报告元数据列 + 学员+学期+学科唯一
-- （ALTER 已移至 t_student_archive 建表语句之后，避免引用未创建的表）
-- ============================================================

-- 错题订正标记 + 手动发币学科归集
ALTER TABLE t_practice_detail ADD COLUMN IF NOT EXISTS corrected tinyint DEFAULT 0 COMMENT '错题是否已订正';
ALTER TABLE t_practice_detail ADD COLUMN IF NOT EXISTS corrected_at timestamp NULL DEFAULT NULL COMMENT '订正时间';
ALTER TABLE t_student_coin ADD COLUMN IF NOT EXISTS subject_id varchar(64) DEFAULT NULL COMMENT '学科ID(手动发币按学科归集)';
ALTER TABLE t_user_knowledge_progress ADD COLUMN IF NOT EXISTS recent_rates varchar(128) DEFAULT NULL COMMENT '最近5次练习正确率(逗号分隔,新到旧)';

-- 学习会话（学员端心跳续会话，累计时长触发学习总结）
CREATE TABLE IF NOT EXISTS t_study_session (
  id varchar(64) NOT NULL,
  student_id varchar(64) NOT NULL COMMENT '学员ID',
  subject_id varchar(64) DEFAULT NULL COMMENT '学科ID',
  session_date varchar(10) NOT NULL COMMENT '会话日期 yyyy-MM-dd',
  start_at timestamp NULL DEFAULT NULL COMMENT '会话开始时间',
  last_heartbeat_at timestamp NULL DEFAULT NULL COMMENT '最近心跳时间',
  end_at timestamp NULL DEFAULT NULL COMMENT '会话结束时间',
  duration_ms bigint DEFAULT 0 COMMENT '累计时长(毫秒)',
  status varchar(20) DEFAULT 'active' COMMENT 'active/ended',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_study_session_student_date ON t_study_session (student_id, session_date);

-- 当日学习总结（AI 生成，按学员+日期唯一，更新覆盖）
CREATE TABLE IF NOT EXISTS t_study_summary (
  id varchar(64) NOT NULL,
  student_id varchar(64) NOT NULL COMMENT '学员ID',
  summary_date varchar(10) NOT NULL COMMENT '总结日期 yyyy-MM-dd',
  session_id varchar(64) DEFAULT NULL COMMENT '触发总结的会话ID',
  content text COMMENT '总结正文',
  model varchar(100) DEFAULT NULL COMMENT '生成模型，规则模板为 rule',
  status varchar(20) DEFAULT 'success' COMMENT 'success/failed',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_study_summary_student_date ON t_study_summary (student_id, summary_date);

-- 学员档案（按学员 + 学期唯一；承载目标规划表/承诺书/初始档案快照/学期报告）
CREATE TABLE IF NOT EXISTS t_student_archive (
  id varchar(64) NOT NULL,
  student_id varchar(64) NOT NULL COMMENT '学员ID',
  student_no varchar(64) DEFAULT NULL COMMENT '学号快照',
  student_name varchar(64) DEFAULT NULL COMMENT '姓名快照',
  school_year varchar(20) DEFAULT NULL COMMENT '学年，如 2026-2027',
  semester varchar(20) DEFAULT NULL COMMENT '学期键，如 2026-1',
  term_label varchar(20) DEFAULT NULL COMMENT '学期名称，如 第一学期',
  subject_id varchar(64) DEFAULT NULL COMMENT '学科ID（空表示全科档案）',
  teacher_id varchar(64) DEFAULT NULL COMMENT '负责老师ID',
  teacher_name varchar(64) DEFAULT NULL COMMENT '负责老师姓名',
  status varchar(20) DEFAULT 'draft' COMMENT 'draft/active/closed',
  profile_snapshot text COMMENT '初始档案快照(JSON：薄弱知识点/掌握度)',
  goal_plan text COMMENT '本学期目标规划表正文',
  promise text COMMENT '学员承诺书正文',
  report_content text COMMENT '学期报告正文',
  report_status varchar(20) DEFAULT 'none' COMMENT 'none/draft/final',
  remark text COMMENT '备注',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_student_archive_student ON t_student_archive (student_id, semester);

-- 学员档案基线与报告元数据列（建表后补齐，兼容早期已建表）
ALTER TABLE t_student_archive ADD COLUMN IF NOT EXISTS baseline_detect_id varchar(64) DEFAULT NULL COMMENT '基线检测记录ID';
ALTER TABLE t_student_archive ADD COLUMN IF NOT EXISTS baseline_at timestamp NULL DEFAULT NULL COMMENT '基线定格时间';
ALTER TABLE t_student_archive ADD COLUMN IF NOT EXISTS report_model varchar(64) DEFAULT NULL COMMENT '报告生成模型(ai模型名或rule)';
ALTER TABLE t_student_archive ADD COLUMN IF NOT EXISTS report_generated_at timestamp DEFAULT NULL COMMENT '报告生成时间';
CREATE UNIQUE INDEX IF NOT EXISTS uk_student_archive ON t_student_archive (student_id, semester, subject_id);

-- 学员上课记录/学习日志（每次课一条，含系统草稿与老师定稿）
CREATE TABLE IF NOT EXISTS t_student_archive_record (
  id varchar(64) NOT NULL,
  archive_id varchar(64) NOT NULL COMMENT '档案ID',
  student_id varchar(64) NOT NULL COMMENT '学员ID',
  record_date varchar(10) NOT NULL COMMENT '上课日期 yyyy-MM-dd',
  subject_id varchar(64) DEFAULT NULL COMMENT '学科ID',
  title varchar(200) DEFAULT NULL COMMENT '本次主题',
  study_summary text COMMENT '当日学习情况(系统自动/老师编辑)',
  solved_problems text COMMENT '解决的问题',
  strengthened_kps text COMMENT '强化的知识点',
  weaknesses text COMMENT '暴露的弱点',
  homework text COMMENT '课后作业/任务',
  teacher_comment text COMMENT '教师寄语',
  duration_minutes int DEFAULT 0 COMMENT '本次时长(分钟)',
  points int DEFAULT 0 COMMENT '获得积分',
  coins int DEFAULT 0 COMMENT '获得学习币',
  source varchar(20) DEFAULT 'manual' COMMENT 'auto/manual',
  status varchar(20) DEFAULT 'draft' COMMENT 'draft/final',
  sort int DEFAULT 0,
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE INDEX IF NOT EXISTS idx_student_archive_record ON t_student_archive_record (archive_id, record_date);

-- 小节通关记录（每学员每小节唯一，保留历史最佳正确率/星级/首次通关）
CREATE TABLE IF NOT EXISTS t_section_pass (
  id varchar(64) NOT NULL,
  user_id varchar(64) DEFAULT NULL COMMENT '学员ID',
  section_id varchar(64) DEFAULT NULL COMMENT '小节ID(t_section.id)',
  best_rate int DEFAULT 0 COMMENT '历史最佳正确率(百分比)',
  best_score double DEFAULT 0 COMMENT '历史最佳得分',
  stars tinyint DEFAULT 0 COMMENT '历史最佳星级0-5',
  passed tinyint DEFAULT 0 COMMENT '是否已通关',
  attempt_count int DEFAULT 0 COMMENT '交卷次数',
  first_pass_at timestamp NULL DEFAULT NULL COMMENT '首次通关时间',
  last_attempt_at timestamp NULL DEFAULT NULL COMMENT '最近交卷时间',
  create_at timestamp DEFAULT CURRENT_TIMESTAMP,
  create_by varchar(256),
  update_at timestamp NULL DEFAULT NULL,
  update_by varchar(256),
  is_deleted tinyint DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_section_pass ON t_section_pass (user_id, section_id);
CREATE INDEX IF NOT EXISTS idx_section_pass_section ON t_section_pass (section_id);


