-- 外研版英语六年级下册（Unit 1-10，源表为旧版 Module 1-10）种子（自动生成，幂等；来源：外研版英语_单元总表_单词句型语法习题 (1).xlsx）
-- 6下单元名统一：Module N -> Unit N（幂等迁移，兼容历史库；新库由 Unit 版 INSERT 建立）
UPDATE t_english_word SET unit = REPLACE(unit, 'Module ', 'Unit ') WHERE version='外研版' AND grade='六年级' AND term='下册' AND unit LIKE 'Module %';
UPDATE t_english_sentence SET unit = REPLACE(unit, 'Module ', 'Unit ') WHERE version='外研版' AND grade='六年级' AND term='下册' AND unit LIKE 'Module %';
UPDATE t_english_grammar SET unit = REPLACE(unit, 'Module ', 'Unit ') WHERE version='外研版' AND grade='六年级' AND term='下册' AND unit LIKE 'Module %';
UPDATE t_english_unit SET unit = REPLACE(unit, 'Module ', 'Unit ') WHERE version='外研版' AND grade='六年级' AND term='下册' AND unit LIKE 'Module %';
UPDATE t_chapter SET name = REPLACE(name, 'Module ', 'Unit ') WHERE version='外研版' AND grade='六年级' AND term='下册' AND name LIKE 'Module %';
UPDATE t_section SET content = REPLACE(content, 'Module ', 'Unit ') WHERE grade='六年级' AND term='下册' AND content LIKE '%Module %';
UPDATE t_repo SET name = REPLACE(name, 'Module ', 'Unit '), description = REPLACE(description, 'Module ', 'Unit '), tag = REPLACE(tag, 'Module ', 'Unit ') WHERE subject='英语' AND grade='六年级' AND (name LIKE '%Module %' OR tag LIKE '%Module %');
UPDATE t_knowledge_point SET name = REPLACE(name, 'Module ', 'Unit '), content = REPLACE(content, 'Module ', 'Unit ') WHERE grade='六年级' AND term='下册' AND (name LIKE '%Module %' OR content LIKE '%Module %');
UPDATE t_template SET chapter = REPLACE(chapter, 'Module ', 'Unit '), knowledge_point = REPLACE(knowledge_point, 'Module ', 'Unit '), tag = REPLACE(tag, 'Module ', 'Unit '), template = REPLACE(template, 'Module ', 'Unit ') WHERE grade='六年级' AND (chapter LIKE 'Module %' OR knowledge_point LIKE '%Module %' OR tag LIKE '%Module %' OR template LIKE '%Module %');

